window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0223", [{"word":"quantitative analysis","ipa_uk":"/ˌkwɒntɪˈteɪtɪv əˈnæləsɪs/","ipa_us":"/ˌkwɑːntəˈteɪtɪv əˈnæləsɪs/","definition_zh":"定量分析；数量分析；以测量数值与统计方法研究问题；化学中测定成分含量；量化评估与建模","definition_en":"the study of a question by measuring quantities and working with numerical data, including statistical, chemical and economic forms","core_image":"天平读数落进表格，一列数字被画成曲线，结论从曲线里长出来","scene":"实验室把水样分成十二份，逐份称重、记录浓度，再把数字画成曲线。The team ran a quantitative analysis of the river samples before the dam was approved.","sceneCN":"这里指用测量数值研究样本（第 1 个义项：以测量数值为基础的分析）；句意为在大坝获批之前，团队对河水样本做了一次定量分析。场景要点：分装的水样、天平、记录表、逐点连成的浓度曲线。","pos":[{"tag":"n.","zh":"定量分析；数量分析"}],"collocations":[{"phrase":"run a quantitative analysis","zh":"做定量分析"},{"phrase":"quantitative analysis of data","zh":"对数据的定量分析"},{"phrase":"quantitative chemical analysis","zh":"化学定量分析"},{"phrase":"quantitative analysis software","zh":"定量分析软件"},{"phrase":"quantitative analysis of risk","zh":"风险量化分析"},{"phrase":"a quantitative analysis shows","zh":"定量分析显示"}],"forms":[{"label":"单数形式","form":"quantitative analysis"},{"label":"复数形式","form":"quantitative analyses"},{"label":"修饰形容词","form":"quantitative"},{"label":"核心名词","form":"analysis"},{"label":"核心名词复数","form":"analyses"}],"derivatives":[{"word":"quantitatively","pos":"adv.","zh":"由修饰形容词加副词词尾构成，义为「定量地、就数量而言」"},{"word":"quantify","pos":"v.","zh":"由同一拉丁词干构成动词，义为「量化、用数量表示」"},{"word":"quantification","pos":"n.","zh":"由量化动词加表示动作结果的名词尾构成，义为「量化」"},{"word":"quantity","pos":"n.","zh":"由同一拉丁词根构成名词，义为「数量」"},{"word":"quantitative analyst","pos":"n.","zh":"由该短语缩合而成的职业称谓，义为「量化分析师」"}],"senses":[{"no":"01","title":"Analysis built on measured numbers","titleCN":"以测量数值为基础的分析","definition":"the study of a question by measuring quantities and reasoning from numerical data rather than impressions","definitionCN":"通过测量数量、依据数值数据推理来研究问题，而不是凭印象判断","example":"The lab ran a quantitative analysis of the soil before the field was sold.","exampleCN":"这块地出售之前，实验室对土壤做了一次定量分析。","why":"Quantus in Latin asks how much, so the first thing this analysis does is put a number on its object.","whyCN":"拉丁语 quantus 问的是「多少」，因此这种分析做的第一件事就是给对象配上一个数字。"},{"no":"02","title":"The statistical procedure itself","titleCN":"统计分析流程本身","definition":"the set of statistical operations, such as sampling, regression and significance testing, applied to a body of data","definitionCN":"对一组数据施行的一整套统计操作，如抽样、回归与显著性检验","example":"Their quantitative analysis used a regression model on ten years of shipping records.","exampleCN":"他们的定量分析对十年的航运记录使用了回归模型。","why":"Once data are numbers, the methods that compare them become part of the phrase, not a separate step.","whyCN":"数据一旦成为数字，比较这些数字的方法也就并入这个短语，而不再是一道单独的工序。"},{"no":"03","title":"Chemical determination of amounts","titleCN":"化学中测定成分含量","definition":"the branch of chemistry that establishes how much of each substance a sample contains","definitionCN":"化学中测定样本含多少某种物质的分支","example":"Quantitative analysis showed 0.3 milligrams of lead per litre of water.","exampleCN":"定量分析显示每升水含零点三毫克铅。","why":"Chemistry split the phrase in two: qualitative work says what is present, quantitative work says how much.","whyCN":"化学把这个短语一分为二：定性工作说明有什么，定量工作说明有多少。"},{"no":"04","title":"Measurement of performance or risk","titleCN":"绩效与风险的量化评估","definition":"the conversion of performance, cost or risk into indicators that can be compared and tracked","definitionCN":"把绩效、成本或风险换算成可以比较与追踪的指标","example":"A quantitative analysis of accident risk guided the new speed limit.","exampleCN":"对事故风险的量化评估为新的限速规定提供了依据。","why":"Risk, cost and performance have no common scale until they are rated, and rating is exactly what the quantitative half does.","whyCN":"风险、成本与绩效本来没有共同尺度，只有打分才有，而这正是「定量」那一半做的事。"},{"no":"05","title":"The numerical section of a report","titleCN":"报告中的量化部分","definition":"the part of a study or report that carries figures, tables and calculations, as distinct from discussion","definitionCN":"研究报告里承载数字、表格与计算的部分，与讨论部分相区别","example":"The quantitative analysis fills the first half of the report; the interviews come later.","exampleCN":"定量分析占了报告的前一半，访谈材料放在后面。","why":"A report is divided by what it contains, and the half made of numbers borrows the name of the method.","whyCN":"报告按内容划分，由数字构成的那一半就借用了方法的名称。"},{"no":"06","title":"Analysis of amount rather than kind","titleCN":"只问多少、不问性质的分析","definition":"the contrastive use of the phrase when it is set against qualitative work that describes qualities and reasons","definitionCN":"与描述性质与原因的定性研究相对照时的用法","example":"Where qualitative work asks why, quantitative analysis asks how many and how much.","exampleCN":"定性研究问的是为什么，定量分析问的是多少。","why":"The adjective carries the contrast inside it: quantity on one side, quality on the other.","whyCN":"形容词本身就把对照装了进来：一边是数量，另一边是性质。"},{"no":"07","title":"Economic and financial modelling","titleCN":"经济与金融建模","definition":"the use of mathematical models and market data to estimate returns, prices or policy effects","definitionCN":"用数学模型与市场数据估算收益、价格或政策效果","example":"The bank's quantitative analysis projected a small fall in demand next quarter.","exampleCN":"该银行的定量分析预计下季度需求会小幅下降。","why":"Finance took the statistical half of the phrase and made it a modelling practice with its own tools.","whyCN":"金融业取走了这个短语中统计的那一半，把它做成了一门有专门工具的建模实践。"},{"no":"08","title":"Quantified comparison across cases","titleCN":"跨案例的量化比较","definition":"the comparison of groups, sites or periods by turning their features into figures on one scale","definitionCN":"把不同群体、地点或时期的特征换算到同一尺度上再作比较","example":"A quantitative analysis across forty schools ranked them by attendance and spending.","exampleCN":"对四十所学校做的定量分析按出勤率与经费把它们排出次序。","why":"Comparison needs a common unit, and measuring supplies one, so the phrase covers ranking as well as describing.","whyCN":"比较需要共同单位，测量正好提供单位，因此这个短语既指描述也指排序。"},{"no":"09","title":"Data-based assessment before a decision","titleCN":"决策前的数据评估","definition":"the practical use of numerical evidence to support or block a decision","definitionCN":"用数值证据支持或阻止一项决定的实际用法","example":"The board asked for a quantitative analysis before approving the new line.","exampleCN":"董事会要求先做定量分析，再批准新的生产线。","why":"A decision needs one common measure to weigh alternatives, so numerical evidence takes the phrase's name in boardrooms.","whyCN":"决定需要一种共同尺度来衡量各种选择，因此在会议室里，数值证据就用了这个短语的名字。"}],"etymology":{"intro":{"en":"Quantitative comes from Latin quantus, how much, through the medieval adjective quantitativus; analysis comes from Greek analysis, a loosening up, built on ana- up and lysis a loosening. English joined the two in the nineteenth century for work that measures rather than describes.","cn":"quantitative 来自拉丁语 quantus「多少」，经中世纪拉丁语形容词 quantitativus 而来；analysis 来自希腊语 analysis「解开」，由 ana-「向上、彻底」与 lysis「松开」构成。英语在十九世纪把两者合起来，指以测量而非描述为主的工作。"},"items":[{"era":"LATIN QUANTUS","en":"Quantus asked how much or how great, and it stands behind the whole English family of quantity words.","cn":"这个词问的是「多少、多大」，英语里整族「数量」词都由它而来。"},{"era":"MEDIEVAL LATIN QUANTITATIVUS","en":"Schoolmen formed the adjective to mean concerned with amount, giving the phrase its first half.","cn":"中世纪的学者造出这个形容词，意为「与数量有关的」，为这个短语提供了前半。"},{"era":"GREEK ANALYSIS","en":"Analysis named a loosening up, and Greek geometry used it for resolving a problem into its parts.","cn":"analysis 本指「松开」，希腊几何学用它表示把问题拆解成各个部分。"},{"era":"ENGLISH, 19TH CENTURY","en":"The two words were joined in English scientific writing; the first use of the full phrase is uncertain and is usually dated only to the nineteenth century.","cn":"这两个词在英语科学写作中合成短语；该完整短语的首次使用年代不确定，通常只笼统归到十九世纪。"},{"era":"CHEMISTRY","en":"The phrase became the name of the chemical branch that determines how much of a substance a sample holds.","cn":"这个短语成为化学分支的名称，专门测定样本含有多少某物质。"},{"era":"STATISTICS AND FINANCE","en":"Sampling, regression and modelling widened it to any numerical study of data, and finance gave it a modelling trade.","cn":"抽样、回归与建模把它扩展到一切针对数据的数值研究，金融业又给了它一门建模行当。"}]},"similar":{"note":{"en":"The first group shares the measuring vocabulary; the second names the neighbouring kinds of study.","cn":"第一组共享「测量」这套词汇；第二组是与它相邻的各种研究名目。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quantitatively","ipa":"/ˌkwɒntɪˈteɪtɪvli/","tag":"same root","definition":"The adverb of the same adjective, meaning in terms of amount.","definitionCN":"同一形容词变来的副词，指「就数量而言」。"},{"word":"quantify","ipa":"/ˈkwɒntɪfaɪ/","tag":"same root","definition":"The verb for turning something into measurable amounts.","definitionCN":"指把事物换算成可测量的数量。"},{"word":"quantity","ipa":"/ˈkwɒntəti/","tag":"same root","definition":"The noun for an amount or number of something.","definitionCN":"指某物的数量。"},{"word":"qualitative analysis","ipa":"/ˌkwɒlɪˈteɪtɪv əˈnæləsɪs/","tag":"opposite","definition":"Study of what a substance or case is like rather than how much of it there is.","definitionCN":"研究物质或案例的性质，而不是数量。"},{"word":"analysis","ipa":"/əˈnæləsɪs/","tag":"same root","definition":"The act of breaking a problem into its parts.","definitionCN":"指把问题拆成各个部分的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"statistical analysis","ipa":"/stəˈtɪstɪkl əˈnæləsɪs/","tag":"near meaning","definition":"Analysis that applies probability and sampling methods to data.","definitionCN":"对数据运用概率与抽样方法的分析。"},{"word":"measurement","ipa":"/ˈmeʒəmənt/","tag":"near meaning","definition":"The act of establishing size, amount or degree with an instrument.","definitionCN":"用仪器确定大小、数量或程度。"},{"word":"data analysis","ipa":"/ˈdeɪtə əˈnæləsɪs/","tag":"near meaning","definition":"The general term for examining collected figures, of which the quantitative kind is one form.","definitionCN":"检查所收集数字的泛称，定量分析是其中一种形式。"},{"word":"assessment","ipa":"/əˈsesmənt/","tag":"near meaning","definition":"A judgement of value, risk or performance, often using numbers but not always.","definitionCN":"对价值、风险或表现的判断，常用数字但不限于数字。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin question behind the word, its real family and its real laboratory phrases.","cn":"正常联想使用这个词背后的拉丁提问、真实同族词与真实实验室说法。"},"normal":[{"en":"Quantus is Latin for how much, so quantitative work always answers a how-much question.","cn":"quantus 在拉丁语里是「多少」，所以定量工作回答的永远是「多少」的问题。"},{"en":"Quantity, quantify and quantitative share one stem: if you can count it, the family fits.","cn":"数量、量化与定量的词干相同：只要能数，就归这一族。"},{"en":"Analysis in Greek is a loosening, so quantitative analysis loosens a problem into numbers.","cn":"analysis 在希腊语里是「松开」，定量分析就是把问题拆成数字。"},{"en":"Chemical quantitative analysis asks how much lead is in the water, not what is in it.","cn":"化学定量分析问的是水里有多少铅，而不是水里有什么。"},{"en":"The phrase is two words doing two jobs: the adjective names the kind, the noun names the work.","cn":"这个短语是两个词各干一件事：形容词说明种类，名词说明工作。"}],"abstract":[{"en":"A number is a description that has agreed to be compared with other descriptions.","cn":"数字是一种答应与别的描述相比较的描述。"},{"en":"Measuring turns an argument about impressions into an argument about figures.","cn":"测量把关于印象的争论变成关于数字的争论。"},{"en":"Every quantitative claim leaves something unmeasured, and the skill lies in knowing what was left out.","cn":"每一个定量结论都留下了未被测量的东西，功夫就在知道漏掉了什么。"}]},"examples":[{"en":"The report opens with a quantitative analysis of traffic flow at the junction.","cn":"报告以对路口车流量的定量分析开篇。"},{"en":"Quantitative analysis of the alloy found less than one per cent nickel.","cn":"对该合金的定量分析发现镍含量不到百分之一。"},{"en":"Before the merger, the bank commissioned a quantitative analysis of credit risk.","cn":"合并之前，这家银行委托做了一次信用风险的定量分析。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「框提忒提夫 分析」——先把东西框起来称一称，再拆开来看：定量分析","word":"quantitative analysis"},"root":"拉丁语 quantus「多少」→ 中世纪拉丁语 quantitativus「与数量有关的」＋希腊语 analysis「解开、拆解」（ana-「彻底」＋lysis「松开」）；完整短语的英语首见年代不确定，通常列在十九世纪。","sensesIntro":{"en":"Nine senses divide the phrase by what it is applied to: a measured sample, the statistical machinery, chemical amounts, risk and performance, the numerical half of a report, the contrast with qualitative work, market modelling, cross-case comparison, and support for a decision.","cn":"九个义项按适用对象分开：被测样本、统计方法、化学含量、风险与绩效、报告中的数字部分、与定性工作的对照、市场建模、跨案例比较、以及为决策提供依据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance reading is written into a table, and a curve grows out of the numbers.","cn":"核心意象：天平读数被写进表格，一条曲线从这些数字里长出来。"},"chain":["HOW MUCH","MEASURED SAMPLE","NUMERICAL TABLE","STATISTICAL METHOD","QUANTIFIED JUDGEMENT","DECISION"],"branches":[{"senses":"01","en":"THE MEASURED SAMPLE: a question about amount answered from readings.","cn":"被测样本：一个关于多少的问题，用读数来回答。"},{"senses":"02 · 06","en":"THE METHOD AND ITS MIRROR: statistical operations on one side, the contrast with qualitative work on the other.","cn":"方法与其镜像：一边是统计操作，另一边是与定性工作的对照。"},{"senses":"03","en":"THE CHEMICAL AMOUNT: how much of a substance a sample holds.","cn":"化学含量：一份样本里含有多少某物质。"},{"senses":"04 · 05 · 07","en":"THE QUANTIFIED JUDGEMENT AND THE PAPER: risk and performance rated, a market modelled, a report's numerical half.","cn":"量化判断与纸面：风险与绩效被打分，市场被建模，报告的数字部分成形。"},{"senses":"08 · 09","en":"THE COMPARISON AND THE CHOICE: cases ranked on one scale, a decision carried by figures.","cn":"比较与抉择：案例被排在同一尺度上，决定由数字来支撑。"}]},"affixes":{"intro":{"en":"The entry is a compound of a Latin adjective and a Greek noun, and each half brings its own endings and family.","cn":"这条词目是一个拉丁形容词与一个希腊名词的复合，两半各带自己的词尾与词族。"},"latinIntro":{"en":"Latin supplies quantus and quantitas, and the medieval adjective quantitativus is a schoolroom formation on the same stem; Greek supplies analysis and lysis.","cn":"拉丁语提供了 quantus 与 quantitas，中世纪的 quantitativus 是在同一词干上的学堂造词；希腊语提供了 analysis 与 lysis。"},"items":[{"word":"quantus","structure":"Latin pronoun and adjective","meaning":"how much, how great","meaningCN":"多少；多大","example":"The word asks for an amount, not a quality.","exampleCN":"这个词问的是数量，不是性质。"},{"word":"quantitas","structure":"Latin noun from quantus","meaning":"amount, quantity","meaningCN":"数量；量","example":"The noun names the thing the question asks for.","exampleCN":"这个名词指提问所要的那个东西。"},{"word":"quantitativus","structure":"Medieval Latin adjective","meaning":"concerned with amount","meaningCN":"与数量有关的","example":"The adjective was coined in the schools to label this kind of work.","exampleCN":"这个形容词在学堂里被造出来，用来标记这一类工作。"},{"word":"analysis","structure":"Greek noun","meaning":"a loosening, a resolution into parts","meaningCN":"松开；拆解","example":"Geometry used it for taking a problem apart.","exampleCN":"几何学用它表示把问题拆开。"},{"word":"ana-","structure":"Greek prefix","meaning":"up, throughout, back","meaningCN":"向上；彻底；回","example":"The prefix adds the idea of going right through.","exampleCN":"这个前缀加进「一路贯穿」的意思。"},{"word":"lysis","structure":"Greek noun","meaning":"a loosening","meaningCN":"松开；解开","example":"The noun supplies the picture of something coming undone.","exampleCN":"这个名词提供「东西被解开」的画面。"},{"word":"-ive","structure":"Latin adjective ending","meaning":"having the nature of","meaningCN":"具有……性质的","example":"It turns the noun of amount into an adjective.","exampleCN":"它把表示数量的名词变成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It gives the adverb for measuring something.","exampleCN":"它构成表示「以测量方式」的副词。"},{"word":"quantify","structure":"verb on the same stem","meaning":"to give an amount to","meaningCN":"给……定出数量","example":"The verb names the act of putting a number on something.","exampleCN":"这个动词指给某物配上数字的动作。"}],"latinEntries":[{"word":"quantus","structure":"Latin adjective","meaning":"how much, how great","meaningCN":"多少；多大"},{"word":"quantitas","structure":"Latin noun","meaning":"amount, quantity","meaningCN":"数量；量"},{"word":"quantitativus","structure":"Medieval Latin adjective","meaning":"concerned with amount","meaningCN":"与数量有关的"},{"word":"analysis","structure":"Greek noun","meaning":"a loosening, a resolution","meaningCN":"松开；拆解"},{"word":"lysis","structure":"Greek noun","meaning":"a loosening","meaningCN":"松开"}],"derivatives":[{"word":"quantitatively","pos":"adv.","zh":"由修饰形容词加副词词尾构成，义为「定量地」"},{"word":"quantify","pos":"v.","zh":"由同一词干构成动词，义为「量化」"},{"word":"quantification","pos":"n.","zh":"由量化动词加表示动作结果的名词尾构成，义为「量化」"},{"word":"quantity","pos":"n.","zh":"由同一拉丁词根构成名词，义为「数量」"},{"word":"quantitative analyst","pos":"n.","zh":"由该短语缩合而成的职业称谓，义为「量化分析师」"}]}},{"word":"critical analysis","ipa_uk":"/ˌkrɪtɪkəl əˈnæləsɪs/","ipa_us":"/ˌkrɪtɪkəl əˈnæləsɪs/","definition_zh":"批判性分析；评析；对论证的批评性检验；对文本、政策或故障的系统评析；对关键因素的专门分析","definition_en":"the systematic examination of a claim, text, plan or failure in order to judge how well it holds up, and in one use the analysis of the factor on which an outcome turns","core_image":"一段论证摊在桌面上被逐句拆开，页边用红笔圈出「证据不足」的几处","scene":"评审会上，编辑把提案的每条理由单独抄在纸上，逐条追问依据在哪里。The journal sent the paper out for a critical analysis before accepting it.","sceneCN":"这里指对文稿作学术评析（第 2 个义项：对文本的学术评析）；句意为期刊在录用之前把论文送去做批判性分析。场景要点：摊开的稿页、逐条摘录的纸片、页边的红笔圈注。","pos":[{"tag":"n.","zh":"批判性分析；评析"}],"collocations":[{"phrase":"a critical analysis of","zh":"对……的批判性分析"},{"phrase":"offer a critical analysis","zh":"提出批判性分析"},{"phrase":"critical analysis skills","zh":"批判性分析能力"},{"phrase":"critical analysis of the evidence","zh":"对证据的批判性检验"},{"phrase":"subject to critical analysis","zh":"接受批判性分析"},{"phrase":"critical analysis essay","zh":"评析性论文"}],"forms":[{"label":"单数形式","form":"critical analysis"},{"label":"复数形式","form":"critical analyses"},{"label":"修饰形容词","form":"critical"},{"label":"核心名词","form":"analysis"},{"label":"核心名词复数","form":"analyses"}],"derivatives":[{"word":"critically","pos":"adv.","zh":"由修饰形容词加副词词尾构成，义为「批判性地、以评析的方式」"},{"word":"critic","pos":"n.","zh":"由同一希腊词根构成名词，义为「批评者、评论者」"},{"word":"criticism","pos":"n.","zh":"由批评者一词加表示行为的名词尾构成，义为「批评、评论」"},{"word":"critique","pos":"n.","zh":"由同一词源经法语构成名词，义为「评析文章、批评」"},{"word":"criterion","pos":"n.","zh":"由同一希腊词根构成名词，义为「标准、评判尺度」"},{"word":"criticality","pos":"n.","zh":"由批评形容词加表示状态的名词尾构成，义为「关键程度、临界性」"}],"senses":[{"no":"01","title":"Judging an argument by its evidence","titleCN":"依据证据评判论证","definition":"examining the claims in an argument and the support offered for them instead of accepting them as given","definitionCN":"检查论证中的主张及其所获支持，而不是把它们当作既定结论接受下来","example":"Her critical analysis of the proposal separated evidence from assertion.","exampleCN":"她对这份提案的批判性分析把证据与断言分开。","why":"Krinein in Greek means to separate and decide, so the work begins by sorting what is proved from what is merely said.","whyCN":"希腊语 krinein 意为「分开、判定」，因此这项工作首先要把已证实的与仅说出的分开。"},{"no":"02","title":"Academic critique of a text","titleCN":"对文本的学术评析","definition":"a close reading and evaluation of a book, article or theory that states its strengths and limits","definitionCN":"对一本书、一篇论文或一种理论作细读与评价，指出其长处与局限","example":"The seminar began with a critical analysis of the paper's method.","exampleCN":"研讨课以对该论文方法的批判性分析开始。","why":"The classroom took the phrase as the name of a standard written form, with claims weighed one by one.","whyCN":"课堂把这个短语用作一种标准写作体裁的名称，主张要一条条被掂量。"},{"no":"03","title":"Literary and artistic criticism","titleCN":"文学与艺术批评","definition":"the interpretive evaluation of a work's form, meaning and effect","definitionCN":"对作品的形式、意义与效果作解释性评价","example":"His critical analysis of the novel traced the imagery of water through every chapter.","exampleCN":"他对这部小说的批判性分析顺着每一章追查水的意象。","why":"Criticism has long meant the judging of art, and the phrase carries that older trade inside it.","whyCN":"批评一词长久以来就指对艺术的评判，这个短语把那一行古老手艺带了进来。"},{"no":"04","title":"Diagnostic review of a failure","titleCN":"对故障或事故的溯源剖析","definition":"a systematic examination of what went wrong in an accident or breakdown and why","definitionCN":"系统检查事故或故障中出了什么问题以及为什么","example":"A critical analysis of the collapse pointed to a single weld at the base.","exampleCN":"对这次坍塌的溯源分析指向底部的一道焊缝。","why":"Instead of judging a text, the phrase is turned on an event, and the same testing of evidence applies.","whyCN":"这里评判的对象从文本换成了事件，而检验证据的同一套做法照旧适用。"},{"no":"05","title":"Assessment of a policy or plan","titleCN":"政策与方案的评估","definition":"the weighing of a public measure's aims, costs and likely effects before or after adoption","definitionCN":"在采纳前后权衡一项公共措施的目标、成本与可能效果","example":"The committee published a critical analysis of the housing plan in June.","exampleCN":"委员会在六月发表了对该住房方案的批判性评估。","why":"Policy work borrowed the academic phrase because both ask whether the stated reasons actually hold.","whyCN":"政策工作借用了这个学术短语，因为两者都在问：所述理由究竟站不站得住。"},{"no":"06","title":"Critical thinking as a trained habit","titleCN":"作为训练出来的思维习惯","definition":"the practised habit of questioning assumptions, checking inference and detecting bias","definitionCN":"质疑前提、检查推理、识别偏见的习得习惯","example":"The course teaches critical analysis before it introduces statistics.","exampleCN":"这门课先教批判性分析，再讲统计学。","why":"The phrase shifted from a product to a skill, naming the mental habit rather than a written piece.","whyCN":"这个短语从成品转向能力，指的不再是一篇文字，而是一种心智习惯。"},{"no":"07","title":"Examination of one decisive factor","titleCN":"对关键因素的专门分析","definition":"here the adjective carries its other sense, decisive, and the phrase isolates the factor on which the outcome turns","definitionCN":"此处形容词取「决定性的」另一义，短语用来单独分析结果所系的那个因素","example":"A critical analysis of the load path showed where the beam would fail first.","exampleCN":"对传力路径的关键分析显示出梁最先破坏的位置。","why":"English critical also means decisive, as in a critical moment, and this reading pulls the phrase away from evaluation.","whyCN":"英语中「批判性」另有「决定性的」读法，如「关键时刻」；这一读法把短语从「评价」拉向「要害」。"},{"no":"08","title":"Review of data and sources","titleCN":"对数据与来源的核验","definition":"checking how figures were gathered, whether sources are reliable, and what was left out","definitionCN":"核查数字如何采集、来源是否可靠、又漏掉了什么","example":"Their critical analysis found that two surveys had sampled the same households.","exampleCN":"他们的批判性核验发现，两项调查抽到了同一批住户。","why":"Analysis supplies the taking apart, and criticism supplies the suspicion, so the pair fits an audit of figures.","whyCN":"分析提供「拆开」，批评提供「怀疑」，两者合起来正好用于核查数字。"},{"no":"09","title":"Argument mapping in debate","titleCN":"辩论中的论证拆解","definition":"setting out an opponent's premises and inferences in order to test where the reasoning breaks","definitionCN":"把对手的前提与推论摆出来，以检验推理在哪里断裂","example":"The debater's critical analysis exposed a step that assumed what it set out to prove.","exampleCN":"那位辩手的批判性分析揭出一个把结论当前提的步骤。","why":"A debate is won by finding the joint in the other side's reasoning, and the phrase names the operation of locating it.","whyCN":"辩论靠找到对方推理中的关节取胜，这个短语指的就是定位那个关节的操作。"}],"etymology":{"intro":{"en":"Critical comes from Greek kritikos, able to judge, from krinein, to separate or decide; Latin took it as criticus and English received it through French. Analysis is the Greek loosening. The pair names judging something by taking it apart.","cn":"critical 来自希腊语 kritikos「能评判的」，其动词 krinein 意为「分开、判定」；拉丁语作 criticus，英语经法语引入。analysis 是希腊语里的「解开」。两者合起来，指通过拆开某物来评判它。"},"items":[{"era":"GREEK KRINEIN","en":"The verb meant to separate, sift and decide, and it also stands behind crisis and criterion.","cn":"这个动词意为分开、筛出、判定，crisis 与 criterion 也由它而来。"},{"era":"GREEK KRITIKOS","en":"The adjective named the person or power able to judge, especially in matters of art and letters.","cn":"这个形容词指有能力评判的人或能力，尤用于文艺之事。"},{"era":"LATIN CRITICUS, FRENCH CRITIQUE","en":"Latin took the judge as criticus, and French formed critique for the judgement itself.","cn":"拉丁语把评判者写作 criticus，法语又造出 critique 专指评判本身。"},{"era":"GREEK ANALYSIS","en":"Analysis meant a loosening up, and it named the resolution of a whole into its parts.","cn":"analysis 意为「松开」，指把整体化解为各个部分。"},{"era":"ENGLISH, 19TH CENTURY","en":"The full phrase settled in English letters and schools; its first use is uncertain and is usually placed in the nineteenth century.","cn":"该完整短语在英语文坛与学堂里定型；其首次使用年代不确定，通常放在十九世纪。"},{"era":"MODERN EXTENSIONS","en":"Schools extended it to thinking skills, engineers to failure review, and policy offices to programme evaluation.","cn":"学校把它扩展到思维技能，工程师用它复查故障，政策部门用它评估项目。"}]},"similar":{"note":{"en":"The first group shares the judging vocabulary; the second names neighbouring review practices.","cn":"第一组共享「评判」这套词汇；第二组是与它相邻的各种审查做法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"critically","ipa":"/ˈkrɪtɪkli/","tag":"same root","definition":"The adverb meaning in a judging or discerning way.","definitionCN":"副词，意为「以评判或辨别的态度」。"},{"word":"critic","ipa":"/ˈkrɪtɪk/","tag":"same root","definition":"A person who judges works or ideas, or one who finds fault.","definitionCN":"指评判作品或观点的人，也指爱挑毛病的人。"},{"word":"criticism","ipa":"/ˈkrɪtɪsɪzəm/","tag":"same root","definition":"The act or work of judging, and also an expression of fault-finding.","definitionCN":"指评判的行为或文字，也指挑错的意见。"},{"word":"critique","ipa":"/krɪˈtiːk/","tag":"same root","definition":"A formal written assessment of a work or argument.","definitionCN":"指对作品或论证的正式书面评析。"},{"word":"criterion","ipa":"/kraɪˈtɪəriən/","tag":"same root","definition":"A standard by which something is judged; the plural is criteria.","definitionCN":"指评判所依的标准，复数为 criteria。"}]},{"heading":"NEAR MEANING","entries":[{"word":"evaluation","ipa":"/ɪˌvæljuˈeɪʃn/","tag":"near meaning","definition":"A judgement of worth or effectiveness, often against set criteria.","definitionCN":"指对价值或成效的判断，常依既定标准。"},{"word":"review","ipa":"/rɪˈvjuː/","tag":"near meaning","definition":"A survey and assessment of a body of work or a decision.","definitionCN":"指对一批成果或某项决定所作的综述与评估。"},{"word":"appraisal","ipa":"/əˈpreɪzl/","tag":"near meaning","definition":"An assessment of value, performance or quality, often formal.","definitionCN":"指对价值、表现或质量的评估，常较正式。"},{"word":"scrutiny","ipa":"/ˈskruːtəni/","tag":"near meaning","definition":"Close and critical inspection, with attention to detail.","definitionCN":"指细致而带审视的检查。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek verb of separating, the real family of judge words, and the real settings where the phrase is used.","cn":"正常联想使用希腊语「分开」的动词、真实同族的「评判」词，以及这个短语真正出现的场合。"},"normal":[{"en":"Krinein means to separate, so a critical reader separates what is proved from what is claimed.","cn":"krinein 意为分开，所以批判性读者把已证实的与仅声称的分开。"},{"en":"Critic, criticism, critique and criterion all come from the same judging root.","cn":"批评者、批评、评析与标准都出自同一个「评判」词根。"},{"en":"Analysis is a loosening: the phrase takes a claim apart joint by joint.","cn":"analysis 是「松开」，这个短语把主张一个关节一个关节地拆开。"},{"en":"A literature review and a failure report use the same phrase, because both test evidence.","cn":"文献综述与故障报告都用这个短语，因为两者都在检验证据。"},{"en":"Critical also means decisive, which is why an analysis of the load path can be critical too.","cn":"这个词的「批判性」另有「决定性」的意思，所以传力路径的分析也可以叫「关键分析」。"}],"abstract":[{"en":"Criticism is not dislike; it is the patience to ask what the evidence actually supports.","cn":"批评不是不喜欢，而是有耐心去问证据到底支持什么。"},{"en":"Every argument has a joint where it can be taken apart, and the phrase names the search for that joint.","cn":"每段论证都有一个可以拆开的关节，这个短语指的就是寻找那个关节。"},{"en":"A judgement without a method is an opinion wearing a gown.","cn":"没有方法的评判，是披着长袍的意见。"}]},"examples":[{"en":"The first chapter offers a critical analysis of the earlier studies.","cn":"第一章对先前的研究作了批判性分析。"},{"en":"Students are asked to write a critical analysis of a policy they disagree with.","cn":"学生被要求写一篇批判性分析，对象是他们并不同意的政策。"},{"en":"A critical analysis of the crash showed that the warning system had never been tested.","cn":"对这次撞车事故的溯源分析显示，报警系统从未测试过。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「克瑞提扣 分析」——把东西拆开、逐条挑刺再下判断：批判性分析","word":"critical analysis"},"root":"希腊语 krinein「分开、判定」→ kritikos「能评判的」→ 拉丁语 criticus → 法语 critique；＋希腊语 analysis「解开」（ana-「彻底」＋lysis「松开」）。完整短语的英语首见年代不确定，通常列在十九世纪。","sensesIntro":{"en":"Nine senses separate the objects and the angles: an argument judged, a text critiqued, a work interpreted, a failure traced, a policy weighed, a habit of mind, a decisive factor, a set of sources checked, and a debate taken apart.","cn":"九个义项按对象与角度分开：评判论证、评析文本、解释作品、追查故障、权衡政策、训练心智习惯、单看关键因素、核验数据来源、拆解辩论。"},"semanticMap":{"core":{"en":"CORE IMAGE: a page of argument lies open, each line lifted out, red circles at the weak joints.","cn":"核心意象：一页论证摊开着，每一行被拎出来，薄弱处画着红圈。"},"chain":["CLAIM OR TEXT","TAKEN APART","EVIDENCE CHECKED","STRENGTHS AND LIMITS","JUDGEMENT","REVISION OR DECISION"],"branches":[{"senses":"01","en":"THE ARGUMENT JUDGED: assertion sorted from proof.","cn":"被评判的论证：断言与证明被分开。"},{"senses":"02 · 03","en":"THE TEXT AND THE WORK: a paper read closely, a novel read for its images.","cn":"文本与作品：论文被细读，小说被追索意象。"},{"senses":"04 · 07","en":"THE FAILURE AND THE HINGE: what went wrong, and the one factor the outcome turns on.","cn":"故障与要害：出了什么问题，以及结果所系的那一个因素。"},{"senses":"05 · 08","en":"THE PLAN AND THE FIGURES: a policy weighed, sources and data checked.","cn":"方案与数字：政策被权衡，来源与数据被核验。"},{"senses":"06 · 09","en":"THE TRAINED HABIT AND THE DEBATE: a skill of mind, a case taken apart in argument.","cn":"习得的习惯与辩论：一种心智技能，一桩在辩论中被拆开的案子。"}]},"affixes":{"intro":{"en":"Critical is a Greek judging word that reached English through Latin and French; analysis is another Greek noun, and the compound keeps both endings.","cn":"critical 是一个经拉丁语与法语进入英语的希腊评判词；analysis 是另一个希腊名词，这个复合词把两套词尾都保留下来。"},"latinIntro":{"en":"Greek supplies krinein, krisis, kritikos and analysis; Latin supplies criticus, and French supplies critique and critique as a noun.","cn":"希腊语提供了 krinein、krisis、kritikos 与 analysis；拉丁语提供了 criticus，法语提供了 critique 这一名词。"},"items":[{"word":"krinein","structure":"Greek verb","meaning":"to separate, sift, decide","meaningCN":"分开；筛出；判定","example":"The verb is the source of judging words.","exampleCN":"这个动词是整族「评判」词的源头。"},{"word":"kritikos","structure":"Greek adjective","meaning":"able to judge","meaningCN":"能评判的","example":"It named the person fit to judge a work.","exampleCN":"它指有资格评判作品的人。"},{"word":"criticus","structure":"Latin noun and adjective","meaning":"judge, critic","meaningCN":"评判者；批评者","example":"Latin kept the word for the judge of letters.","exampleCN":"拉丁语保留了「文章评判者」这个词。"},{"word":"critique","structure":"French noun","meaning":"a judgement, a review","meaningCN":"评判；评析","example":"French named the written judgement itself.","exampleCN":"法语给书面评判本身取了名。"},{"word":"analysis","structure":"Greek noun","meaning":"a loosening, a resolution into parts","meaningCN":"松开；拆解","example":"It supplies the taking-apart half of the phrase.","exampleCN":"它提供这个短语中「拆开」的那一半。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or belonging to","meaningCN":"属于……的","example":"It turns the noun of judgement into an adjective.","exampleCN":"它把表示评判的名词变成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It gives the adverb of judging.","exampleCN":"它构成表示评判方式的副词。"},{"word":"-ism","structure":"Greek and Latin noun ending","meaning":"a practice or system","meaningCN":"行为；体系","example":"It forms the name of the activity of judging.","exampleCN":"它构成评判活动本身的名词。"},{"word":"kriterion","structure":"Greek noun","meaning":"a means of judging","meaningCN":"评判的手段；标准","example":"The tool of judgement gave English criterion.","exampleCN":"评判的工具给英语留下了「标准」一词。"}],"latinEntries":[{"word":"krinein","structure":"Greek verb","meaning":"to separate, decide","meaningCN":"分开；判定"},{"word":"kritikos","structure":"Greek adjective","meaning":"able to judge","meaningCN":"能评判的"},{"word":"criticus","structure":"Latin noun","meaning":"judge, critic","meaningCN":"评判者"},{"word":"analysis","structure":"Greek noun","meaning":"a loosening, a resolution","meaningCN":"松开；拆解"},{"word":"kriterion","structure":"Greek noun","meaning":"a means of judging","meaningCN":"评判的标准"}],"derivatives":[{"word":"critically","pos":"adv.","zh":"由修饰形容词加副词词尾构成，义为「批判性地」"},{"word":"critic","pos":"n.","zh":"由同一希腊词根构成名词，义为「批评者」"},{"word":"criticism","pos":"n.","zh":"由批评者一词加表示行为的名词尾构成，义为「批评」"},{"word":"critique","pos":"n.","zh":"由同一词源经法语构成名词，义为「评析」"},{"word":"criterion","pos":"n.","zh":"由同一希腊词根构成名词，义为「标准」"}]}},{"word":"accordingly","ipa_uk":"/əˈkɔːdɪŋli/","ipa_us":"/əˈkɔːrdɪŋli/","definition_zh":"因此；相应地；按照情况；依照规定；比照办理","definition_en":"in a way that follows from or matches what has just been stated, whether as a consequence, an adjustment or a compliance with a rule","core_image":"上一句写下的结论被手指点住，落到下一行的待办事项上，日期被整行改掉","scene":"暴雨把工期推迟了两周，项目经理把交工日期整体往后挪。The ground was still frozen, and the crew planned accordingly.","sceneCN":"这里指按照所述情况作出安排（第 2 个义项：与已说明的情况相符地）；句意为地面仍然冻着，施工队据此作了安排。场景要点：改期的进度表、冻结的地面、挪后的完工日期。","pos":[{"tag":"adv.","zh":"因此；相应地；依照规定"}],"collocations":[{"phrase":"act accordingly","zh":"据此行事"},{"phrase":"adjust accordingly","zh":"相应调整"},{"phrase":"plan accordingly","zh":"据此作计划"},{"phrase":"and accordingly","zh":"并相应地"},{"phrase":"accordingly, the committee","zh":"因此，委员会……"},{"phrase":"vary accordingly","zh":"随情况而变化"}],"forms":[{"label":"无词形变化（副词）","form":"accordingly"}],"derivatives":[{"word":"according","pos":"adj.","zh":"由同一动词的分词形式构成，义为「按照……的、据……所说」"},{"word":"accord","pos":"n.","zh":"由同一词源经法语构成名词，义为「一致、协议」"},{"word":"accordance","pos":"n.","zh":"由动词加表示状态的名词尾构成，义为「一致、符合」"},{"word":"according to","pos":"prep.","zh":"由分词加分词后置成分构成，义为「根据、按照」"}],"senses":[{"no":"01","title":"Therefore, and so an action follows","titleCN":"因此，并据此行动","definition":"introduces a step taken because of what has just been stated, so that consequence and response arrive together","definitionCN":"引出因前述事实而采取的一步，使结果与应对同时到场","example":"The tests failed; accordingly, the launch was postponed.","exampleCN":"测试未通过，因此发射被推迟。","why":"Accord is agreement, so the word points to an action brought into agreement with the fact just named.","whyCN":"这个词的词干意为「一致」，因此它指向一个与前述事实取得一致的动作。"},{"no":"02","title":"In line with the stated case","titleCN":"与所述情况相符地","definition":"matching an action or arrangement to a condition that has been described, rather than merely following from it","definitionCN":"使行动或安排与已描述的条件相称，而不只是由它推出","example":"Prices vary by region, and the catalogue is printed accordingly.","exampleCN":"价格随地区而异，目录也据此印制。","why":"The core sense is fitting, not causation: what is done is shaped to what was said.","whyCN":"核心意思是「相合」而非「因果」：所做之事按所述之事来定形。"},{"no":"03","title":"As the rules require","titleCN":"按此规定办理","definition":"in contracts and regulations, do what the clause prescribes","definitionCN":"在合同与规章中，按条款所规定的方式办理","example":"The tenant shall give notice in writing, and the deposit shall be returned accordingly.","exampleCN":"承租人应以书面形式通知，押金也按此退还。","why":"Legal drafting needs a word that turns a rule into the manner of performing it, and this is that word.","whyCN":"法律起草需要一个把规则转成履行方式的词，这个词正是它。"},{"no":"04","title":"Sentence-initial signpost","titleCN":"句首衔接标记","definition":"the formal written use that opens a sentence and points back to the preceding statement","definitionCN":"正式书面用法，置于句首并回指上一句内容","example":"Accordingly, the second chapter takes up the question of scale.","exampleCN":"因此，第二章接着讨论尺度问题。","why":"Written argument needs a visible hinge at the start of a sentence, and the adverb is placed there to serve as one.","whyCN":"书面论证需要在句首有一个看得见的铰链，这个副词就被放在那里充当铰链。"},{"no":"05","title":"Mid-sentence insertion","titleCN":"句中插入","definition":"placed after the subject or auxiliary, where the link is carried more lightly and the sentence keeps its rhythm","definitionCN":"置于主语或助动词之后，衔接更轻，句子节奏得以保持","example":"The team, accordingly, revised the timetable by two weeks.","exampleCN":"团队相应地按两周修改了时间表。","why":"An adverb that can sit inside the clause lets the writer mark agreement without stopping the sentence.","whyCN":"能放在句中的副词让作者在不打断句子的情况下标出「相合」关系。"},{"no":"06","title":"At the end of a clause","titleCN":"句末收束","definition":"the final position, common with verbs of adjusting, where the word adds how the action was fitted to the case","definitionCN":"句末位置，常与「调整」类动词连用，补充动作是如何随情况而定的","example":"When the grant was cut, the schedule was tightened accordingly.","exampleCN":"拨款被削减后，进度表也相应收紧。","why":"Final position makes the word part of the predicate, so it describes the manner of the action rather than the link between sentences.","whyCN":"句末位置使这个词进入谓语，于是它描述动作的方式，而不是句与句之间的连接。"},{"no":"07","title":"Adjusted in proportion","titleCN":"按比例相应调整","definition":"used with change verbs to mean to the matching degree, so that the size of one change sets the size of the other","definitionCN":"与变化类动词连用，意为「到相称的程度」，一处变化的幅度决定另一处的幅度","example":"Salaries were raised, and the budget for next year was adjusted accordingly.","exampleCN":"薪资上调，明年的预算也相应调整。","why":"Proportion is agreement in amount, which is the same core idea applied to figures.","whyCN":"比例就是数量上的一致，是同一个核心意思用到数字上。"},{"no":"08","title":"Described or labelled in that manner","titleCN":"按所述方式描述或标注","definition":"used with verbs of describing, labelling or classifying, meaning in the manner already stated","definitionCN":"与描述、标注、归类类动词连用，意为「按已说明的方式」","example":"Each sample was labelled by site and stored accordingly.","exampleCN":"每份样本按地点标注，并据此存放。","why":"Once a rule for naming is given, everything that follows it is handled accordingly, and the word marks that compliance.","whyCN":"命名规则一经给出，随后的一切都照此处理，这个词标记的正是这种遵从。"}],"etymology":{"intro":{"en":"Accordingly is according plus -ly. Accord comes from Old French acorder, to bring to one heart, from Latin ad- to and cor, cord-, heart. The word therefore begins with agreement between parties and ends as a marker of agreement between a statement and an action.","cn":"accordingly 由 according 加 -ly 构成。accord 来自古法语 acorder「使归于一心」，其拉丁语来源是 ad-「向」加 cor、cord-「心」。所以这个词从「双方一心」出发，最后成了「言语与行动相合」的标记。"},"items":[{"era":"LATIN COR, CORD-","en":"Cor meant heart, and the derived cord- appears in concord and discord, words about being of one heart or divided.","cn":"这个词意为「心」，其派生形式出现在 concord 与 discord 里，前者指一心，后者指离心。"},{"era":"LATIN AD- + CORDARE","en":"The compound verb meant to bring into one heart, that is, to reconcile or make agree.","cn":"这个复合动词意为「使归于一心」，即调和、使一致。"},{"era":"OLD FRENCH ACORDER","en":"French kept the sense of agreement and passed the verb into English as accord.","cn":"法语保留了「一致」的意思，并把动词以 accord 的形式传入英语。"},{"era":"ENGLISH ACCORD","en":"English accord covered both the noun of agreement and the verb of granting or matching.","cn":"英语的 accord 既指「一致」这一名词，也指授予、使相合的动作。"},{"era":"ACCORDING + -LY","en":"According began as a participle meaning in agreement with, and the adverb added the manner: in a way that agrees with that.","cn":"according 起初是分词，意为「与……一致」，副词词尾再加上方式：以与那件事相合的方式。"},{"era":"MODERN LEGAL AND TECHNICAL USE","en":"Contracts and manuals fixed the pattern act accordingly, which keeps the word alive outside literary prose; its first use as a sentence opener is uncertain in date.","cn":"合同与手册固定了「据此办理」这一模式，使这个词在文学散文之外继续存活；它作句首衔接词的首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the agreement stem; the second group contains the causal and matching adverbs it is often confused with.","cn":"第一组共享「一致」这一词干；第二组是常与它混淆的因果类与对应类副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"according","ipa":"/əˈkɔːdɪŋ/","tag":"same root","definition":"A participle used in according to, meaning as stated by or in agreement with.","definitionCN":"分词，用于 according to，意为「据……所说」或「与……一致」。"},{"word":"accord","ipa":"/əˈkɔːd/","tag":"same root","definition":"An agreement, or to grant something, especially in formal use.","definitionCN":"指协议，也指正式地授予。"},{"word":"accordance","ipa":"/əˈkɔːdns/","tag":"same root","definition":"The state of agreeing with a rule or standard.","definitionCN":"指与规则或标准相符的状态。"},{"word":"according to","ipa":"/əˈkɔːdɪŋ tə/","tag":"same root","definition":"A preposition meaning as stated by, or in proportion to.","definitionCN":"介词，意为「据……所说」或「按照」。"},{"word":"correspondingly","ipa":"/ˌkɒrəˈspɒndɪŋli/","tag":"different root","definition":"A near neighbour in meaning that comes from respond, not from heart; it marks matching change rather than compliance.","definitionCN":"意思相近但来自 respond 而非「心」，标记的是对应变化而非遵从。"}]},{"heading":"NEAR MEANING","entries":[{"word":"therefore","ipa":"/ˈðeəfɔː/","tag":"near meaning","definition":"The plain marker of a logical conclusion, without any suggestion of adjustment.","definitionCN":"纯粹的结论标记，不含「作出调整」之意。"},{"word":"consequently","ipa":"/ˈkɒnsɪkwəntli/","tag":"near meaning","definition":"Marks an effect that follows, and reports it rather than prescribing a response.","definitionCN":"标记随之而来的结果，只陈述而不规定应对。"},{"word":"respectively","ipa":"/rɪˈspektɪvli/","tag":"near meaning","definition":"Matches items in two lists one to one, in the order given.","definitionCN":"把两份清单中的项目按给定顺序一一对应。"},{"word":"in turn","ipa":"/ɪn ˈtɜːn/","tag":"near meaning","definition":"Marks a sequence of reciprocal or successive actions.","definitionCN":"标记互为或依次发生的动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the heart inside accord, the real legal phrase, and the real change verbs it keeps company with.","cn":"正常联想使用「一致」里的那颗心、真实的法律说法，以及它常结伴的变化类动词。"},"normal":[{"en":"Accord is agreement, and cor is heart: two sides of one heart, then a statement and an act of one mind.","cn":"「一致」的词根里藏着一颗心：先是双方一心，后来是言语与行动一心。"},{"en":"Act accordingly is the phrase you meet in rules long before you meet it in essays.","cn":"「据此行事」这个说法，你会在规章里先碰到，比在散文里早得多。"},{"en":"Adjust, revise, plan and vary are its usual verbs, because it reports an adjustment.","cn":"调整、修改、计划、变动是它常跟的动词，因为它报告的就是一次调整。"},{"en":"According to and accordingly share the stem but not the job: one introduces a source, the other a response.","cn":"「根据」与「据此」两个说法词干相同而职务不同：前者引出消息来源，后者引出应对。"},{"en":"If a sentence could end with therefore, but the next clause says what someone did, accordingly is the better fit.","cn":"如果一句本可以用「因此」收尾，但下一句说的是某人做了什么，那就更适合用「据此」。"}],"abstract":[{"en":"Agreement is not assent: it can mean that an action has been cut to the shape of a fact.","cn":"相合不等于赞同：它可以指行动被裁成事实的形状。"},{"en":"The word quietly asks who is obeying what, which is why regulations like it.","cn":"这个词在悄悄追问谁在服从什么，规章偏爱它正是为此。"},{"en":"A consequence happens; an adjustment is made, and accordingly marks the second.","cn":"结果是自己发生的，调整是人做出来的，而这个词标记的是后者。"}]},"examples":[{"en":"The shipment was delayed, and the delivery schedule was revised accordingly.","cn":"货物延迟到达，交货时间表也相应修改。"},{"en":"Staff were told that the office would close early and were asked to plan accordingly.","cn":"员工被告知办公室将提前关闭，并被要求据此安排工作。"},{"en":"Accordingly, the committee recommended a second round of tests.","cn":"因此，委员会建议进行第二轮测试。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「额考丁利」——照着一颗心定下来的规矩办：相应地、据此","word":"accordingly"},"root":"古法语 acorder「使归于一心」← 拉丁语 ad-「向」+ cor、cord-「心」；英语 accord 指一致，according 为分词「与……相符」，加副词词尾 -ly 构成。本词直接来源清楚；作句首衔接词的首见年代为约数。","sensesIntro":{"en":"Eight senses keep the same fitting idea but change the setting: a response to a fact, an arrangement matching a condition, compliance with a clause, the written hinge, the lighter insertion, the final manner, a proportional adjustment, and a label given in the stated way.","cn":"八个义项保持同一个「相合」的意思，只更换场合：对事实的应对、与条件相称的安排、按条款办理、书面铰链、较轻的插入、句末的方式、按比例的调整、按所述方式的标注。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand points at the conclusion just written, and the next line of the plan is altered to fit it.","cn":"核心意象：一只手点住刚写下的结论，计划的下一行被改成与它相合的样子。"},"chain":["STATEMENT","AGREEMENT","ADJUSTMENT","ACTION TAKEN","WRITTEN LINK","COMPLIANCE"],"branches":[{"senses":"01","en":"THE RESPONSE: a step taken because of the fact just named.","cn":"应对：因刚提到的事实而采取的一步。"},{"senses":"02 · 07","en":"THE FIT AND THE PROPORTION: an arrangement shaped to the case, a change sized to another change.","cn":"相称与比例：安排按情况定形，一处变化按另一处定量。"},{"senses":"03 · 08","en":"THE RULE AND THE LABEL: a clause obeyed, a sample marked in the stated way.","cn":"规则与标注：条款被遵守，样本按所述方式标记。"},{"senses":"04 · 05","en":"THE WRITTEN HINGE: at the head of a sentence, or slipped inside it.","cn":"书面铰链：或置于句首，或嵌进句中。"},{"senses":"06","en":"THE MANNER AT THE END: the action closes the clause, and the word says how it was fitted.","cn":"句末的方式：动作收住句子，这个词说明它是如何随情况而定的。"}]},"affixes":{"intro":{"en":"Accordingly is an English adverb built on a French verb that came from Latin, and its parts are still visible in a small family.","cn":"这个词是英语副词，其基础是经拉丁语而来的法语动词，各部分在一个小词族里仍然看得见。"},"latinIntro":{"en":"Latin supplies ad- and cor, cord-; Old French supplies acorder, and English supplies accord, according and the ending -ly.","cn":"拉丁语提供了表示「向」的前缀与表示「心」的词根；古法语提供了「使归于一心」的动词，英语再由「一致」的分词加副词词尾构成。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向；朝","example":"The prefix points the action towards its object.","exampleCN":"这个前缀把动作指向对象。"},{"word":"cor, cord-","structure":"Latin noun","meaning":"heart","meaningCN":"心","example":"Two parties of one heart are parties in agreement.","exampleCN":"一心之两方，就是达成一致的两方。"},{"word":"accordare","structure":"Latin-derived verb","meaning":"to bring to one heart, reconcile","meaningCN":"使归于一心；调和","example":"The verb supplies the sense of making agree.","exampleCN":"这个动词提供「使一致」的意思。"},{"word":"acorder","structure":"Old French verb","meaning":"to agree, to reconcile","meaningCN":"一致；和解","example":"French carried the word into English.","exampleCN":"法语把这个词带进英语。"},{"word":"accord","structure":"English noun and verb","meaning":"agreement; to grant","meaningCN":"一致；授予","example":"The noun keeps the idea of two sides matching.","exampleCN":"名词保留「两方相合」的意思。"},{"word":"according","structure":"English participle","meaning":"in agreement with, as stated by","meaningCN":"与……一致；据……所说","example":"The participle turns agreement into a connector.","exampleCN":"这个分词把「一致」变成连接成分。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the manner adverb from the participle.","exampleCN":"它由分词构成方式副词。"},{"word":"-ance","structure":"Latin noun ending","meaning":"state of being","meaningCN":"……的状态","example":"It forms accordance, the state of agreeing.","exampleCN":"它构成表示「相合状态」的名词。"}],"latinEntries":[{"word":"cor, cord-","structure":"Latin noun","meaning":"heart","meaningCN":"心"},{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向"},{"word":"accordare","structure":"Latin-derived verb","meaning":"to reconcile, bring to one heart","meaningCN":"调和；使归于一心"}],"derivatives":[{"word":"according","pos":"adj.","zh":"由同一动词的分词形式构成，义为「按照……的」"},{"word":"accord","pos":"n.","zh":"由同一词源经法语构成名词，义为「一致、协议」"},{"word":"accordance","pos":"n.","zh":"由动词加表示状态的名词尾构成，义为「符合」"},{"word":"according to","pos":"prep.","zh":"由分词加后置成分构成，义为「根据」"}]}},{"word":"additionally","ipa_uk":"/əˈdɪʃənəli/","ipa_us":"/əˈdɪʃənəli/","definition_zh":"此外；另外；而且；额外还","definition_en":"used to add a further point, item or figure to what has already been stated, without claiming that it matters more","core_image":"一张预算表已经写满三行，会计在下面又添了一行，笔尖没有划掉任何旧项","scene":"预算表上原本列着三项开支，会计又在下面添了第四行。The fee covers tuition and, additionally, all laboratory materials.","sceneCN":"这里指在主项之外再补一项（第 2 个义项：除主要项之外还有）；句意为这笔费用包括学费，此外还包括全部实验材料。场景要点：列满项目的预算表、被添上的第四行、未被划掉的旧项。","pos":[{"tag":"adv.","zh":"此外；另外；而且"}],"collocations":[{"phrase":"and additionally","zh":"并且此外"},{"phrase":"additionally, the report notes","zh":"此外，报告指出"},{"phrase":"additionally include","zh":"另外还包括"},{"phrase":"additionally charge","zh":"另行收费"},{"phrase":"additionally required","zh":"额外需要的"},{"phrase":"additionally, there is","zh":"此外还有"}],"forms":[{"label":"无词形变化（副词）","form":"additionally"}],"derivatives":[{"word":"addition","pos":"n.","zh":"由同一拉丁动词加表示动作结果的名词尾构成，义为「增加、追加物」"},{"word":"additional","pos":"adj.","zh":"由增加名词加形容词词尾构成，义为「额外的、附加的」"},{"word":"add","pos":"v.","zh":"由同一拉丁词干经法语缩合而成动词，义为「加、添加」"},{"word":"additive","pos":"n.","zh":"由添加动词加形容词兼名词词尾构成，义为「添加剂」"},{"word":"addendum","pos":"n.","zh":"由拉丁语「应加之物」直接借入，义为「补遗、附加条款」"}],"senses":[{"no":"01","title":"Besides, as a further point","titleCN":"此外，另补一点","definition":"introduces a separate point that stands beside the one just made, rather than replacing or deepening it","definitionCN":"引出一个与刚才那点并列的另一点，而不是替换或加深它","example":"The room is small; additionally, it has no window.","exampleCN":"这个房间很小，此外还没有窗。","why":"Addition is a giving to something already there, so the word places a new item beside the old one.","whyCN":"「增加」是往已有之物上再给一点，因此这个词把新项目放在旧项目旁边。"},{"no":"02","title":"In addition to the main item","titleCN":"除主要项之外还有","definition":"marks an extra element in a set of benefits, costs or conditions whose main element has already been named","definitionCN":"在一组好处、费用或条件中标出已点名的主项之外的额外成分","example":"The fee covers tuition and, additionally, all laboratory materials.","exampleCN":"这笔费用包括学费，此外还包括全部实验材料。","why":"A price or offer is read as a whole, and the adverb adds a part the reader might not assume.","whyCN":"价格或报价是被整体理解的，这个副词补上读者未必会想到的那一部分。"},{"no":"03","title":"A further figure in a tally","titleCN":"账目与统计中的追加数","definition":"used when a further number or category is added to a total already reported","definitionCN":"在已报出的总数上再加一个数字或类别时使用","example":"Travel costs rose and, additionally, two new posts were created.","exampleCN":"差旅费用上升，此外还新设了两个岗位。","why":"Figures are added one to another, which is the literal arithmetic sense of the word.","whyCN":"数字是一个加到一个上的，这正是这个词最字面的算术义。"},{"no":"04","title":"A second reason in an argument","titleCN":"论证中的第二条理由","definition":"marks the next supporting reason in a chain of argument, often in academic or analytical writing","definitionCN":"在论证链中标出下一条支持理由，常见于学术与分析性写作","example":"Additionally, the sample was too small to support the claim.","exampleCN":"此外，样本太小，不足以支持该主张。","why":"Written argument stacks reasons, and each new one is given rather than substituted.","whyCN":"书面论证把理由一层层堆起来，每一条都是新增而非替换。"},{"no":"05","title":"Sentence-initial formal signpost","titleCN":"句首正式衔接","definition":"the formal written opener, common in reports and essays, that announces an extra point before stating it","definitionCN":"正式书面开句方式，多见于报告与论文，先宣告还有一点再把它说出来","example":"Additionally, the survey was repeated in the following year.","exampleCN":"此外，这项调查在次年又重做了一次。","why":"A report needs visible order, so the extra point is flagged at the head of the sentence.","whyCN":"报告需要看得见的次序，因此额外的一点被放在句首标出。"},{"no":"06","title":"Mid-sentence parenthesis","titleCN":"句中插入补充","definition":"inserted between commas to slip in an extra remark without opening a new sentence","definitionCN":"用逗号夹在句中，塞进一句补充而不另起新句","example":"The plan, additionally, includes a second training phase.","exampleCN":"这项计划此外还包括第二阶段培训。","why":"The adverb can sit inside the clause, which lets an extra item be added without breaking the sentence's flow.","whyCN":"这个副词能坐在从句内部，于是补一项也不必打断句子的流动。"},{"no":"07","title":"A contractual extra obligation","titleCN":"合同中的附加义务","definition":"in specifications and agreements, a further requirement laid on top of those already stated","definitionCN":"在规格书与协议中，在已列要求之上再加一项","example":"The contractor shall, additionally, provide as-built drawings.","exampleCN":"承包方此外还应提供竣工图纸。","why":"Contracts are read item by item, and anything extra must be marked as extra.","whyCN":"合同是逐条读的，任何额外之事都必须标明为额外。"},{"no":"08","title":"Adding without ranking","titleCN":"只追加，不分主次","definition":"the nuance that the added point is not claimed to be more important than the first","definitionCN":"其中的细微差别：新加的一点并未被声称比第一点更重要","example":"Additionally suggests another item, not a weightier one.","exampleCN":"「此外」暗示的是又一项，而不是更重的一项。","why":"The word adds, and addition says nothing about rank, which separates it from moreover and furthermore.","whyCN":"这个词只做加法，而加法不谈高低，这正是它与「而且、再者」两类递进词的分界。"},{"no":"09","title":"A spoken move to the next point","titleCN":"口语中转向下一点","definition":"in speech and presentations, a soft signal that the speaker is adding one more item before closing","definitionCN":"在讲话与演示中，柔和地提示说话人要在收尾前再补一项","example":"Additionally, I want to raise the question of staff turnover.","exampleCN":"此外，我还想提一下人员流动的问题。","why":"Speech has no paragraph breaks, so the adverb does the work that layout does on a page.","whyCN":"口语没有段落分隔，于是这个词承担了版面上由排版承担的工作。"}],"etymology":{"intro":{"en":"Additionally is addition with -al and -ly. Addition comes from Latin addere, to give to, from ad- to and dare, to give. The word is literally a giving towards something that is already there.","cn":"additionally 是 addition 加 -al 再加 -ly。addition 来自拉丁语 addere「加给」，由 ad-「向」与 dare「给」构成。字面上，它就是往已有之物上再给一点。"},"items":[{"era":"LATIN DARE","en":"Dare meant to give, and it also stands behind data, the things given.","cn":"这个词意为「给」，data 即「被给出的东西」，也由它而来。"},{"era":"LATIN ADDERE","en":"The compound meant to give to, and so to add, annex or attach.","cn":"这个复合词意为「给到上面」，于是指添加、附加、附上。"},{"era":"LATIN ADDITIO","en":"The noun named both the act of adding and the thing added.","cn":"这个名词既指添加的动作，也指被添加之物。"},{"era":"OLD FRENCH AND ENGLISH ADDITION","en":"French passed the noun to English, where it covered arithmetic, building work and extra rooms alike.","cn":"法语把这个名词传给英语，它在英语里同时覆盖算术、加建工程与新增的房间。"},{"era":"ADDITIONAL + -LY","en":"The adjective marked what is extra, and the adverb was then formed to introduce an extra point; the date of its first use is uncertain.","cn":"形容词标记「额外」，副词再由它构成以引出额外的一点；其首次使用年代不确定。"},{"era":"MODERN REPORTS AND SPECIFICATIONS","en":"Reports, contracts and manuals made the adverb a standard signpost for one more item.","cn":"报告、合同与手册把这个副词固定成「还有一项」的标准标记。"}]},"similar":{"note":{"en":"The first group shares the adding stem; the second contains the other additive connectors it is weighed against.","cn":"第一组共享「添加」词干；第二组是拿来与它比较的其他递进连接词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"addition","ipa":"/əˈdɪʃn/","tag":"same root","definition":"The act of adding, or the thing added, including a part added to a building.","definitionCN":"指添加的动作或所加之物，也包括建筑的加建部分。"},{"word":"additional","ipa":"/əˈdɪʃənl/","tag":"same root","definition":"Extra, beyond what was already counted or agreed.","definitionCN":"指额外的、超出已计入或已商定范围的。"},{"word":"add","ipa":"/æd/","tag":"same root","definition":"To put one thing with another, or to perform the arithmetic operation.","definitionCN":"指把一物加到另一物上，也指做加法。"},{"word":"additive","ipa":"/ˈædɪtɪv/","tag":"same root","definition":"A substance added in small amounts for a particular purpose.","definitionCN":"指为特定目的少量加入的物质。"},{"word":"addendum","ipa":"/əˈdendəm/","tag":"same root","definition":"Something added at the end of a document; the plural is addenda.","definitionCN":"指文末所加之物，复数为 addenda。"}]},{"heading":"NEAR MEANING","entries":[{"word":"moreover","ipa":"/mɔːrˈəʊvə/","tag":"near meaning","definition":"Adds a point that is presented as stronger or more consequential, not merely extra.","definitionCN":"添加的一点被呈现为更有力或更要紧，而不只是额外。"},{"word":"furthermore","ipa":"/ˌfɜːðəˈmɔː/","tag":"near meaning","definition":"Adds a further point in formal argument, with a slightly heavier feel than additionally.","definitionCN":"在正式论证中再加一点，语气比 additionally 稍重。"},{"word":"besides","ipa":"/bɪˈsaɪdz/","tag":"near meaning","definition":"Adds a point in a looser, more conversational way, often as an afterthought.","definitionCN":"以更松散、更口语的方式补一点，常带「顺便说」的意味。"},{"word":"also","ipa":"/ˈɔːlsəʊ/","tag":"near meaning","definition":"The plain additive, usually mid-sentence and without the formal weight.","definitionCN":"最朴素的添加词，多居句中，不带正式分量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the giving inside the Latin verb, the arithmetic sense, and the real report phrases.","cn":"正常联想使用拉丁动词里的「给」、算术义，以及报告里的真实说法。"},"normal":[{"en":"Addere is ad plus dare, to give to: every addition is a gift laid on what is already there.","cn":"addere 是 ad 加 dare，即「给到上面」：每次添加都是往已有之物上放一份。"},{"en":"Data and addition share the Latin verb of giving, because data are things given.","cn":"「数据」与「添加」共享拉丁语里「给」这个动词，因为数据就是被给出的东西。"},{"en":"Addition is arithmetic before it is prose, which is why the word suits figures so well.","cn":"「添加」先是算术词，然后才是文章词，所以它配数字特别顺。"},{"en":"Additionally adds; moreover ranks, and furthermore formalises. Three different jobs.","cn":"这个词只做加法；另有词负责分轻重，另有词负责加正式度：三件不同的活。"},{"en":"In a contract, anything additional must be written as additional, or it will not be read as a duty.","cn":"在合同里，额外之事必须写成「额外」，否则不会被读成义务。"}],"abstract":[{"en":"An addition never argues with what is already there; it only asks for room.","cn":"添加从不与已有之物争辩，它只要求一点位置。"},{"en":"A list grows by consent, one item at a time, and the word is the sound of that consent.","cn":"清单是一项一项被同意着长起来的，这个词就是那声同意。"},{"en":"What is merely added can also be merely dropped, which is why ranking words exist.","cn":"只是被添加的东西，也可以只是被删掉，正因如此才另有分轻重的词。"}]},"examples":[{"en":"The flat is cheap; additionally, it is close to the station.","cn":"这套房子租金便宜，此外离车站也近。"},{"en":"Additionally, the insurer will pay for temporary accommodation.","cn":"此外，保险公司将支付临时住宿费用。"},{"en":"The course fee covers tuition and, additionally, two field trips.","cn":"课程费用包括学费，此外还包括两次实地考察。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「额滴神呐利」——清单上再加一行，不动前面的：此外、另外","word":"additionally"},"root":"拉丁语 dare「给」→ addere「加给」→ additio「添加」→ 古法语 addition → 英语 addition，再加形容词词尾与副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses differ by what is being added and where the word stands: a further point, an extra item, a further figure, a second reason, the formal sentence opener, the parenthesis, a contractual duty, the note that it adds without ranking, and the spoken move to a new item.","cn":"九个义项按「加什么」与「站在哪里」分开：另一点、额外一项、追加数字、第二条理由、正式句首、句中插入、合同附加义务、只加不分轻重、口语转向下一点。"},"semanticMap":{"core":{"en":"CORE IMAGE: a full list already written, and one more line added underneath without erasing anything above.","cn":"核心意象：清单已经写满，下面又添了一行，上面的字一个也没擦。"},"chain":["GIVEN","ADDED TO","ONE MORE ITEM","NOT RANKED","FORMAL SIGNPOST","SPOKEN TRANSITION"],"branches":[{"senses":"01","en":"THE FURTHER POINT: a separate remark placed beside the first.","cn":"另一点：一条与第一点并列的独立说法。"},{"senses":"02 · 03","en":"THE EXTRA ITEM AND THE FIGURE: a part added to an offer, a number added to a total.","cn":"额外项与追加数：给报价添一部分，给总数添一个数字。"},{"senses":"04 · 08","en":"THE SECOND REASON, UNABBED IN RANK: another support, with no claim that it is stronger.","cn":"第二条理由，且不分轻重：再加一条支持，并不声称它更有力。"},{"senses":"05 · 06","en":"THE WRITTEN SIGNPOST: at the head of a sentence, or slipped inside it.","cn":"书面标记：或放在句首，或塞进句中。"},{"senses":"07 · 09","en":"THE DUTY AND THE SPOKEN MOVE: a clause laid on a contract, a soft turn in speech.","cn":"义务与口语转向：合同上多出的一条，讲话中一次柔和的转折。"}]},"affixes":{"intro":{"en":"Additionally is a Latin verb wearing two English endings, and its family is one of the commonest in the language.","cn":"这个词是一个披着两个英语词尾的拉丁动词，它的词族是英语里最常见的之一。"},"latinIntro":{"en":"Latin supplies dare and addere; the noun additio passed through Old French, and English added -al and -ly.","cn":"拉丁语提供了「给」与「加给」两个动词；表示「添加」的名词经古法语传来，英语再加形容词词尾与副词词尾。"},"items":[{"word":"dare","structure":"Latin verb","meaning":"to give","meaningCN":"给","example":"The verb is the gift half of the compound.","exampleCN":"这个动词是复合词里「给」的那一半。"},{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向；朝","example":"It directs the giving towards what is already there.","exampleCN":"它把「给」指向已有之物。"},{"word":"addere","structure":"Latin verb","meaning":"to give to, add, annex","meaningCN":"加给；添加；附加","example":"The verb names putting one thing with another.","exampleCN":"这个动词指把一物加到另一物上。"},{"word":"additio","structure":"Latin noun from addere","meaning":"a giving to, an addition","meaningCN":"添加；附加物","example":"The noun covers both the act and its result.","exampleCN":"这个名词兼指动作与其结果。"},{"word":"addition","structure":"English noun through French","meaning":"the act or result of adding","meaningCN":"添加；追加物","example":"English uses it for sums, buildings and extra items alike.","exampleCN":"英语用它同时指算术、加建与额外项。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or belonging to","meaningCN":"属于……的","example":"It forms the adjective for what is extra.","exampleCN":"它构成表示「额外」的形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It forms the adverb that introduces an extra point.","exampleCN":"它构成引出额外一点的副词。"},{"word":"-ive","structure":"Latin adjective ending","meaning":"having the nature of","meaningCN":"具有……性质的","example":"It forms additive, a substance added for a purpose.","exampleCN":"它构成表示「为某目的加入之物」的名词。"}],"latinEntries":[{"word":"dare","structure":"Latin verb","meaning":"to give","meaningCN":"给"},{"word":"addere","structure":"Latin verb","meaning":"to give to, add","meaningCN":"加给；添加"},{"word":"additio","structure":"Latin noun","meaning":"a giving to, an addition","meaningCN":"添加；附加物"}],"derivatives":[{"word":"addition","pos":"n.","zh":"由同一拉丁动词加表示动作结果的名词尾构成，义为「添加」"},{"word":"additional","pos":"adj.","zh":"由增加名词加形容词词尾构成，义为「额外的」"},{"word":"add","pos":"v.","zh":"由同一词干经法语缩合而成动词，义为「添加」"},{"word":"additive","pos":"n.","zh":"由添加动词加形容词兼名词词尾构成，义为「添加剂」"},{"word":"addendum","pos":"n.","zh":"由拉丁语「应加之物」直接借入，义为「补遗」"}]}},{"word":"arguably","ipa_uk":"/ˈɑːɡjuəbli/","ipa_us":"/ˈɑːrɡjuəbli/","definition_zh":"可以说；有理由认为；可论证地；大概可以算作","definition_en":"used to present a claim as one that can be supported by argument or reason, while leaving room for disagreement","core_image":"一栋楼的评价被写在稿纸上，定论后面留着一小块空白，像给反驳留了座位","scene":"评审席上两个人对同一栋楼给出不同评价，评论家在稿子里写下一句带保留的定论。She is arguably the finest translator of her generation.","sceneCN":"这里指给最高级的判断留出余地（第 2 个义项：给最高级留余地）；句意为她大概可以算作她那一代最出色的译者。场景要点：两张不同评价的评审单、稿纸上带保留的句子、定论后留出的空白。","pos":[{"tag":"adv.","zh":"可以说；有理由认为"}],"collocations":[{"phrase":"arguably the best","zh":"可以说是最好的"},{"phrase":"arguably the most important","zh":"可以说是最重要的"},{"phrase":"arguably true","zh":"有理由认为成立"},{"phrase":"arguably a case of","zh":"可以说是……的一例"},{"phrase":"one could arguably say","zh":"可以说"},{"phrase":"arguably so","zh":"可以说确实如此"}],"forms":[{"label":"无词形变化（副词）","form":"arguably"}],"derivatives":[{"word":"argue","pos":"v.","zh":"由同一拉丁动词经法语构成，义为「论证、争辩」"},{"word":"arguable","pos":"adj.","zh":"由论证动词加表示「可……的」形容词词尾构成，义为「可论证的、有争议的」"},{"word":"argument","pos":"n.","zh":"由同一词源加表示行为结果的名词尾构成，义为「论证、争论」"},{"word":"argumentative","pos":"adj.","zh":"由论证名词加形容词词尾构成，义为「好争辩的、论证性的」"},{"word":"argumentation","pos":"n.","zh":"由论证动词加表示行为的名词尾构成，义为「论证过程」"}],"senses":[{"no":"01","title":"One can reasonably argue that","titleCN":"有理由认为","definition":"presents a statement as defensible on the evidence available, without claiming that it is settled","definitionCN":"把一项说法呈现为依现有证据站得住，但不声称它已成定论","example":"Arguably, the harbour scheme did more harm than good.","exampleCN":"可以说，那个港口方案弊大于利。","why":"Arguere means to make clear by argument, so the word offers a case rather than a verdict.","whyCN":"arguere 意为「用论证说清楚」，因此这个词给出的是一个理由，而不是一个判决。"},{"no":"02","title":"Softening a superlative","titleCN":"给最高级留余地","definition":"placed before the best, worst or most to mark a judgement that a reasonable person could dispute","definitionCN":"放在「最好的、最坏的、最……」之前，标明这是一个旁人可以有理由反对的判断","example":"She is arguably the finest translator of her generation.","exampleCN":"她大概可以算作她那一代最出色的译者。","why":"A superlative sounds absolute, and the adverb reopens the space that the superlative had closed.","whyCN":"最高级听起来绝对，这个副词把最高级关上的那扇门又推开一条缝。"},{"no":"03","title":"Hedging in academic writing","titleCN":"学术写作中的谨慎断言","definition":"used to avoid claiming proof where the evidence supports only a case","definitionCN":"在证据只能支持一种理由、不足以构成证明时，避免声称已经证明","example":"Arguably, the two variables are linked through a third factor.","exampleCN":"可以说，这两个变量是通过第三个因素联系起来的。","why":"Academic style needs a way to advance a thesis while leaving it open to challenge, and this is that way.","whyCN":"学术文体需要一种既能提出论点、又允许被质疑的说法，这个词就是那种说法。"},{"no":"04","title":"A concession to the other side","titleCN":"承认对方也有道理","definition":"used to grant that an opposing reading has force before answering it","definitionCN":"在回应之前先承认对立的读法确有分量","example":"Arguably, the earlier study was right about the direction of change.","exampleCN":"可以说，早先那项研究在变化方向上是对的。","why":"Granting a point is itself an argumentative move, and the word makes the grant without surrender.","whyCN":"承认一点本身就是一种论证动作，这个词让承认不至于变成投降。"},{"no":"05","title":"Framing a case in debate","titleCN":"辩论中为立论铺垫","definition":"opens a position that the speaker intends to support with reasons","definitionCN":"开启一个说话人打算用理由去支持的立场","example":"Arguably, the burden of proof lies with the applicant.","exampleCN":"可以说，举证责任在申请人一方。","why":"Debate needs an opening that invites reasons, and the word signals that reasons are coming.","whyCN":"辩论需要一个邀请理由进场的开场，这个词就提示理由随后就到。"},{"no":"06","title":"Questioning a claim in reply","titleCN":"反问式质疑","definition":"in reply, often stressed, hints that the claim is doubtful rather than granting it","definitionCN":"在应答中常带重音，暗示该说法可疑，而不是予以认可","example":"Arguably so, but the figures do not show it.","exampleCN":"可以说确实如此，但数字并不支持。","why":"The same word can grant and doubt, and stress is what turns the grant into a question.","whyCN":"同一个词既能认可也能怀疑，重音就是把认可变成疑问的那一下。"},{"no":"07","title":"Provable in principle","titleCN":"逻辑上可论证","definition":"the literal sense: capable of being supported by argument, whether or not anyone has yet done so","definitionCN":"字面义：能够被论证支持，无论是否已有人论证过","example":"The result is arguably true for any finite sample.","exampleCN":"这一结果对任何有限样本都可论证为真。","why":"The adverb is built on arguable, and arguable means open to argument, not merely likely.","whyCN":"这个副词由「可论证的」这一形容词构成，而该形容词指「可供论证」，并不等于「很可能」。"},{"no":"08","title":"The reviewer's evaluative tone","titleCN":"评论文字中的评价语气","definition":"the critic's way of giving a firm opinion while leaving the formal claim unasserted","definitionCN":"评论者给出明确看法、却不把话说成事实的方式","example":"It is arguably the most important building of the decade.","exampleCN":"它大概可以算作这十年里最重要的一座建筑。","why":"Reviewing lives on judgements that cannot be proved, so it needs a form of words that sounds decided but stays open.","whyCN":"评论靠的是无法证明的判断，因此它需要一种听上去已定、实则留口的措辞。"},{"no":"09","title":"Not the same as probably","titleCN":"与「很可能」的分界","definition":"the word claims that a case can be made, not that the event is likely","definitionCN":"这个词声称的是「能立论」，而不是「事情很可能发生」","example":"Arguably does not mean probably; it means a case can be made.","exampleCN":"「可以说」并不是「很可能」，它的意思是能够给出理由。","why":"The word is built on arguable, which concerns reasons rather than chances, so the probability reading loses its whole point.","whyCN":"这个词建立在「可论证的」这一形容词之上，而可论证关心的是理由而不是机会，因此读成概率就丢了全部要点。"}],"etymology":{"intro":{"en":"Arguably is arguable plus -ly, from argue, which comes from Latin arguere, to make clear, prove or accuse, through Old French arguer. The English hedging use is recent: the word offers a case, not a probability.","cn":"arguably 是 arguable 加 -ly，源自 argue；argue 经古法语 arguer 来自拉丁语 arguere「使清楚、证明、指控」。英语里这种留余地的用法出现较晚：它给出的是一个理由，而不是一个概率。"},"items":[{"era":"LATIN ARGUERE","en":"The verb meant to make clear, demonstrate or prove, and also to accuse or bring a charge.","cn":"这个动词意为使清楚、演示、证明，也指指控、提出罪状。"},{"era":"OLD FRENCH ARGUER","en":"French narrowed the word towards reasoning and pleading in a dispute.","cn":"法语把这个词收窄到争议中的推理与申辩。"},{"era":"ENGLISH ARGUE","en":"English kept both faces: setting out reasons, and quarrelling.","cn":"英语把两副面孔都留下了：摆出理由，以及争吵。"},{"era":"ARGUABLE","en":"The adjective meant open to argument, and later also disputable.","cn":"这个形容词意为可供论证，后来也指有争议。"},{"era":"ARGUABLY, 20TH CENTURY","en":"The hedge became common in journalism and scholarship in the twentieth century; the exact date of that shift is uncertain.","cn":"这种弱化用法在二十世纪的新闻与学术写作中变得常见；这一转变的确切年代不确定。"},{"era":"MODERN EVALUATIVE USE","en":"Reviewers and analysts now use it to sound decided without making a claim they would have to defend as fact.","cn":"评论者与分析者现在用它显得有定见，又不至于把话说成必须当作事实来辩护。"}]},"similar":{"note":{"en":"The first group shares the arguing stem; the second holds the hedges it is most often confused with.","cn":"第一组共享「论证」词干；第二组是常与它混淆的几种留余地说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"argue","ipa":"/ˈɑːɡjuː/","tag":"same root","definition":"To give reasons for a position, or to disagree noisily.","definitionCN":"指为某立场给出理由，也指大声争执。"},{"word":"arguable","ipa":"/ˈɑːɡjuəbl/","tag":"same root","definition":"Open to argument, and in another use, doubtful.","definitionCN":"指可供论证，另一用法指可疑。"},{"word":"argument","ipa":"/ˈɑːɡjumənt/","tag":"same root","definition":"A set of reasons, and also a quarrel.","definitionCN":"指一组理由，也指争吵。"},{"word":"argumentative","ipa":"/ˌɑːɡjuˈmentətɪv/","tag":"same root","definition":"Given to arguing, or relating to argument as a form.","definitionCN":"指好争辩的，或与论证形式有关的。"},{"word":"argumentation","ipa":"/ˌɑːɡjuːmenˈteɪʃn/","tag":"same root","definition":"The systematic construction of arguments.","definitionCN":"指系统地构造论证。"}]},{"heading":"NEAR MEANING","entries":[{"word":"presumably","ipa":"/prɪˈzjuːməbli/","tag":"near meaning","definition":"Marks what may reasonably be assumed from what is known.","definitionCN":"标记依已知情况可合理假定的事。"},{"word":"conceivably","ipa":"/kənˈsiːvəbli/","tag":"near meaning","definition":"Marks what can be imagined as possible, with no claim of support.","definitionCN":"标记可以想象为可能的事，不声称有依据。"},{"word":"supposedly","ipa":"/səˈpəʊzɪdli/","tag":"near meaning","definition":"Reports what is said to be so, often with doubt attached.","definitionCN":"转述据说如此，常带怀疑。"},{"word":"perhaps","ipa":"/pəˈhæps/","tag":"near meaning","definition":"The plain marker of possibility, about likelihood rather than argument.","definitionCN":"最朴素的可能标记，谈的是概率而非论证。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of proving, the real argument family, and the hedging habit of reviewers.","cn":"正常联想使用拉丁语「证明」的动词、真实的论证词族，以及评论者留余地的习惯。"},"normal":[{"en":"Arguere is to make clear by argument, so arguably offers clarity that is still open to challenge.","cn":"拉丁语里那个表示「用论证说清」的动词，给的是仍可被质疑的清楚。"},{"en":"Argue, argument, arguable and arguably are one family, one root, four jobs.","cn":"论证、论证性、可论证、可以说，四者同出一根，四份差事。"},{"en":"Put it before a superlative and the absolute claim grows a door.","cn":"把它放在最高级前面，绝对的说法就多了一扇门。"},{"en":"In a seminar, arguably is the polite way to say here is my case, now test it.","cn":"在研讨课上，「可以说」是「这是我的理由，请来检验」的礼貌说法。"},{"en":"It does not measure probability: it measures whether reasons exist.","cn":"它衡量的不是概率，而是有没有理由。"}],"abstract":[{"en":"A claim that cannot be wrong is not an argument; arguably keeps the claim exposed on purpose.","cn":"不会错的主张不是论证；这个词故意让主张保持暴露。"},{"en":"The word is a door left ajar in a sentence that would otherwise be shut.","cn":"这个词是一句本已关上、却被留了一条缝的话。"},{"en":"Authority says it is so; arguably says here is why it might be so.","cn":"权威说事情就是这样；这个词说，这是它可能如此的理由。"}]},"examples":[{"en":"Arguably, the second design is the safer of the two.","cn":"可以说，第二个设计是两者中更安全的一个。"},{"en":"He is arguably the most influential critic writing today.","cn":"他大概可以算作当今最有影响力的评论家。"},{"en":"The delay was arguably caused by the change in specification.","cn":"可以说，延期是由规格变更造成的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿格优厄布利」——他也能讲出一套理由，但话还留着余地：可以说","word":"arguably"},"root":"拉丁语 arguere「使清楚、证明、指控」→ 古法语 arguer → 英语 argue → arguable，再加副词词尾构成。直接来源清楚；作弱化断言的用法为二十世纪发展，确切首见年代不确定。","sensesIntro":{"en":"Nine senses vary the strength and target of the hedge: a defensible claim, a softened superlative, academic caution, a concession, a debate opening, a doubting reply, the literal sense of being arguable, the reviewer's tone, and the line between a case and a probability.","cn":"九个义项改变的是留余地的力度与对象：站得住的主张、被软化的最高级、学术上的谨慎、对对方的让步、辩论开场、带疑的应答、字面上的「可论证」、评论者的语气，以及「能立论」与「很可能」的分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a verdict written on a page, with a small blank left beside it where a challenge may sit.","cn":"核心意象：纸页上写下的一句定论，旁边留着一小块空白，给反驳留着座位。"},"chain":["A CLAIM","REASONS OFFERED","CASE MADE","ROOM LEFT OPEN","DISPUTE EXPECTED","JUDGEMENT WITHOUT VERDICT"],"branches":[{"senses":"01 · 07","en":"THE DEFENSIBLE CLAIM: reasons can be given, whether or not anyone has given them yet.","cn":"站得住的主张：理由给得出，至于是否已给出则不论。"},{"senses":"02 · 08","en":"THE SOFTENED VERDICT: a superlative reopened, a review that sounds decided but stays open.","cn":"被软化的定论：最高级被重新推开，评论听来已定却仍留口。"},{"senses":"03 · 05","en":"THE ACADEMIC AND DEBATE HEDGE: caution in a paper, an opening that invites reasons.","cn":"学术与辩论中的留余地：论文里的谨慎，辩论里邀请理由进场的开场。"},{"senses":"04","en":"THE CONCESSION: the other side is granted its force before the answer comes.","cn":"让步：在回应之前，先承认对方那一面确有分量。"},{"senses":"06 · 09","en":"THE DOUBT AND THE LIMIT: a stressed reply that questions, and the refusal to mean probably.","cn":"疑问与界限：带重音的应答表示怀疑，以及它并不等于「很可能」。"}]},"affixes":{"intro":{"en":"Arguably is a Latin verb of proving, filtered through French, wearing an English adjective ending and an adverb ending.","cn":"arguably 是一个经法语过滤的拉丁「证明」动词，套着英语的形容词词尾与副词词尾。"},"latinIntro":{"en":"Latin supplies arguere and argumentum; Old French supplies arguer, and English builds argue, arguable and arguably on the same stem.","cn":"拉丁语提供了 arguere 与 argumentum；古法语提供了 arguer，英语在同一词干上造出 argue、arguable 与 arguably。"},"items":[{"word":"arguere","structure":"Latin verb","meaning":"to make clear, prove, accuse","meaningCN":"使清楚；证明；指控","example":"The verb carries both proving and accusing.","exampleCN":"这个动词同时带着「证明」与「指控」。"},{"word":"argumentum","structure":"Latin noun","meaning":"a proof, an argument, a subject","meaningCN":"证明；论证；题材","example":"The noun names what the verb produces.","exampleCN":"这个名词指动词所产出之物。"},{"word":"arguer","structure":"Old French verb","meaning":"to reason, plead, dispute","meaningCN":"推理；申辩；争执","example":"French carried the word into English use.","exampleCN":"法语把这个词带入英语用法。"},{"word":"argue","structure":"English verb","meaning":"to give reasons, to dispute","meaningCN":"给出理由；争辩","example":"English keeps the reasoned and the quarrelsome sense.","exampleCN":"英语兼留「讲理」与「争吵」两义。"},{"word":"arguable","structure":"English adjective","meaning":"open to argument, disputable","meaningCN":"可供论证的；有争议的","example":"The suffix makes a claim that reasons can reach it.","exampleCN":"词尾造出一个「理由够得着」的说法。"},{"word":"-able","structure":"Latin adjective ending","meaning":"capable of being","meaningCN":"能被……的","example":"It turns the verb into a possibility.","exampleCN":"它把动词变成一种可能性。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the hedge adverb from the adjective.","exampleCN":"它由形容词构成这个留余地的副词。"},{"word":"-ment","structure":"Latin noun ending","meaning":"result of an action","meaningCN":"动作的结果","example":"It forms argument, the thing produced.","exampleCN":"它构成 argument，即产出之物。"}],"latinEntries":[{"word":"arguere","structure":"Latin verb","meaning":"to make clear, prove, accuse","meaningCN":"使清楚；证明"},{"word":"argumentum","structure":"Latin noun","meaning":"a proof, an argument","meaningCN":"证明；论证"}],"derivatives":[{"word":"argue","pos":"v.","zh":"由同一拉丁动词经法语构成，义为「论证、争辩」"},{"word":"arguable","pos":"adj.","zh":"由论证动词加「可……的」形容词词尾构成，义为「可论证的」"},{"word":"argument","pos":"n.","zh":"由同一词源加表示行为结果的名词尾构成，义为「论证」"},{"word":"argumentative","pos":"adj.","zh":"由论证名词加形容词词尾构成，义为「好争辩的」"},{"word":"argumentation","pos":"n.","zh":"由论证动词加表示行为的名词尾构成，义为「论证过程」"}]}},{"word":"consequently","ipa_uk":"/ˈkɒnsɪkwəntli/","ipa_us":"/ˈkɑːnsəkwentli/","definition_zh":"因此；所以；结果是；随之而来","definition_en":"used to say that something happens as a result of what has just been stated, reporting the consequence as an observed fact","core_image":"上游水位上涨一格，下游的记录纸上跟着多出一行，原因与结果各占一行","scene":"连日降雨让上游水位上涨，管理站在下游的记录纸上又添了一行。The reservoir filled within a week and, consequently, the fields below were flooded.","sceneCN":"这里指陈述一个客观发生的后果（第 1 个义项：客观结果）；句意为水库一周之内就蓄满了，结果下面的田地受了淹。场景要点：上涨的水位、追加的一行记录、被淹的田地。","pos":[{"tag":"adv.","zh":"因此；所以；结果是"}],"collocations":[{"phrase":"and consequently","zh":"因而；并因此"},{"phrase":"consequently, the number of","zh":"因此，……的数量"},{"phrase":"consequently, many families","zh":"因此，许多家庭……"},{"phrase":"consequently less","zh":"因此更少"},{"phrase":"consequently unable to","zh":"因此无法……"},{"phrase":"consequently, the results","zh":"因此，结果……"}],"forms":[{"label":"无词形变化（副词）","form":"consequently"}],"derivatives":[{"word":"consequent","pos":"adj.","zh":"由拉丁语动词的现在分词词干加形容词词尾构成，义为「随之而来的、作为结果的」"},{"word":"consequence","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「后果、结果」"},{"word":"consequential","pos":"adj.","zh":"由结果名词加表示「属于……的」形容词词尾构成，义为「重大的、随之引发的」"},{"word":"inconsequential","pos":"adj.","zh":"由结果形容词加否定前缀构成，义为「无关紧要的」"},{"word":"consequentialism","pos":"n.","zh":"由结果形容词加表示学说体系的名词尾构成，义为「后果论」"}],"senses":[{"no":"01","title":"An effect that follows a cause","titleCN":"客观结果","definition":"marks an effect that follows from what has just been said, stated as fact, with no blame attached and no advice offered","definitionCN":"标出由前述之事引出的结果，只作事实陈述，既不带责怪，也不给建议","example":"The bridge was closed for repairs and consequently the ferry ran full.","exampleCN":"大桥因维修关闭，结果渡轮上挤满了人。","why":"Consequi is Latin for to follow close behind; the word reports a following, not a judgement.","whyCN":"这个词的拉丁语动词意为紧紧跟随；它报告的是跟随，不是评判。"},{"no":"02","title":"Sentence-initial in formal writing","titleCN":"句首正式衔接","definition":"placed first in a report or paper so that the reader meets the outcome before the supporting detail","definitionCN":"置于报告或论文的句首，让读者先看到结果，再看支撑细节","example":"Consequently, the second phase began three months late.","exampleCN":"因此，第二阶段晚了三个月才开始。","why":"A report puts the result at the head of the sentence because the result is what the reader is looking for.","whyCN":"报告把结果放在句首，因为读者要找的正是结果。"},{"no":"03","title":"The parenthesis inside the clause","titleCN":"句中插入","definition":"set between commas after the subject or auxiliary, where the causal link rides along more lightly","definitionCN":"用逗号夹在主语或助动词之后，因果衔接随之变轻","example":"The soil, consequently, lost much of its nitrogen.","exampleCN":"土壤因此失去了大部分氮。","why":"An adverb inside the clause lets the link travel with the subject instead of governing the whole sentence.","whyCN":"放在从句内部的副词让衔接跟着主语走，而不去支配整句。"},{"no":"04","title":"The joined result after and","titleCN":"并列结构中的「因而」","definition":"attached after and, it joins a second result to the first inside one unbroken clause rather than opening a new sentence","definitionCN":"紧接在表示并列的连接词之后，把第二个结果与第一个并排接在同一句里，而不另起一句","example":"The pipe froze and consequently burst during the night.","exampleCN":"管子冻住了，因而在夜里爆裂。","why":"Two results belong to the same event, and the joining word keeps them in one breath.","whyCN":"两个结果同属一件事，连接词把它们留在同一口气里。"},{"no":"05","title":"One joint in a chain of effects","titleCN":"因果链中的一环","definition":"used where an effect becomes the cause of the next effect, so that the word marks each joint in the chain","definitionCN":"用于一个结果又成为下一个结果之因的场合，标出链条上的每一处接缝","example":"The dam raised the water table, and consequently the roots of the old trees rotted.","exampleCN":"大坝抬高了地下水位，结果老树的根烂掉了。","why":"In a chain, one effect is also a cause, and the word marks the turn from one to the other.","whyCN":"在链条上，一个结果同时也是原因，这个词标记的就是从那一个转向下一个的地方。"},{"no":"06","title":"A conclusion drawn from premises","titleCN":"演绎得出的结论","definition":"in formal argument, marks a conclusion that follows from the premises rather than an event caused by another event","definitionCN":"在正式论证中，标出一个由前提推出的结论，而不是由事件引起的事件","example":"The premises are true; consequently, the conclusion must be true.","exampleCN":"前提为真；因此结论必然为真。","why":"A deduction is a following of another kind: the conclusion follows from the premises, not in time.","whyCN":"演绎是另一种跟随：结论从前提里跟出来，而不是在时间上跟在后面。"},{"no":"07","title":"A report, not a response","titleCN":"只报结果，不规定应对","definition":"the line between this word and accordingly: consequently stops at what happened, while accordingly adds what someone did about it","definitionCN":"与「据此办理」那类词的分界：这一个停在发生了什么，另一个还要说出人做了什么","example":"Consequently reports what followed; accordingly tells you what to do about it.","exampleCN":"这一个只报告随后发生了什么；另一个才告诉你该据此做什么。","why":"Reporting and instructing are different jobs, and English keeps separate words for them.","whyCN":"报告与指示是两件事，英语为它们分别留了词。"},{"no":"08","title":"Not the same as hence","titleCN":"与「由此」的分界","definition":"the line between this word and hence: hence may stand before a bare noun phrase, while consequently needs a full clause","definitionCN":"与「由此」的分界：那个词可以直接接名词短语，这个词必须接一个完整小句","example":"One writes hence the name, never consequently the name.","exampleCN":"人们会写「由此得名」，却不会用这个词去接「得名」。","why":"Hence has a wider reach in formal prose, which is why it can introduce a phrase rather than a clause.","whyCN":"那个词在正式文章里管得更宽，所以它能引出短语而不只是小句。"},{"no":"09","title":"A loose link in speech","titleCN":"口语中的松散因果","definition":"in speech and informal narrative, a light causal link close to so, but with more weight than the short word carries","definitionCN":"在口语与非正式叙述中，一种接近「所以」的轻因果，但比那个短词更有分量","example":"I left my card at home, and consequently I could not pay.","exampleCN":"我把卡忘在家里，结果付不了钱。","why":"Spoken links are often loose, and the word merely sets one fact after another without a formal claim.","whyCN":"口语里的连接常常松散，这个词只是把一件件事排好，并不作正式断言。"}],"etymology":{"intro":{"en":"Consequently is consequent plus -ly. Consequent comes from Latin consequens, the present participle of consequi, to follow after, built on com- together and sequi to follow. The adverb adds the manner: in a way that follows.","cn":"这个词由形容词加副词词尾构成；形容词来自拉丁语 consequens，即 consequi「随后而来」的现在分词，由 com-「共同」与 sequi「跟随」构成。副词再加上方式：以随之而来的方式。"},"items":[{"era":"LATIN SEQUI","en":"Sequi meant to follow, and it stands behind the English words for a sequel, a sequence and what comes after.","cn":"这个词意为「跟随」，「续集」「序列」「随后的」等英语词都由它而来。"},{"era":"LATIN CONSEQUI","en":"Com- plus sequi made a verb of following closely, and so of resulting.","cn":"com- 加 sequi 构成动词，意为紧紧跟随，因而指结果。"},{"era":"LATIN CONSEQUENS","en":"The participle described what follows, and the noun consequentia named the following itself.","cn":"这个分词描述「跟随的」，名词 consequentia 则指跟随本身。"},{"era":"ENGLISH CONSEQUENT AND CONSEQUENCE","en":"English took both the adjective and the noun: what follows, and what follows as a result.","cn":"英语把形容词与名词都借了进来：随后之事，以及作为结果之事。"},{"era":"CONSEQUENTLY","en":"The adverb was formed on the adjective to mark a clause as a result; the exact date of its first use is uncertain.","cn":"副词由形容词构成，用来把一个小句标为结果；其首次使用的确切年代不确定。"},{"era":"MODERN ACADEMIC PROSE","en":"Reports and papers made it one of the standard markers of a stated consequence.","cn":"报告与论文使它成为陈述结果的标准标记之一。"}]},"similar":{"note":{"en":"The first group shares the following stem; the second holds the causal connectors it is measured against.","cn":"第一组共享「跟随」这一词干；第二组是拿来与它权衡的因果类连接词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consequent","ipa":"/ˈkɒnsɪkwənt/","tag":"same root","definition":"Following as a result; also the second half of a conditional statement.","definitionCN":"指作为结果而随之而来的，也指条件句的后件。"},{"word":"consequence","ipa":"/ˈkɒnsɪkwəns/","tag":"same root","definition":"A result, especially one that is unwelcome or important.","definitionCN":"指结果，尤指不受欢迎或重要的结果。"},{"word":"consequential","ipa":"/ˌkɒnsɪˈkwenʃl/","tag":"same root","definition":"Important in its effects, or following from something else.","definitionCN":"指影响重大的，或由他事引出的。"},{"word":"consecutive","ipa":"/kənˈsekjətɪv/","tag":"same root","definition":"Following one after another without a break.","definitionCN":"指一个接一个、中间不断的。"},{"word":"conscientious","ipa":"/ˌkɒnʃiˈenʃəs/","tag":"different root","definition":"From Latin scire, to know, not from sequi; it means careful to do what is right, and has nothing to do with following.","definitionCN":"来自拉丁语「知道」而非「跟随」；意为认真尽责，与「随后」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"therefore","ipa":"/ˈðeəfɔː/","tag":"near meaning","definition":"The plain marker of a conclusion, equally at home in speech and in writing.","definitionCN":"最朴素的结论标记，口语与书面同样适用。"},{"word":"hence","ipa":"/hens/","tag":"near meaning","definition":"A formal marker of inference that can also introduce a noun phrase.","definitionCN":"正式的推论标记，还能直接引出名词短语。"},{"word":"accordingly","ipa":"/əˈkɔːdɪŋli/","tag":"near meaning","definition":"Marks a response fitted to the facts just stated, not merely the result.","definitionCN":"标记依前述事实作出的应对，而不只是结果。"},{"word":"so","ipa":"/səʊ/","tag":"near meaning","definition":"The short spoken connector, quick and unemphatic.","definitionCN":"口语里的短连接词，轻快而不加重。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of following, the real consequent family, and the ledger position the word likes.","cn":"正常联想使用拉丁语「跟随」的动词、真实的同族词，以及这个词偏爱的账本位置。"},"normal":[{"en":"Sequi is to follow, so consequently says only that one thing came after another.","cn":"词根意为「跟随」，所以这个词只说一件事跟在另一件事后面。"},{"en":"Consequent, consequence and consequently share one stem: the following, and then the marker of the following.","cn":"「随后的」「结果」「因此」三个词共享一个词干：先是跟随，再是标记跟随。"},{"en":"Put it after the cause and before the effect, and the sentence reads like a ledger.","cn":"把它放在原因之后、结果之前，句子就像一本账。"},{"en":"It reports; accordingly instructs. One looks back at what happened, the other leans forward to what should be done.","cn":"它只报告；「据此」才下达应对。前者回头看发生了什么，后者向前看该做什么。"},{"en":"Hence can stand before a bare noun phrase; consequently needs a clause with a verb in it.","cn":"「由此」可以直接接名词短语，这个词则必须接一个带动词的小句。"}],"abstract":[{"en":"A consequence is a fact with a parent, and the word points at the parent.","cn":"结果是带着出身的事实，这个词只负责指出它的出身。"},{"en":"On a chain of effects every link is both child and parent; the word marks the joint.","cn":"在因果链上，每一环都既是孩子又是父母，这个词只标记那个接缝。"},{"en":"The word does not ask whether the result was wanted; it only says that it followed.","cn":"这个词不问结果是否被人想要，它只说结果跟了上来。"}]},"examples":[{"en":"The factory closed, and consequently the town lost a third of its jobs.","cn":"工厂关闭，小镇因此失去了三分之一的工作岗位。"},{"en":"Consequently, the experiment had to be repeated under drier conditions.","cn":"因此，这项实验不得不在更干燥的条件下重做。"},{"en":"Rainfall was well below average; consequently, the reservoir did not refill.","cn":"降雨量远低于平均，结果水库没有重新蓄满。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康西宽特利」——事情跟着事情走，前一件完了后一件就来：因此","word":"consequently"},"root":"拉丁语 sequi「跟随」→ consequi「紧随而来」（com-「共同」＋sequi）→ consequens「随后的」→ 英语 consequent／consequence → 加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses vary the place and the kind of following: an observed effect, the formal sentence opener, the parenthesis, the final position, a link in a chain, a deduction, the line against a response word, the line against a phrase-taking word, and the loose spoken link.","cn":"九个义项改变的是「跟随」的种类与位置：客观结果、正式句首、句中插入、句末、因果链的一环、演绎结论、与「据此」类词的分界、与可接短语之词的分界、口语中的松散因果。"},"semanticMap":{"core":{"en":"CORE IMAGE: the water gauge rises one notch, and a new line is written on the record sheet below it.","cn":"核心意象：水位计上涨一格，下面的记录纸上就多写一行。"},"chain":["CAUSE","FOLLOWS","CONSEQUENCE","FORMAL SIGNPOST","CHAIN OF EFFECTS","DRAWN CONCLUSION"],"branches":[{"senses":"01 · 09","en":"THE OBSERVED EFFECT: a result stated as fact, including its looser spoken form.","cn":"观察到的结果：被当作事实陈述的结果，也包括口语里较松散的用法。"},{"senses":"02 · 03","en":"THE WRITTEN POSITIONS: at the head of the clause, or carried inside it.","cn":"书面位置：或置于小句之首，或带在小句之中。"},{"senses":"04","en":"THE JOINED RESULT: a second consequence tied to the first by and.","cn":"并列结果：第二个后果被「和」接在第一个后面。"},{"senses":"05 · 06","en":"THE CHAIN AND THE PROOF: one effect causing the next, and a conclusion following from premises.","cn":"链条与证明：一个结果引出下一个，以及由前提推出的结论。"},{"senses":"07 · 08","en":"THE TWO BOUNDARIES: it neither prescribes a response nor takes a noun phrase.","cn":"两条边界：它既不规定应对，也不直接带名词短语。"}]},"affixes":{"intro":{"en":"Consequently is a Latin verb of following, wearing an adjective ending and an English adverb ending.","cn":"这个词是一个表示「跟随」的拉丁动词，套着形容词词尾与英语副词词尾。"},"latinIntro":{"en":"Latin supplies sequi, consequi and consequens; English supplies consequent, consequence and the endings.","cn":"拉丁语提供了 sequi、consequi 与 consequens；英语提供了 consequent、consequence 与两个词尾。"},"items":[{"word":"sequi","structure":"Latin verb","meaning":"to follow","meaningCN":"跟随","example":"The verb is the whole idea of the word.","exampleCN":"这个动词就是这个词的全部意思。"},{"word":"con-","structure":"Latin prefix","meaning":"together, wholly","meaningCN":"共同；彻底","example":"It gives the following a sense of closeness.","exampleCN":"它给「跟随」加上紧贴的意思。"},{"word":"consequi","structure":"Latin verb","meaning":"to follow after, result","meaningCN":"随后而来；结果","example":"The compound verb names a following that produces something.","exampleCN":"这个复合动词指一种会产出结果的跟随。"},{"word":"consequens","structure":"Latin participle","meaning":"following, resulting","meaningCN":"跟随的；随之而来的","example":"The participle becomes the English adjective.","exampleCN":"这个分词成为英语的形容词。"},{"word":"consequentia","structure":"Latin noun","meaning":"a following, a consequence","meaningCN":"跟随；结果","example":"The noun names the thing that follows.","exampleCN":"这个名词指跟随而来的那个东西。"},{"word":"consequent","structure":"English adjective","meaning":"following as a result","meaningCN":"随之而来的","example":"English builds the adjective on the Latin participle.","exampleCN":"英语在这个拉丁分词上造出形容词。"},{"word":"-ent","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于……状态的","example":"It marks the participle as an adjective.","exampleCN":"它把分词标成形容词。"},{"word":"-ence","structure":"Latin noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of the result.","exampleCN":"它构成表示结果的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the adverb that marks a clause as a result.","exampleCN":"它构成把一个小句标为结果的副词。"}],"latinEntries":[{"word":"sequi","structure":"Latin verb","meaning":"to follow","meaningCN":"跟随"},{"word":"consequi","structure":"Latin verb","meaning":"to follow after, result","meaningCN":"随后而来；结果"},{"word":"consequens","structure":"Latin participle","meaning":"following, resulting","meaningCN":"跟随的"},{"word":"consequentia","structure":"Latin noun","meaning":"a following, a consequence","meaningCN":"跟随；结果"},{"word":"con-","structure":"Latin prefix","meaning":"together, wholly","meaningCN":"共同；彻底"}],"derivatives":[{"word":"consequent","pos":"adj.","zh":"由拉丁语现在分词词干加形容词词尾构成，义为「随之而来的」"},{"word":"consequence","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「后果」"},{"word":"consequential","pos":"adj.","zh":"由结果名词加表示所属的形容词词尾构成，义为「重大的」"},{"word":"inconsequential","pos":"adj.","zh":"由结果形容词加否定前缀构成，义为「无关紧要的」"},{"word":"consequentialism","pos":"n.","zh":"由结果形容词加表示学说的名词尾构成，义为「后果论」"}]}},{"word":"conversely","ipa_uk":"/ˈkɒnvɜːsli/","ipa_us":"/ˈkɑːnvɜːrsli/","definition_zh":"反之；反过来；相反地；从另一面看","definition_en":"used to state the reverse of a relation just given, so that the two sides exchange places while both remain true","core_image":"对照表上左右两列被对调，箭头掉头，数字一个没改","scene":"研究者在两栏对照表上把左右两列对调，箭头也跟着掉头。The larger the sample, the steadier the result; conversely, a small sample gives a weaker signal.","sceneCN":"这里指把同一关系的两端调换（第 1 个义项：反向对照）；句意为样本越大结果越稳，反过来，样本小则信号更弱。场景要点：对调的两列、掉头的箭头、未被改动的数字。","pos":[{"tag":"adv.","zh":"反之；反过来；相反地"}],"collocations":[{"phrase":"and conversely","zh":"反之亦然"},{"phrase":"conversely, the same is true","zh":"反过来也一样"},{"phrase":"conversely, a smaller","zh":"反之，较小的……"},{"phrase":"or conversely","zh":"或者反过来"},{"phrase":"conversely, one might","zh":"反之，人们可能……"},{"phrase":"conversely, if","zh":"反过来，如果……"}],"forms":[{"label":"无词形变化（副词）","form":"conversely"}],"derivatives":[{"word":"converse","pos":"adj.","zh":"由拉丁语「翻转」的过去分词构成形容词，义为「相反的、逆的」"},{"word":"conversion","pos":"n.","zh":"由翻转动词加表示动作结果的名词尾构成，义为「转变、转换」"},{"word":"convert","pos":"v.","zh":"由同一词干经法语构成动词，义为「转变、改变」"},{"word":"convertible","pos":"adj.","zh":"由转变动词加「可……的」形容词词尾构成，义为「可转换的」"}],"senses":[{"no":"01","title":"The reverse of a stated relation","titleCN":"反向对照","definition":"marks the same relation taken from the other end, so that the two sides change places and both statements stay true","definitionCN":"把同一种关系从另一端说起，两边调换位置，而两句话都仍然成立","example":"The more a material is heated, the more it expands; conversely, cooling makes it contract.","exampleCN":"材料受热越多膨胀越大；反过来，冷却使它收缩。","why":"Vertere is to turn, and the word turns a relation round to face the other way.","whyCN":"这个词的拉丁语动词意为「转」，它把一种关系转过来，朝向另一边。"},{"no":"02","title":"Sentence-initial in formal writing","titleCN":"句首正式衔接","definition":"opens a sentence in academic or report prose to announce that the mirror image of the previous claim now follows","definitionCN":"在学术或报告文字中开句，宣告上一说法的镜像现在出场","example":"Conversely, households on lower incomes spent a larger share on food.","exampleCN":"反过来，收入较低的家庭把更大比例的钱花在食物上。","why":"Formal prose likes symmetry, and the opener tells the reader that the mirror half is coming.","whyCN":"正式文章喜欢对称，这个句首词告诉读者镜像的那一半要来了。"},{"no":"03","title":"The parenthesis inside the clause","titleCN":"句中插入","definition":"set between commas to bring in the other side without breaking the sentence's main line","definitionCN":"用逗号夹在句中，把另一面带进来而不打断句子的主线","example":"Older workers, conversely, preferred the earlier shift.","exampleCN":"反过来，年纪较大的工人更喜欢早一点的班次。","why":"Inside the clause the word works like a small hinge rather than a full stop.","whyCN":"放在小句内部，这个词像一个小铰链，而不是一个句号。"},{"no":"04","title":"A falling line in a graph","titleCN":"图表中的反向走向","definition":"used in describing figures, where one curve rises as the other falls, so that the two move in opposite directions","definitionCN":"用于描述数据，一条曲线上升时另一条下降，两者朝相反方向移动","example":"In the first chart the line rises; conversely, the second line falls.","exampleCN":"第一张图上那条线上升；反过来，第二张图上的线下降。","why":"Charts are read in pairs, and the word tells the eye to look for the opposite movement.","whyCN":"图表常成对阅读，这个词叫眼睛去找相反的那段走势。"},{"no":"05","title":"The converse in logic","titleCN":"逻辑中的逆命题","definition":"used when a conditional relation is reversed, that is, when the antecedent and the consequent exchange places","definitionCN":"当一个条件关系的两端被对调，即前件与后件互换位置时使用","example":"Every square is a rectangle, but conversely a rectangle need not be a square.","exampleCN":"正方形都是矩形，但反过来，矩形不必是正方形。","why":"Logic gave the word its sharpest use: the converse is a different proposition and may be false.","whyCN":"逻辑学给了这个词最锋利的用法：逆命题是另一个命题，而且可能是假的。"},{"no":"06","title":"Not a denial of the first claim","titleCN":"不否认前一句","definition":"the boundary against a phrase such as on the contrary: the earlier claim is kept, not contradicted","definitionCN":"与「正相反」一类说法的分界：前一说法被保留下来，而不是被驳倒","example":"Conversely does not deny the first claim; on the contrary does.","exampleCN":"这个词并不否认前一句；「正相反」才是否认。","why":"The two words look alike in translation but do opposite work: one balances, the other rebuts.","whyCN":"这两个说法在译文中看着像，做的工作却相反：一个求平衡，一个作反驳。"},{"no":"07","title":"Not a loose contrast","titleCN":"并非宽泛对比","definition":"the boundary against in contrast: a mere difference can be contrasted, but only a reversible relation can be called conversely","definitionCN":"与「相比之下」的分界：单纯的差别可以对比，但只有可以翻转的关系才用这个词","example":"In contrast is the looser choice; conversely needs a relation that can be reversed.","exampleCN":"「相比之下」是更宽松的选择；这个词要求一种能够翻转的关系。","why":"Reversibility is the test: if the two halves cannot swap, the word is the wrong tool.","whyCN":"能否翻转就是检验：两半换不过来，就用错了词。"},{"no":"08","title":"Balancing a point in speech","titleCN":"口语中补上另一面","definition":"in speech and journalism, adds the other side of a case so that the account sounds even-handed","definitionCN":"在口语与新闻中补出事情的另外一面，让叙述显得持平","example":"The drug is cheap and, conversely, the costly version works no better.","exampleCN":"这种药便宜，而反过来，贵的那种也并不更管用。","why":"Spoken argument often needs a counterweight more than a proof, and the word supplies one.","whyCN":"口语论证常常需要一个平衡砝码，而不是一个证明，这个词正好补上。"}],"etymology":{"intro":{"en":"Conversely is converse plus -ly. Converse comes from Latin conversus, the past participle of convertere, to turn round, built on com- together and vertere to turn. The word turns a relation, it does not deny one.","cn":"这个词由形容词加副词词尾构成；形容词来自拉丁语 conversus，即 convertere「翻转」的过去分词，由 com-「共同」与 vertere「转」构成。它把一种关系转过来，而不是把一种说法否掉。"},"items":[{"era":"LATIN VERTERE","en":"Vertere meant to turn, and it also stands behind the English words for a turning point and for a line turned towards its opponent.","cn":"这个词意为「转」，英语里表示转折点、以及转向对方的那些词都由它而来。"},{"era":"LATIN CONVERTERE","en":"Com- plus vertere meant to turn something round or turn it wholly, and so to reverse or transform it.","cn":"com- 加 vertere 意为把某物转过来或整个转掉，因而指翻转、转变。"},{"era":"LATIN CONVERSUS","en":"The past participle described what has been turned, and the noun conversio named the turning.","cn":"过去分词描述「已被转过来的」，名词 conversio 则指那次转动。"},{"era":"ENGLISH CONVERSE","en":"English took converse for the reversed relation; the unrelated verb meaning to talk comes from a different Latin word.","cn":"英语借来这个词表示「相反的关系」；另一个表示「交谈」的动词来自不同的拉丁词。"},{"era":"CONVERSE + -LY","en":"The adverb marked the reversed half of a relation; the exact date of its first use is uncertain.","cn":"副词用来标出关系中翻转的那一半；其首次使用的确切年代不确定。"},{"era":"MODERN ACADEMIC AND TECHNICAL USE","en":"Logic, statistics and charts gave the adverb its sharp sense of a reversible relation.","cn":"逻辑学、统计学与图表赋予它「关系可翻转」的锋利含义。"}]},"similar":{"note":{"en":"The first group shares the turning stem, with one word from an unrelated family; the second holds the contrast words it is often confused with.","cn":"第一组共享「转」这一词干，另有一个来自无关词族的词；第二组是常与它混淆的对照类说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"converse","ipa":"/ˈkɒnvɜːs/","tag":"same root","definition":"The reversed relation itself, or the opposite of a statement.","definitionCN":"指被翻转的那种关系本身，或一个说法的反面。"},{"word":"conversion","ipa":"/kənˈvɜːʃn/","tag":"same root","definition":"The act of changing something from one form or use into another.","definitionCN":"指把某物从一种形式或用途转变为另一种。"},{"word":"convert","ipa":"/kənˈvɜːt/","tag":"same root","definition":"To change form, function or belief.","definitionCN":"指改变形式、功能或信仰。"},{"word":"convertible","ipa":"/kənˈvɜːtəbl/","tag":"same root","definition":"Able to be changed into another form, or a car with a folding roof.","definitionCN":"指可被转换成另一形式的，也指敞篷车。"},{"word":"conversation","ipa":"/ˌkɒnvəˈseɪʃn/","tag":"different root","definition":"From Latin conversari, to live or talk with, not from vertere; it means talk, and has nothing to do with reversal.","definitionCN":"来自拉丁语「相处、交谈」而非「转」；意为交谈，与反向无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"on the contrary","ipa":"/ɒn ðə ˈkɒntrəri/","tag":"near meaning","definition":"Denies or rebuts the statement just made.","definitionCN":"否定或驳斥刚说出的那句话。"},{"word":"in contrast","ipa":"/ɪn ˈkɒntrɑːst/","tag":"near meaning","definition":"Marks a difference between two things, without any requirement that they can be swapped.","definitionCN":"标出两物的差别，并不要求它们可以互换位置。"},{"word":"vice versa","ipa":"/ˌvaɪs ˈvɜːsə/","tag":"near meaning","definition":"The two sides simply exchange roles, usually in a single relation.","definitionCN":"两边直接交换角色，通常用于单一关系。"},{"word":"inversely","ipa":"/ɪnˈvɜːsli/","tag":"near meaning","definition":"In a mathematical or physical relation, one quantity falls as the other rises.","definitionCN":"在数学或物理关系中，一量上升另一量下降。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of turning, the real conversion family, and the reversibility test.","cn":"正常联想使用拉丁语「转」的动词、真实的转化词族，以及那条「能否翻转」的检验。"},"normal":[{"en":"Vertere is to turn, and the word turns a relation round to its other side.","cn":"词根意为「转」，这个词把一种关系转到它的另一面。"},{"en":"Converse, conversion and convert share the turning: a thing turned, a turning, and to turn.","cn":"「相反的」「转变」「转换」都带着这个「转」：转过来的、一次转、去转。"},{"en":"It needs a relation that can be reversed; a mere difference is not enough.","cn":"它需要一个可以翻转的关系；仅仅有差别还不够。"},{"en":"On the contrary denies; conversely balances. One pushes back, the other turns round.","cn":"「正相反」是在否认；这个词是在平衡。一个推开，一个翻转。"},{"en":"Vice versa is its plain twin: the two sides simply change places.","cn":"「反之亦然」是它最朴素的同伴：两边只是换个位置。"}],"abstract":[{"en":"A mirror does not argue with the face; it only shows the other side.","cn":"镜子不与脸争辩，它只呈现另一面。"},{"en":"The word keeps both claims standing and merely swaps their seats.","cn":"这个词让两个说法都站着，只把它们的座位对调。"},{"en":"A relation that cannot be turned round has no use for it.","cn":"无法翻转的关系，用不上这个词。"}]},"examples":[{"en":"Warm air can hold more moisture; conversely, cold air holds less.","cn":"暖空气能容纳更多水汽；反过来，冷空气容纳得更少。"},{"en":"Conversely, a well-timed pause can strengthen a weak argument.","cn":"反过来，一次恰到好处的停顿也能加强一个薄弱的论证。"},{"en":"The two conditions are mirror images; conversely, each can be read from the other.","cn":"这两个条件是镜像关系；反过来，由其中一个可以读出另一个。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康佛斯利」——把两边翻过来看，数字没变，箭头掉头：反之","word":"conversely"},"root":"拉丁语 vertere「转」→ convertere「翻转」（com-「共同」＋vertere）→ conversus「转过来的」→ 英语 converse「相反的」→ 加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Eight senses differ by where the reversed half is placed and what kind of relation is reversed: the core reversal, the sentence opener, the parenthesis, the opposite movement of two curves, the logical converse, the boundary against a denial, the boundary against a loose contrast, and the spoken counterweight.","cn":"八个义项按「翻转的那一半放在哪里」与「翻转的是什么关系」分开：核心反向对照、句首衔接、句中插入、两条曲线的反向走势、逻辑逆命题、与否认类说法的边界、与宽泛对比的边界、口语中的平衡补充。"},"semanticMap":{"core":{"en":"CORE IMAGE: the two columns of a comparison table are swapped, and the arrow reverses while the figures stay put.","cn":"核心意象：对照表的左右两栏被对调，箭头掉头，而数字原封不动。"},"chain":["ONE SIDE","THE OTHER SIDE","TURNED ABOUT","BOTH STILL TRUE","MIRROR IN WRITING","REVERSED RELATION"],"branches":[{"senses":"01 · 08","en":"THE REVERSAL AND THE SPOKEN BALANCE: the relation turned round, here mirrored, there spoken as a counterweight.","cn":"翻转与口语平衡：关系被转过来，在这里是镜像，在那里是口语中的砝码。"},{"senses":"02 · 03","en":"THE MIRROR IN WRITING: at the head of a sentence, or slipped inside it.","cn":"书面中的镜像：或置于句首，或嵌进句中。"},{"senses":"04","en":"THE OPPOSITE MOVEMENT: one curve rises while the other falls.","cn":"相反走势：一条曲线上升，另一条下降。"},{"senses":"05","en":"THE LOGICAL CONVERSE: antecedent and consequent change places.","cn":"逻辑逆命题：前件与后件互换位置。"},{"senses":"06 · 07","en":"THE TWO BOUNDARIES: it neither denies the first claim nor merely contrasts two things.","cn":"两条边界：它既不否认前一句，也不只是把两物作宽泛对比。"}]},"affixes":{"intro":{"en":"Conversely is a Latin participle of turning, wearing an English adverb ending; the family around it is wide and still transparent.","cn":"这个词是拉丁语中表示「转」的分词，套着英语副词词尾；它周围的词族既宽又仍然看得清。"},"latinIntro":{"en":"Latin supplies vertere, convertere and conversus; English supplies converse, conversion and the endings.","cn":"拉丁语提供了 vertere、convertere 与 conversus；英语提供了 converse、conversion 与词尾。"},"items":[{"word":"vertere","structure":"Latin verb","meaning":"to turn, turn round","meaningCN":"转；翻转","example":"The verb supplies the physical picture of turning.","exampleCN":"这个动词提供「转」的身体画面。"},{"word":"con-","structure":"Latin prefix","meaning":"together, wholly","meaningCN":"共同；完全","example":"It intensifies the turning into a full reversal.","exampleCN":"它把「转」加强成彻底的翻转。"},{"word":"convertere","structure":"Latin verb","meaning":"to turn round, reverse","meaningCN":"翻转；使反向","example":"The compound names turning something to face the other way.","exampleCN":"这个复合词指把某物转到朝向另一边。"},{"word":"conversus","structure":"Latin participle","meaning":"turned, reversed","meaningCN":"转过来的；反向的","example":"The participle becomes the English adjective.","exampleCN":"这个分词成为英语形容词。"},{"word":"conversio","structure":"Latin noun","meaning":"a turning round, a change","meaningCN":"转向；转变","example":"The noun names the act of turning.","exampleCN":"这个名词指转动的动作。"},{"word":"converse","structure":"English adjective and noun","meaning":"reversed in order or relation","meaningCN":"次序或关系相反的","example":"The English word keeps the reversed sense.","exampleCN":"英语这个词保留了「反向」的意思。"},{"word":"-ion","structure":"Latin noun ending","meaning":"result of an action","meaningCN":"动作的结果","example":"It forms conversion, the result of turning.","exampleCN":"它构成表示转变结果的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the adverb that marks the mirrored half.","exampleCN":"它构成标出镜像那一半的副词。"}],"latinEntries":[{"word":"vertere","structure":"Latin verb","meaning":"to turn","meaningCN":"转"},{"word":"convertere","structure":"Latin verb","meaning":"to turn round, reverse","meaningCN":"翻转；使反向"},{"word":"conversus","structure":"Latin participle","meaning":"turned, reversed","meaningCN":"转过来的"},{"word":"conversio","structure":"Latin noun","meaning":"a turning round","meaningCN":"转向；转变"},{"word":"con-","structure":"Latin prefix","meaning":"together, wholly","meaningCN":"共同；完全"}],"derivatives":[{"word":"converse","pos":"adj.","zh":"由拉丁语过去分词直接构成形容词，义为「相反的」"},{"word":"conversion","pos":"n.","zh":"由翻转动词加表示动作结果的名词尾构成，义为「转变」"},{"word":"convert","pos":"v.","zh":"由同一词干经法语构成动词，义为「转变」"},{"word":"convertible","pos":"adj.","zh":"由转变动词加「可……的」形容词词尾构成，义为「可转换的」"}]}},{"word":"correspondingly","ipa_uk":"/ˌkɒrəˈspɒndɪŋli/","ipa_us":"/ˌkɔːrəˈspɑːndɪŋli/","definition_zh":"相应地；对应地；同步地；按相称的幅度","definition_en":"in a way that matches another change or item, so that the two move or stand together, without saying that one causes the other","core_image":"双栏账本左右两栏始终齐平，左边添一行，右边也跟着添一行","scene":"双栏账本左边记支出，右边记余额，左边添一行，右边跟着添一行。Output rose by a tenth and, correspondingly, employment rose by the same amount.","sceneCN":"这里指两处变化同步同幅（第 1 个义项：同步变化）；句意为产量增加了一成，就业也相应地增加了同样的幅度。场景要点：双栏账本、始终齐平的行数、同步添上的记录。","pos":[{"tag":"adv.","zh":"相应地；对应地；同步地"}],"collocations":[{"phrase":"and correspondingly","zh":"并相应地"},{"phrase":"correspondingly, the","zh":"相应地，……"},{"phrase":"increase correspondingly","zh":"相应增加"},{"phrase":"correspondingly lower","zh":"相应更低"},{"phrase":"correspondingly higher","zh":"相应更高"},{"phrase":"vary correspondingly","zh":"相应变化"}],"forms":[{"label":"无词形变化（副词）","form":"correspondingly"}],"derivatives":[{"word":"correspond","pos":"v.","zh":"由拉丁语「共同回应」的动词构成，义为「相符、通信」"},{"word":"correspondence","pos":"n.","zh":"由对应动词加表示状态的名词尾构成，义为「相符、通信」"},{"word":"correspondent","pos":"n.","zh":"由对应动词的现在分词加表示人或物的名词尾构成，义为「通信记者、对应物」"},{"word":"corresponding","pos":"adj.","zh":"由对应动词的现在分词加形容词词尾构成，义为「相应的」"}],"senses":[{"no":"01","title":"A change matched by another change","titleCN":"同步变化","definition":"marks a second change that keeps pace with the one just described, in direction and in rough amount","definitionCN":"标出与前述变化同向、同幅的第二处变化","example":"Demand for cooling rose in July; energy use rose correspondingly.","exampleCN":"七月制冷需求上升，能源消耗也相应上升。","why":"Respondere is to answer back, and two things that correspond answer each other, one movement meeting another.","whyCN":"这个词的拉丁语动词意为「回应」，彼此对应的东西在互相回应，一处变动迎上另一处变动。"},{"no":"02","title":"A match in amount","titleCN":"按相称的幅度","definition":"used where the second quantity is not merely parallel but proportioned to the first, larger with larger and smaller with smaller","definitionCN":"第二项不只是并行，而是与第一项相称，前者大后者也大，前者小后者也小","example":"Costs were cut by a fifth, and the staff was reduced correspondingly.","exampleCN":"成本削减了五分之一，人员也相应裁减。","why":"Proportion is the strictest form of correspondence, and the word can carry it without naming a ratio.","whyCN":"比例是对应关系里最严格的一种，这个词不必点明比率也能带上它。"},{"no":"03","title":"Sentence-initial in formal writing","titleCN":"句首衔接","definition":"placed first in a report or paper to announce that the matching change follows","definitionCN":"置于报告或论文的句首，宣告与之相称的另一处变化随后出现","example":"Correspondingly, the second group showed a smaller rise.","exampleCN":"相应地，第二组显示出较小的升幅。","why":"Written comparison needs a visible joint, and the opener supplies it.","whyCN":"书面比较需要看得见的接缝，句首位置正好提供。"},{"no":"04","title":"The parenthesis inside the clause","titleCN":"句中插入","definition":"set between commas so that the matching item is slipped in without stopping the sentence","definitionCN":"用逗号夹在句中，把对应项轻轻塞入而不打断句子","example":"The northern route, correspondingly, takes two days longer.","exampleCN":"相应地，北线要多走两天。","why":"Inside the clause the word works as a quiet aside rather than a signpost.","whyCN":"放在小句内部，这个词是安静的旁注，而不是路标。"},{"no":"05","title":"The manner of adjusting","titleCN":"句末修饰调整","definition":"in final position with verbs of change, it says that the action was carried out to the matching degree","definitionCN":"处于句末并与变化类动词连用，说明动作是按相称的幅度实施的","example":"When the tariff changed, the prices at the pump moved correspondingly.","exampleCN":"关税变动之后，加油站的油价也相应变动。","why":"Final position puts the word inside the predicate, so it describes how the change was made.","whyCN":"句末位置把这个词放进谓语，于是它描述变动是如何进行的。"},{"no":"06","title":"A structural counterpart","titleCN":"结构上的对应项","definition":"used of items that answer one another across two lists or systems, where the matching is one of position rather than of amount","definitionCN":"用于两份清单或两套体系之间彼此对应的项目，对应的是位置而不是数量","example":"Each province has a correspondingly named office in the capital.","exampleCN":"每个省在首都都有一个名称相应的办事处。","why":"Correspondence is not only of size; two systems can mirror each other in structure.","whyCN":"对应不只发生在大小上；两套体系可以在结构上互为镜像。"},{"no":"07","title":"Not a claim of cause","titleCN":"不含因果断言","definition":"the boundary against the result words: correspondingly says the two moved together, not that one made the other move","definitionCN":"与结果类词的分界：这个词说两者一起动，而不是一个使另一个动","example":"Correspondingly says the two moved together; consequently says one caused the other.","exampleCN":"这个词说两者一同变动；表示客观结果的词才说一个造成了另一个。","why":"Matching is a relation of shape, and shape can be read without any causal arrow.","whyCN":"相称是一种形状上的关系，读这种关系不必加上因果箭头。"},{"no":"08","title":"Not the same as respectively","titleCN":"与「分别地」的分界","definition":"the boundary against respectively: that word pairs the items of two lists in order, while this word pairs changes in size","definitionCN":"与「分别地」的分界：那个词按顺序把两份清单逐项配对，这个词把两处变化的幅度配对","example":"Respectively pairs items in order; correspondingly pairs changes in size.","exampleCN":"「分别地」按顺序配项目，这个词按大小配变化。","why":"Order and degree are different kinds of pairing, and English keeps separate words for them.","whyCN":"顺序与幅度是两种不同的配对，英语为它们分别留了词。"}],"etymology":{"intro":{"en":"Correspondingly is corresponding plus -ly. Correspond comes from Medieval Latin correspondere, to answer together, built on com- together and respondere, to answer, itself re- back and spondere to promise. Two things correspond when each answers the other.","cn":"这个词由形容词加副词词尾构成。动词来自中世纪拉丁语 correspondere「一同回应」，由 com-「共同」与 respondere「回答」构成，而 respondere 又是 re-「回」加 spondere「许诺」。两物相符，就是各自回应对方。"},"items":[{"era":"LATIN SPONDERE","en":"Spondere meant to promise or pledge, and it stands behind the English word for a spouse, a promised person.","cn":"这个词意为许诺、保证，英语里表示配偶的词也由它而来，原指「被许诺的人」。"},{"era":"LATIN RESPONDERE","en":"Re- plus spondere made a verb of answering in return, as a promise answers a promise.","cn":"re- 加 spondere 构成动词，意为回过来作答，像许诺回应许诺。"},{"era":"MEDIEVAL LATIN CORRESPONDERE","en":"Com- plus respondere meant to answer together, and so to be in harmony or agreement.","cn":"com- 加 respondere 意为一同回应，因而指彼此和谐、相符。"},{"era":"ENGLISH CORRESPOND","en":"English took the verb for things that answer one another, and also for the exchange of letters.","cn":"英语借来这个动词，既指彼此回应的东西，也指书信往来。"},{"era":"CORRESPONDING + -LY","en":"The adverb marks a matching change or item; the exact date of its first use is uncertain.","cn":"副词用来标出相称的变化或项目；其首次使用的确切年代不确定。"},{"era":"MODERN STATISTICAL USE","en":"Tables and technical reports made it a standard word for two quantities that move in step.","cn":"表格与技术报告使它成为描述两个量同步变动的标准用词。"}]},"similar":{"note":{"en":"The first group shares the answering stem, with one word from an unrelated family; the second holds the words it is most often mixed up with.","cn":"第一组共享「回应」这一词干，另有一个来自无关词族的词；第二组是常与它弄混的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"correspond","ipa":"/ˌkɒrəˈspɒnd/","tag":"same root","definition":"To match another thing, or to exchange letters with someone.","definitionCN":"指与另一物相符，也指与某人通信。"},{"word":"correspondence","ipa":"/ˌkɒrəˈspɒndəns/","tag":"same root","definition":"A match between two sets, or the letters exchanged.","definitionCN":"指两组之间的相符，也指往来的书信。"},{"word":"correspondent","ipa":"/ˌkɒrəˈspɒndənt/","tag":"same root","definition":"A reporter based in a place, or a thing that matches another.","definitionCN":"指驻某地的记者，也指与另一物相对应者。"},{"word":"corresponding","ipa":"/ˌkɒrəˈspɒndɪŋ/","tag":"same root","definition":"Matching or analogous to something else.","definitionCN":"指与另一物相应的、类似的。"},{"word":"corroborate","ipa":"/kəˈrɒbəreɪt/","tag":"different root","definition":"From Latin roborare, to make strong like oak, not from respondere; it means to confirm a claim with evidence.","definitionCN":"来自拉丁语「使如橡木般坚固」，不是「回应」；意为用证据证实某一说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accordingly","ipa":"/əˈkɔːdɪŋli/","tag":"near meaning","definition":"Marks an action adjusted to the facts just given.","definitionCN":"标记依前述事实作出的调整。"},{"word":"respectively","ipa":"/rɪˈspektɪvli/","tag":"near meaning","definition":"Pairs the items of two lists one to one, in the order given.","definitionCN":"把两份清单的项目按所给顺序逐一配对。"},{"word":"proportionally","ipa":"/prəˈpɔːʃənəli/","tag":"near meaning","definition":"In a way that keeps a stated ratio between the parts.","definitionCN":"以各部分之间保持明确比率的方式。"},{"word":"likewise","ipa":"/ˈlaɪkwaɪz/","tag":"near meaning","definition":"In the same way, often of a similar action rather than a matched quantity.","definitionCN":"以同样的方式，常用于类似的动作而非相称的数量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of answering back, the real correspondence family, and the two-column ledger.","cn":"正常联想使用拉丁语「回话」的动词、真实的对应该词族，以及那本双栏账本。"},"normal":[{"en":"Respondere is to answer back, and things that correspond answer each other.","cn":"词根意为「回应」，彼此对应的东西就是在互相回应。"},{"en":"Two columns, one movement: the word keeps them level without saying which pushed which.","cn":"两栏、一次变动：这个词让两边保持齐平，却不说谁推动了谁。"},{"en":"It loves verbs of change: rise, fall, increase, adjust, vary.","cn":"它偏爱变化类动词：升、降、增、调、变。"},{"en":"Respectively lists in order; correspondingly moves in step. One is a roll call, the other a dance.","cn":"「分别地」按顺序点名；这个词同步移动。一个是点名，一个是同行。"},{"en":"The word adds no cause; it only reports a matching size.","cn":"这个词不加因果，只报告一个相称的幅度。"}],"abstract":[{"en":"Two things can keep step without one leading the other.","cn":"两样东西可以同步而行，而不必谁领着谁。"},{"en":"A pair is a promise that neither side will move alone.","cn":"成对，就是一种谁也不单独移动的约定。"},{"en":"Matching is a relation of size, and size can be measured but not blamed.","cn":"相称是一种大小上的关系，大小可以测量，却无从责怪。"}]},"examples":[{"en":"The temperature fell, and the pressure in the tank fell correspondingly.","cn":"温度下降，罐内压力也相应下降。"},{"en":"Correspondingly, the later chapters give less space to the early period.","cn":"相应地，后面几章给早期阶段的篇幅更少。"},{"en":"As the sample grew, the margin of error shrank correspondingly.","cn":"随着样本增大，误差范围也相应缩小。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「考瑞斯旁丁利」——两栏账本一起长，左添一行右也添一行：相应地","word":"correspondingly"},"root":"拉丁语 spondere「许诺」→ respondere「回应」（re-「回」＋spondere）→ 中世纪拉丁语 correspondere「一同回应」→ 英语 correspond → corresponding，再加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Eight senses vary what is paired and where the word stands: a matching change, a proportioned amount, the written opener, the parenthesis, the manner at the end, a structural counterpart, the boundary against causal words, and the boundary against the listing word.","cn":"八个义项改变的是「配什么」与「站在哪里」：同步变化、相称幅度、书面句首、句中插入、句末方式、结构对应项、与因果词的分界、与列举词的分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: two columns of a ledger stay level, and a line added on the left brings a line on the right.","cn":"核心意象：账本的两栏始终齐平，左边添一行，右边就跟着添一行。"},"chain":["ONE CHANGE","AN ANSWER","IN STEP","MATCHED AMOUNT","STRUCTURAL PAIR","NO CAUSE CLAIMED"],"branches":[{"senses":"01 · 02","en":"THE MATCHED CHANGE: the two move together, and the size of one sets the size of the other.","cn":"相称的变化：两者同步而动，一处的幅度决定另一处的幅度。"},{"senses":"03 · 04","en":"THE WRITTEN JOINT: at the head of the sentence, or slipped inside it.","cn":"书面接缝：或置于句首，或嵌进句中。"},{"senses":"05","en":"THE MANNER AT THE END: the action is carried out to the matching degree.","cn":"句末的方式：动作按相称的幅度实施。"},{"senses":"06","en":"THE STRUCTURAL COUNTERPART: one list answers another in position.","cn":"结构对应项：一份清单在位置上回应另一份。"},{"senses":"07 · 08","en":"THE TWO BOUNDARIES: no causal arrow, and no simple roll call of items.","cn":"两条边界：不加因果箭头，也不是逐项点名。"}]},"affixes":{"intro":{"en":"Correspondingly is a Latin verb of answering back with a particle in front, an adjective ending and an English adverb ending.","cn":"这个词是一个表示「回应」的拉丁动词，前面带小品词，后面套形容词词尾与英语副词词尾。"},"latinIntro":{"en":"Latin supplies spondere and respondere; Medieval Latin supplies correspondere, and English supplies correspond, corresponding and the endings.","cn":"拉丁语提供了 spondere 与 respondere；中世纪拉丁语提供了 correspondere，英语提供了 correspond、corresponding 与词尾。"},"items":[{"word":"spondere","structure":"Latin verb","meaning":"to promise, pledge","meaningCN":"许诺；保证","example":"The verb is the promise inside the answer.","exampleCN":"这个动词是「回应」里那一半许诺。"},{"word":"re-","structure":"Latin prefix","meaning":"back, again","meaningCN":"回；再","example":"It turns the promise into an answer given back.","exampleCN":"它把许诺变成回过来的作答。"},{"word":"respondere","structure":"Latin verb","meaning":"to answer in return, correspond","meaningCN":"回应；相应","example":"The verb names an answer given to an answer.","exampleCN":"这个动词指对回答作出的回答。"},{"word":"correspondere","structure":"Medieval Latin verb","meaning":"to answer together, agree","meaningCN":"共同回应；相符","example":"The compound names two things answering each other.","exampleCN":"这个复合词指两物彼此回应。"},{"word":"correspond","structure":"English verb","meaning":"to match, to exchange letters","meaningCN":"相符；通信","example":"English adds the letter-writing sense.","exampleCN":"英语加上「书信往来」这一义。"},{"word":"corresponding","structure":"English adjective","meaning":"matching, analogous","meaningCN":"相应的；类似的","example":"The participle becomes an adjective of matching.","exampleCN":"这个分词成为表示「相称」的形容词。"},{"word":"-ent","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于……状态的","example":"It forms the adjective and the noun of the matching thing.","exampleCN":"它构成表示对应之物的形容词与名词。"},{"word":"-ence","structure":"Latin noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of correspondence.","exampleCN":"它构成表示「相符」的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the adverb of matching change.","exampleCN":"它构成表示「相称变化」的副词。"}],"latinEntries":[{"word":"spondere","structure":"Latin verb","meaning":"to promise, pledge","meaningCN":"许诺；保证"},{"word":"respondere","structure":"Latin verb","meaning":"to answer in return","meaningCN":"回应"},{"word":"correspondere","structure":"Medieval Latin verb","meaning":"to answer together, agree","meaningCN":"共同回应；相符"},{"word":"re-","structure":"Latin prefix","meaning":"back, again","meaningCN":"回；再"}],"derivatives":[{"word":"correspond","pos":"v.","zh":"由中世纪拉丁语「共同回应」的动词构成，义为「相符、通信」"},{"word":"correspondence","pos":"n.","zh":"由对应动词加表示状态的名词尾构成，义为「相符、通信」"},{"word":"correspondent","pos":"n.","zh":"由对应动词的现在分词加表示人或物的名词尾构成，义为「通信记者」"},{"word":"corresponding","pos":"adj.","zh":"由对应动词的现在分词加形容词词尾构成，义为「相应的」"}]}},{"word":"crucially","ipa_uk":"/ˈkruːʃəli/","ipa_us":"/ˈkruːʃəli/","definition_zh":"关键地；至关重要地；关键在于；决定性的是","definition_en":"used to mark the one point on which the outcome depends, stronger and more specific than merely important","core_image":"十字路口只有一条路通向终点，路牌被红笔圈住，其余路口都暗下去","scene":"实验报告里有一处条件被红笔圈住，其余条件都划了淡线。Crucially, the two groups were matched for age before the trial began.","sceneCN":"这里指点出决定成败的那一项条件（第 1 个义项：决定成败的关键点）；句意为关键在于，试验开始之前两组人的年龄已作过配对。场景要点：被红笔圈住的条件、暗下去的其余条件、只剩一条通向终点的路口。","pos":[{"tag":"adv.","zh":"关键地；至关重要地；关键在于"}],"collocations":[{"phrase":"crucially, the study","zh":"关键在于，这项研究……"},{"phrase":"and crucially","zh":"而且关键在于"},{"phrase":"crucially important","zh":"至关重要的"},{"phrase":"crucially, however","zh":"然而关键在于"},{"phrase":"crucially, this means","zh":"关键在于，这意味着……"},{"phrase":"crucially, the difference","zh":"关键在于这一差别"}],"forms":[{"label":"无词形变化（副词）","form":"crucially"}],"derivatives":[{"word":"crucial","pos":"adj.","zh":"由拉丁语「十字」加形容词词尾构成，义为「关键的、决定性的」"},{"word":"crux","pos":"n.","zh":"由同一拉丁名词直接借入，义为「症结、关键点」"},{"word":"cruciform","pos":"adj.","zh":"由十字名词加表示形状的词根构成，义为「十字形的」"},{"word":"excruciate","pos":"v.","zh":"由表示「钉上十字架、折磨」的拉丁动词构成，义为「使极度痛苦」"},{"word":"excruciating","pos":"adj.","zh":"由折磨动词的现在分词加形容词词尾构成，义为「极痛苦的」"}],"senses":[{"no":"01","title":"The point on which the result turns","titleCN":"决定成败的关键点","definition":"marks the condition or fact that decides how the whole comes out, raising it above the other points in the sentence","definitionCN":"标出决定全局成败的条件或事实，把它抬到句中其他要点之上","example":"Crucially, the two groups were matched for age before the trial began.","exampleCN":"关键在于，试验开始之前两组人的年龄已作过配对。","why":"Crux is a cross, and at a cross-roads the choice of one path decides the journey.","whyCN":"十字路口的意思就是：站在岔口上，选哪条路决定整段行程。"},{"no":"02","title":"The formal sentence opener","titleCN":"句首正式突出","definition":"placed first in academic or report prose to single out one point before the rest is read","definitionCN":"置于学术或报告文字的开头，在读者读到其余内容之前先单挑出一点","example":"Crucially, the sample included no first-year students.","exampleCN":"关键在于，样本里没有一年级学生。","why":"A paper has many claims, and the opener tells the reader which one carries the argument.","whyCN":"一篇论文有很多说法，句首位置告诉读者哪一条承重。"},{"no":"03","title":"The parenthesis inside the clause","titleCN":"句中插入","definition":"set between commas so that the decisive point is added without a change of sentence","definitionCN":"用逗号夹在句中，把决定性的一点补进来而不另起一句","example":"The second condition, crucially, was never tested.","exampleCN":"关键在于，第二个条件从未被检验。","why":"Insertion lets the writer mark the load-bearing point in a quieter voice.","whyCN":"插入让作者用更轻的声音标出那处承重的地方。"},{"no":"04","title":"The weight placed at the end","titleCN":"句末强调","definition":"in final position, where the decisive element is the last thing the reader is left with","definitionCN":"处于句末，把决定性的成分留作读者最后握在手里的东西","example":"The choice of solvent mattered crucially.","exampleCN":"溶剂的选择在要害上起了作用。","why":"What comes last in a sentence stays longest, so the end is where a decisive point can be planted.","whyCN":"句子最后的东西留得最久，所以句末适合安放要害。"},{"no":"05","title":"A load-bearing premise","titleCN":"论证中的关键前提","definition":"in reasoning, marks the premise or assumption that the whole argument stands on","definitionCN":"在推理中标出整个论证所站立其上的前提或假设","example":"Crucially, the argument assumes that the two variables are independent.","exampleCN":"关键在于，这个论证假定两个变量彼此独立。","why":"An argument falls if its load-bearing premise falls, and the word points to that premise.","whyCN":"论证会随承重前提一起倒掉，这个词就指在那里。"},{"no":"06","title":"Harder than merely important","titleCN":"比「重要的是」更硬","definition":"the boundary against importantly: that word gives weight, while this one says the outcome depends on the point","definitionCN":"与「重要的是」的分界：那个词给出分量，这个词则说结果就系于这一点","example":"Importantly signals weight; crucially signals that the outcome depends on it.","exampleCN":"「重要的是」给的是分量；这个词给的是「成败系于此」。","why":"Weight and dependence are different claims, and a writer who means the second needs the stronger word.","whyCN":"有分量与成败所系是两种说法，想说后者的作者需要更硬的词。"},{"no":"07","title":"Not a statistical difference","titleCN":"与「显著地」的分界","definition":"the boundary against significantly: that word reports a measured difference, while this one reports a difference that decides the result","definitionCN":"与「显著地」的分界：那个词报告测得的差别，这个词报告决定结果的差别","example":"Significantly reports a statistical difference; crucially reports a difference that decides the result.","exampleCN":"「显著地」报告统计上的差别；这个词报告决定结果的差别。","why":"A measured difference need not be a decisive one: a result can be significant and still change nothing.","whyCN":"测得的差别未必是决定性的差别：结果可以显著，却什么也没有改变。"},{"no":"08","title":"Emphasis in speech","titleCN":"口语中的强调","definition":"in speech, often after and, a pointed reminder that the next detail is the one that matters","definitionCN":"在口语中常跟在「而且」之后，提醒听者下面的细节才是最要紧的","example":"The door was locked and, crucially, nobody had a key.","exampleCN":"门锁着，而且关键在于，谁也没有钥匙。","why":"Speech has no italics, so a word like this does the work of underlining.","whyCN":"口语没有斜体，这样的词就干了划重点的活。"}],"etymology":{"intro":{"en":"Crucially is crucial plus -ly. Crucial was formed in English on Latin crux, crucis, a cross, and first described what belonged to a cross. The modern sense of decisive comes from the experimentum crucis, the cross-roads experiment that decides which of two paths is right.","cn":"这个词由形容词加副词词尾构成。形容词是英语在拉丁语 crux、crucis「十字」上造出来的，最初指「与十字有关的」。今天「决定性」的意思来自 experimentum crucis，即那个决定两条路哪条正确的「十字路口实验」。"},"items":[{"era":"LATIN CRUX","en":"Crux meant a cross, and also a hard knot or turning point that has to be decided.","cn":"这个词指十字架，也指必须作出决断的症结或转折点。"},{"era":"LATIN CRUCIARE","en":"The verb meant to put someone on a cross, and so to torment; cruciatus named the torment.","cn":"这个动词意为把人钉上十字架，因而指折磨；名词 cruciatus 指那种痛苦。"},{"era":"ENGLISH CRUCIAL","en":"English formed the adjective with -al, at first in the literal sense of a cross; the date of that first use is uncertain.","cn":"英语加形容词词尾构成这个词，最初是「十字的」字面义；该首见年代不确定。"},{"era":"EXPERIMENTUM CRUCIS","en":"Bacon described a decisive test as a cross-roads experiment, instantia crucis; later writers called it experimentum crucis, the experiment that decides.","cn":"培根把决定性的检验称作「十字路口实验」，即 instantia crucis；后来的作者称之为 experimentum crucis，即「判决性实验」。"},{"era":"THE DECISIVE SENSE","en":"From that deciding experiment the adjective took its sense of decisive, and the adverb followed.","cn":"形容词从这种决定性的实验取得「决定性」之义，副词随后而来。"},{"era":"MODERN ACADEMIC USE","en":"Papers and reports use the adverb to flag the one point on which their conclusion depends; its first use as such is dated only approximately.","cn":"论文与报告用这个副词标出结论所系的那一点；它作此用法的首见年代只有约略说法。"}]},"similar":{"note":{"en":"The first group shares the cross; the second holds the emphasis words it is weighed against, and one word from an unrelated family.","cn":"第一组共享「十字」这一词根；第二组是拿来与它权衡的强调类词，另有一个来自无关词族的形近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"crucial","ipa":"/ˈkruːʃl/","tag":"same root","definition":"Decisive for an outcome, and in older use, shaped like a cross.","definitionCN":"指对结果有决定作用的，旧义指十字形的。"},{"word":"crux","ipa":"/krʌks/","tag":"same root","definition":"The central difficulty or the point on which everything turns.","definitionCN":"指核心难题，或一切都系于其上的那一点。"},{"word":"cruciform","ipa":"/ˈkruːsɪfɔːm/","tag":"same root","definition":"Shaped like a cross.","definitionCN":"指形状像十字的。"},{"word":"excruciating","ipa":"/ɪkˈskruːʃieɪtɪŋ/","tag":"same root","definition":"Extremely painful, from the torment of the cross.","definitionCN":"指极度痛苦的，源自十字架之刑的折磨。"},{"word":"cruel","ipa":"/ˈkruːəl/","tag":"different root","definition":"From Latin crudus, raw or bloody, not from crux; it means causing suffering, not decisive.","definitionCN":"来自拉丁语「生的、血淋淋的」而非「十字」；意为残忍的，不指决定性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"importantly","ipa":"/ɪmˈpɔːtntli/","tag":"near meaning","definition":"Marks a point as weighty, without claiming that the result depends on it.","definitionCN":"标记一点有分量，但不声称结果系于它。"},{"word":"significantly","ipa":"/sɪɡˈnɪfɪkəntli/","tag":"near meaning","definition":"Reports a large or statistically measured difference.","definitionCN":"报告幅度大或经统计测得的差别。"},{"word":"critically","ipa":"/ˈkrɪtɪkli/","tag":"near meaning","definition":"Can mean decisively, but also means in a judging or fault-finding way.","definitionCN":"既可指决定性地，也指以评判或挑错的方式。"},{"word":"essentially","ipa":"/ɪˈsenʃəli/","tag":"near meaning","definition":"Marks what something is in its nature, not what decides its fate.","definitionCN":"标记某物在本性上是什么，而不是什么决定它的结局。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the cross at the heart of the word, the real deciding experiment, and the load-bearing point in an argument.","cn":"正常联想使用这个词心里的「十字」、真实的判决性实验，以及论证里的承重点。"},"normal":[{"en":"Crux is a cross, and at a cross-roads one path must be chosen.","cn":"词根是「十字」，站在十字路口必须选一条路。"},{"en":"Bacon's cross-roads experiment decided between two explanations, and the word kept that deciding force.","cn":"培根的十字路口实验在两种解释之间作出裁决，这个词保留的就是那股裁决力。"},{"en":"Crucial, crux and crucially share the cross: the knot, the decisive test, and the adverb that flags it.","cn":"「关键的」「症结」「关键地」都带着十字：那个结、那场判决、以及标出它的副词。"},{"en":"Importantly says this matters; crucially says the result depends on it.","cn":"「重要的是」说这要紧；这个词说结果就系于它。"},{"en":"If you could replace it with significantly, you probably want a different word.","cn":"如果你能用「显著地」替换它，那多半该换一个词。"}],"abstract":[{"en":"A cross-roads is not a busy place but a deciding place.","cn":"十字路口不是热闹之处，而是决断之处。"},{"en":"Every argument has one joint that carries the weight, and the word points at it.","cn":"每个论证都有一处承重的接缝，这个词就指在那里。"},{"en":"Calling a detail crucial is a claim about the whole, not about the detail.","cn":"把一个细节说成关键，是在对整体作判断，而不是在说那个细节。"}]},"examples":[{"en":"Crucially, the second experiment used the same temperature as the first.","cn":"关键在于，第二次实验用了与第一次相同的温度。"},{"en":"The repair was cheap and, crucially, it held for a full year.","cn":"这次修理很便宜，而且关键在于，它整整撑了一年。"},{"en":"Crucially, none of the samples had been exposed to light.","cn":"关键在于，没有任何一份样本见过光。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「克鲁舍利」——十字路口只有一条路通向结果：关键地","word":"crucially"},"root":"拉丁语 crux、crucis「十字」→ 英语 crucial「与十字有关的、决定性的」（其「决定性」义出自培根的十字路口实验）→ 加副词词尾构成。直接来源清楚；作「决定性」义的年代为约数。","sensesIntro":{"en":"Eight senses vary the target and the force of the emphasis: the deciding point, the formal opener, the parenthesis, the end position, a load-bearing premise, the boundary against a word of weight, the boundary against a statistical word, and spoken emphasis.","cn":"八个义项改变的是「强调什么」与「强调多硬」：决定点、正式句首、句中插入、句末、承重前提、与「重要的是」的分界、与统计用词的分界、口语强调。"},"semanticMap":{"core":{"en":"CORE IMAGE: at a cross-roads one road leads to the end, and its sign is circled in red while the others dim.","cn":"核心意象：十字路口只有一条路通向终点，它的路牌被红笔圈住，其余路口暗下去。"},"chain":["A CROSS","A CROSS-ROADS","A DECIDING TEST","THE LOAD-BEARING POINT","THE OUTCOME TURNS","EMPHASIS IN PROSE"],"branches":[{"senses":"01 · 08","en":"THE DECIDING POINT AND THE SPOKEN NUDGE: the one condition that matters, underlined in speech.","cn":"决定点与口语提醒：最要紧的那一项条件，在口语里被划了重点。"},{"senses":"02 · 03 · 04","en":"THE THREE POSITIONS: at the head of the sentence, inside it, or at its end.","cn":"三个位置：句首、句中、句末。"},{"senses":"05","en":"THE LOAD-BEARING PREMISE: the assumption the whole argument rests on.","cn":"承重前提：整个论证所依靠的那个假设。"},{"senses":"06","en":"THE HARDER CLAIM: weight is not the same as dependence on the outcome.","cn":"更硬的断言：有分量不等于成败系于此。"},{"senses":"07","en":"THE MEASURED DIFFERENCE: statistical significance is another thing altogether.","cn":"测得的差别：统计上的显著完全是另一回事。"}]},"affixes":{"intro":{"en":"Crucially is an English adjective built on a Latin noun for a cross, with an English adverb ending on top.","cn":"这个词是英语在拉丁语的「十字」名词上造成的形容词，再套一层英语副词词尾。"},"latinIntro":{"en":"Latin supplies crux, cruciare and cruciatus; English supplies crucial, cruciform and the endings.","cn":"拉丁语提供了 crux、cruciare 与 cruciatus；英语提供了 crucial、cruciform 与词尾。"},"items":[{"word":"crux","structure":"Latin noun","meaning":"cross, a turning point","meaningCN":"十字；关键点","example":"The noun supplies both the shape and the idea of a decisive knot.","exampleCN":"这个名词既提供十字的形状，也提供「症结」的意思。"},{"word":"cruciare","structure":"Latin verb","meaning":"to torment on a cross","meaningCN":"钉上十字架；折磨","example":"The verb names the punishment of the cross.","exampleCN":"这个动词指十字架上的刑罚。"},{"word":"cruciatus","structure":"Latin noun","meaning":"torment, torture","meaningCN":"折磨；痛苦","example":"The noun names the suffering the verb causes.","exampleCN":"这个名词指动词所造成的痛苦。"},{"word":"crucial","structure":"English adjective","meaning":"of a cross; decisive","meaningCN":"十字的；决定性的","example":"English formed it with -al, and later gave it the deciding sense.","exampleCN":"英语加词尾造出它，后来才给了它「决定性」一义。"},{"word":"cruciform","structure":"English adjective","meaning":"cross-shaped","meaningCN":"十字形的","example":"The word keeps the literal shape of the cross.","exampleCN":"这个词保留十字的字面形状。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or belonging to","meaningCN":"属于……的","example":"It turns the noun into an adjective.","exampleCN":"它把名词变成形容词。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or do","meaningCN":"使……；做……","example":"It forms the verb of tormenting.","exampleCN":"它构成表示「折磨」的动词。"},{"word":"-ing","structure":"English participle ending","meaning":"forming a present participle","meaningCN":"构成现在分词","example":"It forms the adjective of extreme pain.","exampleCN":"它构成表示极度痛苦的形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the adverb that flags the decisive point.","exampleCN":"它构成标出关键点的副词。"}],"latinEntries":[{"word":"crux","structure":"Latin noun","meaning":"cross, a turning point","meaningCN":"十字；关键点"},{"word":"cruciare","structure":"Latin verb","meaning":"to torment on a cross","meaningCN":"钉上十字架；折磨"},{"word":"cruciatus","structure":"Latin noun","meaning":"torment","meaningCN":"折磨"},{"word":"cruciformis","structure":"Latin adjective","meaning":"cross-shaped","meaningCN":"十字形的"}],"derivatives":[{"word":"crucial","pos":"adj.","zh":"由十字名词加形容词词尾构成，义为「决定性的」"},{"word":"crux","pos":"n.","zh":"由同一拉丁名词直接借入，义为「症结」"},{"word":"cruciform","pos":"adj.","zh":"由十字名词加表示形状的词根构成，义为「十字形的」"},{"word":"excruciate","pos":"v.","zh":"由表示「钉上十字架」的拉丁动词构成，义为「使极度痛苦」"},{"word":"excruciating","pos":"adj.","zh":"由折磨动词的现在分词加形容词词尾构成，义为「极痛苦的」"}]}},{"word":"effectively","ipa_uk":"/ɪˈfektɪvli/","ipa_us":"/ɪˈfektɪvli/","definition_zh":"实际上；事实上；有效地；大体上；几乎","definition_en":"used to say what is true in effect or in practice, or that something produces the result intended, often where the form differs from the reality","core_image":"旧规定还挂在墙上，柜台却已照另一套办法办事，纸上的名目与实际的做法分成两栏","scene":"旧规定仍贴在墙上，柜台却已按新办法办事，来人只看实际怎么做。The old rule is still on the books, but effectively it has not been applied for years.","sceneCN":"这里指名目与实际之间的落差（第 1 个义项：实际上、事实上）；句意为那条旧规定仍留在法规里，但实际上多年没有执行了。场景要点：墙上的旧规定、换了做法的柜台、名目与实际的落差。","pos":[{"tag":"adv.","zh":"实际上；有效地；大体上"}],"collocations":[{"phrase":"effectively means","zh":"实际上意味着"},{"phrase":"effectively the same","zh":"实际上一样"},{"phrase":"effectively banned","zh":"实际上被禁止"},{"phrase":"effectively no","zh":"实际上没有"},{"phrase":"communicate effectively","zh":"有效地沟通"},{"phrase":"work effectively","zh":"有效地工作"}],"forms":[{"label":"无词形变化（副词）","form":"effectively"}],"derivatives":[{"word":"effect","pos":"n.","zh":"由拉丁语「做出之事」的过去分词构成名词，义为「结果、效果」"},{"word":"effective","pos":"adj.","zh":"由效果名词加表示性质的形容词词尾构成，义为「有效的」"},{"word":"effectiveness","pos":"n.","zh":"由有效形容词加表示性质的名词尾构成，义为「有效性」"},{"word":"ineffective","pos":"adj.","zh":"由有效形容词加否定前缀构成，义为「无效的」"},{"word":"effectual","pos":"adj.","zh":"由效果名词加形容词词尾构成，义为「奏效的」"}],"senses":[{"no":"01","title":"True in practice rather than on paper","titleCN":"名实落差：实际上","definition":"marks what is true in practice even though the formal position says otherwise, so that the real state differs from the stated one","definitionCN":"标出在做法上实际成立的状况，即便名目上另有说法，实际情况与纸面并不一致","example":"The ban was never repealed, but effectively no one pays the tax.","exampleCN":"那道禁令从未被废除，但实际上没有人缴这笔税。","why":"Efficere is to do a thing out and through; the adverb asks what the thing amounts to once it is done.","whyCN":"词根意为一路做到底、做成；这个副词问的是事情做成之后实际算个什么。"},{"no":"02","title":"Producing the intended result","titleCN":"有效地","definition":"the manner sense: an action or tool reaches the result it was meant to reach, and reaches it well","definitionCN":"方式义：一个动作或工具达到了它该达到的结果，而且达到得好","example":"The vaccine protects effectively against severe illness.","exampleCN":"这种疫苗能有效地防止重症。","why":"Effect is a result, so the manner adverb says the result was actually delivered.","whyCN":"「效果」就是结果，所以这个方式副词说的是结果真的被交付了。"},{"no":"03","title":"Amounting to all but not quite","titleCN":"大体上；几乎","definition":"approximates a total or a whole, close to virtually, but stated as what the case amounts to rather than how near it is","definitionCN":"近似一个全部或整体，接近「几乎」，但着眼的是「实际算作什么」而不是「离满还差多少」","example":"Effectively all of the respondents had heard of the scheme.","exampleCN":"实际上所有受访者都听说过这个方案。","why":"Counting the shortfall is one thing; asking what is left amounts to is another.","whyCN":"清点差多少是一回事，问剩下的实际算作什么是另一回事。"},{"no":"04","title":"The summing-up opener","titleCN":"句首总结","definition":"placed first to state the practical upshot of what has just been described, as a conclusion in plain terms","definitionCN":"置于句首，用平实的话说出前述内容在实际上的结论","example":"Effectively, the two schemes came to the same thing.","exampleCN":"实际上，这两个方案结果是一样的。","why":"A summary needs a word that says in practice before the plain statement is made.","whyCN":"总结需要一个在平实陈述之前先说「实际如何」的词。"},{"no":"05","title":"The parenthesis that lowers the tone","titleCN":"句中插入","definition":"set between commas to state the practical truth while the sentence keeps its formal shape","definitionCN":"用逗号夹在句中，在句子保持正式外形的同时说出实际真相","example":"The plan was, effectively, dead on arrival.","exampleCN":"这个计划实际上刚提出就死了。","why":"Insertion lets the writer keep the official frame and still say what happened.","whyCN":"插入让作者保住正式框架，同时把实际发生的事说出来。"},{"no":"06","title":"Not the same as virtually","titleCN":"与「几乎」的分界","definition":"the boundary against virtually: that word measures nearness to a limit, while this one judges what a thing amounts to in practice","definitionCN":"与「几乎」的分界：那个词衡量离极限有多近，这个词判断一件事实际算作什么","example":"Virtually counts how near a thing is; effectively asks what it amounts to.","exampleCN":"「几乎」计算离得多近；这个词问实际算作什么。","why":"Nearness and amount are different questions: one asks how much is missing, the other what the total counts as.","whyCN":"接近与总量是两个问题：一个问还差多少，一个问总数算作什么。"},{"no":"07","title":"Not the same as in effect","titleCN":"与「实际上」短语的分界","definition":"the boundary against the phrase in effect: the phrase usually stands after the verb, while this adverb can also take the front of a clause","definitionCN":"与短语「实际上」的分界：那个短语通常站在动词之后，这个副词还能站到小句前面","example":"In effect is a phrase after the verb; effectively is the adverb that can open a clause.","exampleCN":"那个短语跟在动词后；这个副词却能开句。","why":"Grammar, not meaning, separates the two: one is a phrase, the other has an adverb's freedom of position.","whyCN":"分开两者的是语法而不是意思：一个是短语，另一个有副词那样换位置的本事。"},{"no":"08","title":"Not the same as actually","titleCN":"与「其实」的分界","definition":"the boundary against actually: that word corrects an assumption, while this one judges the practical effect of what is there","definitionCN":"与「其实」的分界：那个词纠正一个预设，这个词判断眼前之物在实效上如何","example":"Actually corrects what was assumed; effectively judges what the thing amounts to.","exampleCN":"「其实」纠正别人以为的事；这个词判断这件事实际算个什么。","why":"Correcting an assumption and weighing an effect are separate moves, and English marks them with separate adverbs.","whyCN":"纠正预设与权衡实效是两种动作，英语用两个副词分别标记。"}],"etymology":{"intro":{"en":"Effectively is effective plus -ly. Effective comes from Latin efficere, to work out or accomplish, from ex- out and facere to do or make. Effect is what has been brought about; the adverb says what a thing amounts to in practice.","cn":"这个词由形容词加副词词尾构成。形容词来自拉丁语 efficere「做出、完成」，由 ex-「向外」与 facere「做、造」构成。效果就是被做出来的东西；这个副词说的是一件事在实际中算作什么。"},"items":[{"era":"LATIN FACERE","en":"Facere meant to do or make, and it stands behind the English words for a fact, a factory and a manufacture.","cn":"这个词意为做、造，英语里表示事实、工厂、制造的那些词都由它而来。"},{"era":"LATIN EX-","en":"The prefix meant out, and it gave the compound the sense of carrying something through to the end.","cn":"这个前缀意为「向外」，它让复合词带上「一路做到底」的意思。"},{"era":"LATIN EFFICERE","en":"Ex- plus facere meant to work out, accomplish or bring about.","cn":"ex- 加 facere 意为做出、完成、促成。"},{"era":"LATIN EFFECTUS","en":"The participle meant accomplished, and as a noun it meant the result of the doing.","cn":"这个分词意为「已完成的」，作名词则指做出来的结果。"},{"era":"ENGLISH EFFECT AND EFFECTIVE","en":"English took the noun for a result and the adjective for what produces one.","cn":"英语借来名词表示结果，借来形容词表示能产生结果的。"},{"era":"EFFECTIVELY","en":"The adverb grew two uses, in practice and with effect; the exact date of the first is uncertain.","cn":"这个副词长出两种用法：实际上、有效地；前一种的首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the doing stem, with one word from an unrelated family; the second holds the near synonyms that are regularly confused with it.","cn":"第一组共享「做」这一词干，另有一个来自无关词族的形近词；第二组是常与它混淆的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"effect","ipa":"/ɪˈfekt/","tag":"same root","definition":"A result or an impression, and as a verb, to bring something about.","definitionCN":"指结果或印象，作动词则指使某事发生。"},{"word":"effective","ipa":"/ɪˈfektɪv/","tag":"same root","definition":"Producing the result intended, or in force from a stated date.","definitionCN":"指能产生预期结果的，也指从某日起生效的。"},{"word":"effectiveness","ipa":"/ɪˈfektɪvnəs/","tag":"same root","definition":"The degree to which something produces the result intended.","definitionCN":"指某物达到预期结果的程度。"},{"word":"ineffective","ipa":"/ˌɪnɪˈfektɪv/","tag":"same root","definition":"Not producing the result intended.","definitionCN":"指未能产生预期结果的。"},{"word":"effusive","ipa":"/ɪˈfjuːsɪv/","tag":"different root","definition":"From ex- and fundere, to pour out, not from facere; it means overflowing with feeling.","definitionCN":"来自「向外倒出」而非「做」；意为感情洋溢的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"virtually","ipa":"/ˈvɜːtʃuəli/","tag":"near meaning","definition":"Nearly, in respect of amount or degree, sometimes also in effect.","definitionCN":"指在数量或程度上几乎，有时也指实际上。"},{"word":"in effect","ipa":"/ɪn ɪˈfekt/","tag":"near meaning","definition":"A phrase stating what is true in practice, usually placed after the verb.","definitionCN":"短语，说明实际上如何，通常放在动词之后。"},{"word":"actually","ipa":"/ˈæktʃuəli/","tag":"near meaning","definition":"In fact, often used to correct what was assumed.","definitionCN":"指事实上，常用于纠正别人的预设。"},{"word":"practically","ipa":"/ˈpræktɪkli/","tag":"near meaning","definition":"In practice, or almost; also means in a practical manner.","definitionCN":"指实际上或几乎，也指以务实的方式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of doing through to the end, the real effect family, and the gap between a label and a practice.","cn":"正常联想使用拉丁语里「一路做到底」的动词、真实的效果词族，以及名目与做法之间的那道缝。"},"normal":[{"en":"Facere is to do or make, and efficere is to do it out and through, to accomplish.","cn":"词根意为「做、造」，「做出」则是一路做到底、做成。"},{"en":"Effect is the done thing; effective is the doing that gets it done.","cn":"「效果」是做成之事，「有效的」是把它做成的那股劲。"},{"en":"In effect is the phrase; effectively is the adverb that says the same at the front of a clause.","cn":"「实际上」有一个短语形式，也有一个副词形式，后者可以站在小句前面。"},{"en":"Effectively all means nearly all; virtually all means the same with a different accent.","cn":"「实际上全部」近乎全部，「几乎全部」说的是同一件事，只是着重点不同。"},{"en":"Communicate effectively is the manner use: do the work well, not merely in the end.","cn":"「有效地沟通」用的是方式义：把事做好，而不只是最后算总账。"}],"abstract":[{"en":"What a thing amounts to is not the same as what it is called.","cn":"一样东西实际算作什么，与它被称作什么，并不是一回事。"},{"en":"A rule that is never used has an effect that is no effect.","cn":"一条从不被使用的规则，其效果就是没有效果。"},{"en":"Effectiveness is measured at the end, which is why the word so often sounds like a verdict.","cn":"有效与否要到末尾才量得出来，所以这个词听上去常像一句判词。"}]},"examples":[{"en":"The tax was never abolished, yet effectively no one pays it.","cn":"这项税从未被废除，但实际上没有人缴。"},{"en":"A short memo can communicate effectively if it is well organised.","cn":"一份简短的备忘录只要组织得当，也能有效地传达信息。"},{"en":"Effectively, the merger gave one firm control of the market.","cn":"实际上，这次合并让一家公司控制了市场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊菲克提夫利」——名目还挂在墙上，实际早照另一套办：实际上","word":"effectively"},"root":"拉丁语 facere「做、造」→ efficere「做出、完成」（ex-「向外」＋facere）→ effectus「结果」→ 英语 effect／effective → 加副词词尾构成。直接来源清楚；两种用法的首见年代为约数。","sensesIntro":{"en":"Eight senses divide by what is being judged and where the word stands: real practice against the record, the manner of doing something well, an amount that is all but total, the summing-up opener, the parenthesis, and the boundaries against three near synonyms.","cn":"八个义项按「判断什么」与「站在哪里」分开：实际做法与纸面记录、把事情做好的方式、几乎等于全部的程度、句首总结、句中插入，以及与三个近义词的分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rule still hangs on the wall while the counter follows another practice, and the label and the practice sit in two columns.","cn":"核心意象：规定还挂在墙上，柜台却按另一套做法办事，名目与做法分列两栏。"},"chain":["A DOING","CARRIED THROUGH","A RESULT","WHAT IT AMOUNTS TO","IN PRACTICE","A VERDICT"],"branches":[{"senses":"01 · 05","en":"THE GAP AND THE ASIDE: what is true in practice, stated plainly or slipped in between commas.","cn":"落差与旁注：实际成立的状况，或平直说出，或用逗号夹进句中。"},{"senses":"02","en":"THE MANNER: the work is done well enough to deliver its result.","cn":"方式：事情做得够好，结果真的被交付。"},{"senses":"03","en":"THE APPROXIMATE WHOLE: all but not quite, judged by what it amounts to.","cn":"近似的整体：几乎等于全部，着眼的是实际算作什么。"},{"senses":"04","en":"THE SUMMING-UP: a plain statement of the practical upshot.","cn":"总结：把实际结论用平实的话说出来。"},{"senses":"06 · 07 · 08","en":"THREE BOUNDARIES: nearness, a phrase after the verb, and the correction of an assumption.","cn":"三条分界：接近程度、动词后的短语、对预设的纠正。"}]},"affixes":{"intro":{"en":"Effectively is a Latin verb of doing with a prefix and an English adverb ending, and its family is one of the most productive in English.","cn":"这个词是一个带前缀的拉丁语「做」动词，套着英语副词词尾；它的词族是英语里最能产的之一。"},"latinIntro":{"en":"Latin supplies ex-, facere, efficere and effectus; English supplies effect, effective and the endings.","cn":"拉丁语提供了 ex-、facere、efficere 与 effectus；英语提供了 effect、effective 与词尾。"},"items":[{"word":"ex-","structure":"Latin prefix","meaning":"out, thoroughly","meaningCN":"向外；彻底","example":"It carries the doing out to its end.","exampleCN":"它把「做」一路带到终点。"},{"word":"facere","structure":"Latin verb","meaning":"to do, make","meaningCN":"做；制造","example":"The verb is the plain act of making.","exampleCN":"这个动词就是最朴素的「做」。"},{"word":"efficere","structure":"Latin verb","meaning":"to work out, accomplish","meaningCN":"做出；完成","example":"The compound means to carry a thing through.","exampleCN":"这个复合词意为把一件事做到底。"},{"word":"effectus","structure":"Latin participle and noun","meaning":"accomplished; result","meaningCN":"已完成的；结果","example":"The participle becomes the noun of the result.","exampleCN":"这个分词变成表示结果的名词。"},{"word":"effect","structure":"English noun","meaning":"a result, an impression","meaningCN":"结果；效果","example":"English keeps the noun for what was brought about.","exampleCN":"英语保留名词，指被做出来的东西。"},{"word":"effective","structure":"English adjective","meaning":"producing a result","meaningCN":"产生效果的","example":"The adjective describes what delivers a result.","exampleCN":"这个形容词描述能交付结果的东西。"},{"word":"-ive","structure":"Latin adjective ending","meaning":"having the nature of","meaningCN":"具有……性质的","example":"It turns the noun of result into an adjective.","exampleCN":"它把结果名词变成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It makes the adverb of practice and of effect.","exampleCN":"它构成表示「实际上」与「有效地」的副词。"},{"word":"-ness","structure":"English noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of effectiveness.","exampleCN":"它构成表示「有效性」的名词。"}],"latinEntries":[{"word":"ex-","structure":"Latin prefix","meaning":"out, thoroughly","meaningCN":"向外；彻底"},{"word":"facere","structure":"Latin verb","meaning":"to do, make","meaningCN":"做；制造"},{"word":"efficere","structure":"Latin verb","meaning":"to work out, accomplish","meaningCN":"做出；完成"},{"word":"effectus","structure":"Latin participle and noun","meaning":"accomplished; result","meaningCN":"已完成的；结果"},{"word":"efficax","structure":"Latin adjective","meaning":"effective, productive","meaningCN":"有效的；能产出的"}],"derivatives":[{"word":"effect","pos":"n.","zh":"由拉丁语「做出之事」的过去分词构成名词，义为「结果」"},{"word":"effective","pos":"adj.","zh":"由效果名词加表示性质的形容词词尾构成，义为「有效的」"},{"word":"effectiveness","pos":"n.","zh":"由有效形容词加表示性质的名词尾构成，义为「有效性」"},{"word":"ineffective","pos":"adj.","zh":"由有效形容词加否定前缀构成，义为「无效的」"},{"word":"effectual","pos":"adj.","zh":"由效果名词加形容词词尾构成，义为「奏效的」"}]}},{"word":"eventually","ipa_uk":"/ɪˈventʃuəli/","ipa_us":"/ɪˈventʃuəli/","definition_zh":"最终；终于；最后；迟早","definition_en":"used to say that something happens in the end, after a long time or after a series of delays, without saying exactly when","core_image":"一条长长的走廊，尽头那盏灯在走过许多扇关着的门之后才亮起来","scene":"站台上的人群已经等了很久，广播一次又一次推迟到站时间，最后列车终于进站。The delayed train eventually pulled into the platform.","sceneCN":"这里指经过多次延误之后终于发生（第 2 个义项：几经拖延之后终于）；句意为晚点的列车最终驶入了站台。场景要点：久等的人群、反复推迟的广播、终于进站的列车。","pos":[{"tag":"adv.","zh":"最终；终于；最后；迟早"}],"collocations":[{"phrase":"eventually become","zh":"最终成为"},{"phrase":"eventually lead to","zh":"最终导致"},{"phrase":"will eventually","zh":"终将"},{"phrase":"eventually agreed to","zh":"最终同意"},{"phrase":"eventually die out","zh":"最终灭绝"},{"phrase":"eventually, however","zh":"不过最终"}],"forms":[{"label":"无词形变化（副词）","form":"eventually"}],"derivatives":[{"word":"eventual","pos":"adj.","zh":"由拉丁词干加形容词词尾构成，义为「最终的、最后发生的」"},{"word":"eventuality","pos":"n.","zh":"由「最终的」形容词加表示状态的名词尾构成，义为「可能发生的结局、不测之事」"},{"word":"eventuate","pos":"v.","zh":"由拉丁词干加动词词尾构成，义为「最终发生、结果为」"},{"word":"event","pos":"n.","zh":"由同一拉丁词根「出来、发生」经法语构成名词，义为「事件」"},{"word":"eventful","pos":"adj.","zh":"由事件名词加表示「充满……的」形容词词尾构成，义为「多事的」"}],"senses":[{"no":"01","title":"In the end, after a long time","titleCN":"经过漫长的时间之后","definition":"marks an outcome that comes about only after a considerable stretch of time, with the length of that stretch left vague","definitionCN":"标出一个经过相当长一段时间才出现的结果，这段时间有多长并不说明","example":"The old bridge eventually collapsed under the weight of the lorries.","exampleCN":"那座老桥最终在货车的重压下坍塌了。","why":"The Latin verb means to come out or turn out, so the word looks at the outcome from the far end of the waiting.","whyCN":"拉丁动词意为「出来、结果成为」，因此这个词是从等待的远端回看结果。"},{"no":"02","title":"After repeated delays","titleCN":"几经拖延之后终于","definition":"used when something has been postponed or blocked several times before it happens","definitionCN":"用于某事几经推迟或受阻之后才终于发生","example":"The delayed train eventually pulled into the platform.","exampleCN":"晚点的列车最终驶入了站台。","why":"Each delay pushes the event further off, and the adverb marks the point where the pushing stops.","whyCN":"每一次延误都把这件事推得更远，而这个副词标记的就是「不再往前推」的那一刻。"},{"no":"03","title":"At the close of a gradual process","titleCN":"渐进过程的终点","definition":"marks the end point of a slow natural or technical process whose stages are not separately noticed","definitionCN":"标出一个缓慢的自然或技术过程的终点，其各个阶段并不被逐一注意","example":"The wound eventually healed, leaving only a thin scar.","exampleCN":"伤口最终愈合，只留下一条细疤。","why":"Growth and decay work by small increments, and the adverb names the moment the increments finish.","whyCN":"生长与衰败都是靠细小的增量进行的，这个词命名的就是增量走完的那一刻。"},{"no":"04","title":"A distant future outcome","titleCN":"将来迟早会发生","definition":"refers to an outcome expected in the future, often after a long interval, with the timing left open","definitionCN":"指预料在将来出现的结果，往往隔着很长一段时间，具体时间并不确定","example":"She will eventually have to sell the house.","exampleCN":"她迟早得把那栋房子卖掉。","why":"The word does not promise speed; it promises arrival.","whyCN":"这个词不承诺快，只承诺会到。"},{"no":"05","title":"Sentence-initial narrative frame","titleCN":"句首叙述收束","definition":"placed first in a narrative sentence to announce the outcome before its circumstances","definitionCN":"置于叙述句的句首，先把结果说出来，再交代其来龙去脉","example":"Eventually, the two sides agreed to meet without conditions.","exampleCN":"最终，双方同意无条件会面。","why":"A storyteller may put the ending first so that the listener waits for the how.","whyCN":"讲故事的人可以把结局放在前面，让听者去等「怎么走到这里」。"},{"no":"06","title":"Sentence-final spoken emphasis","titleCN":"句末口语强调","definition":"in speech, placed at the end so that the outcome lands with relief, exasperation or surprise","definitionCN":"在口语中置于句末，使结果带着宽慰、无奈或意外的语气落下","example":"They got the permit eventually, after four visits.","exampleCN":"跑了四趟之后，他们到底还是拿到了许可证。","why":"At the end of a spoken line the outcome is the last thing heard, and the voice can carry the feeling.","whyCN":"在口语里放在句末，结果是最后听见的东西，语气于是能把情绪带出来。"},{"no":"07","title":"Asking whether the outcome came","titleCN":"追问结果是否终于发生","definition":"in questions, asks whether a long-awaited outcome was reached, not when it happened","definitionCN":"在疑问句中问的是久等的结果究竟有没有实现，而不是它何时发生","example":"Did the manuscript eventually reach the publisher?","exampleCN":"那份手稿最终送到出版商手里了吗？","why":"A question about the end of a wait is a question about arrival, not about schedule.","whyCN":"追问一段等待的终点，问的是「到了没有」，不是「排在几时」。"},{"no":"08","title":"Certain of the outcome, vague about the time","titleCN":"结果确定而时间含糊","definition":"the pragmatic force: asserts that something will happen while refusing to commit to a date","definitionCN":"语用效果：断言某事一定会发生，同时拒绝对具体日期作出承诺","example":"The policy will eventually be reviewed, though no date has been set.","exampleCN":"这项政策终将接受审议，尽管日期尚未确定。","why":"The word buys certainty about the end by giving up precision about the middle.","whyCN":"这个词用放弃中途的精确，换来了对结局的确定。"},{"no":"09","title":"Not the same as finally or ultimately","titleCN":"与「终于」「根本上」的分界","definition":"the boundary sense: eventually stresses elapsed time, finally marks a last step or the end of waiting, ultimately points to the final analysis or the basic level","definitionCN":"分界义：这个词强调流逝的时间，「终于」标记最后一步或等待结束，「根本上」指向最终分析或根本层面","example":"Eventually reports the passing of time; finally reports the last item in a series.","exampleCN":"这个词报告的是时间的流逝；「终于」报告的是序列里的最后一项。","why":"Three words look like synonyms but answer different questions: when, which one last, and at bottom.","whyCN":"三个词看似同义，回答的却是不同问题：什么时候、哪一项最后、归根到底。"}],"etymology":{"intro":{"en":"Eventually is eventual plus -ly. Eventual comes from Latin eventus, an outcome, from evenire, to come out or turn out, built on ex- out and venire to come. The adverb adds manner: in the way that an outcome arrives.","cn":"eventually 是 eventual 加 -ly。eventual 来自拉丁语 eventus「结果」，出自动词 evenire「出来、结果成为」，由 ex-「向外」与 venire「来」构成。副词再加方式：以结局最终到来的方式。"},"items":[{"era":"LATIN VENIRE","en":"Venire meant to come, and it stands behind advent, invent, prevent and event.","cn":"这个词意为「来」，advent、invent、prevent 与 event 都由它而来。"},{"era":"LATIN EVENIRE","en":"Ex- plus venire made a verb of coming out, happening or turning out.","cn":"ex- 加 venire 构成动词，意为出来、发生、结果成为。"},{"era":"LATIN EVENTUS","en":"The noun named an outcome or occurrence, the thing that turns out.","cn":"这个名词指结果或发生之事，即最终呈现出来的东西。"},{"era":"OLD FRENCH EVENT","en":"French carried the noun into English, where it covered both an occurrence and its outcome.","cn":"法语把这个名词带入英语，在英语里它兼指发生之事与其结果。"},{"era":"ENGLISH EVENTUAL","en":"The adjective marked what comes at the end of a process; its first use is dated only approximately.","cn":"这个形容词标记一个过程末尾出现的事；其首次使用年代仅为约数。"},{"era":"EVENTUALLY","en":"The adverb was formed from the adjective to mark the end of a wait; the exact date of that formation is uncertain.","cn":"副词由该形容词构成，用来标记一段等待的终点；其形成的确切年代不确定。"}]},"similar":{"note":{"en":"The first group shares the coming-out stem; the second holds the time words it is most often weighed against.","cn":"第一组共享「出来、发生」的词干；第二组是常拿来与它比较的时间说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"eventual","ipa":"/ɪˈventʃuəl/","tag":"same root","definition":"Happening at the end of a process; final rather than immediate.","definitionCN":"指在一个过程末尾发生的、最终的，而非立即的。"},{"word":"eventuality","ipa":"/ˌiːvenˈtjuːæləti/","tag":"same root","definition":"A possible outcome or contingency that may have to be dealt with.","definitionCN":"指可能出现的结局或需要应对的意外情况。"},{"word":"eventuate","ipa":"/ɪˈventʃueɪt/","tag":"same root","definition":"To happen or to result in the end.","definitionCN":"指最终发生或最终导致某种结果。"},{"word":"event","ipa":"/ɪˈvent/","tag":"same root","definition":"Something that happens, especially something notable.","definitionCN":"指发生之事，尤指值得注意的事件。"},{"word":"evenly","ipa":"/ˈiːvnli/","tag":"different root","definition":"In an equal or uniform way, from even; it has nothing to do with coming out or an outcome.","definitionCN":"指均匀地、平等地，来自意为「平坦、相等」的古英语词，与「出来、结果」毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"finally","ipa":"/ˈfaɪnəli/","tag":"near meaning","definition":"Marks the last item in a series or the end of a wait, often with relief in the voice.","definitionCN":"标记序列中的最后一项或等待的结束，语气常带宽慰。"},{"word":"ultimately","ipa":"/ˈʌltɪmətli/","tag":"near meaning","definition":"At the most basic level, or after everything else has been considered.","definitionCN":"指在根本层面上，或在把其余一切考虑完之后。"},{"word":"in time","ipa":"/ɪn ˈtaɪm/","tag":"near meaning","definition":"After a period, often within an acceptable limit; it can also mean before a deadline.","definitionCN":"指过了一段时间之后，常含「还赶得上」之意；也可指在截止之前。"},{"word":"sooner or later","ipa":"/ˌsuːnə ɔː ˈleɪtə/","tag":"near meaning","definition":"Eventually, with the added claim that the outcome cannot be avoided.","definitionCN":"指迟早，另带「此事无法避免」的断言。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of coming, the event family, and the real phrases of waiting.","cn":"正常联想使用拉丁语「来」这个动词、事件词族，以及等待场景里的真实说法。"},"normal":[{"en":"Venire is to come, evenire is to come out: the word is what comes out at the far end.","cn":"「来」是来，「出来」是出来：这个词指的就是在远端出来的那个东西。"},{"en":"Event, eventual, eventuality and eventually are one family, one root, four jobs.","cn":"事件、最终的、可能结局与最终：一个词族，一个词根，四份差事。"},{"en":"A train that is repeatedly delayed is the clearest picture: the word only says the arrival happened.","cn":"一再晚点的列车是最清楚的画面：这个词只说明「到站」这件事发生了。"},{"en":"Put it at the end of a spoken sentence and the relief does the talking.","cn":"把它放在口语的句末，说话的就不是词，而是那口松下来的气。"},{"en":"It never says when; it only says that the end has a door.","cn":"它从不说「几时」，只说尽头有一道门。"}],"abstract":[{"en":"Time is the only thing the word spends; the outcome is what it buys.","cn":"这个词只花一样东西，就是时间；它买回来的，是结果。"},{"en":"Every long wait has a shape, and the word is the far end of that shape.","cn":"每一段长久的等待都有形状，这个词就是那个形状的远端。"},{"en":"What is certain in the end can still be uncertain in the middle.","cn":"结局确定的事，在中途仍然可以是不确定的。"}]},"examples":[{"en":"The negotiations eventually produced a workable agreement.","cn":"谈判最终产生了一份可行的协议。"},{"en":"After three false starts, the engine eventually started.","cn":"三次启动失败之后，发动机终于发动起来了。"},{"en":"Scientists believe the glacier will eventually disappear.","cn":"科学家认为这条冰川终将消失。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊文初尔利」——一件事走了很久，最后还是走到了：最终、终于","word":"eventually"},"root":"拉丁语 venire「来」→ ex- + venire 构成 evenire「出来、结果成为」→ 名词 eventus「结果」→ 古法语 → 英语 event 与 eventual，再加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses differ by the length and kind of waiting: a long time, repeated delays, a gradual process, a future outcome, the sentence-initial frame, the spoken final position, the question about arrival, the refusal to give a date, and the line against finally and ultimately.","cn":"九个义项按等待的长短与性质分开：漫长之后、几经拖延、渐进过程、将来结局、句首收束、句末强调、追问是否到达、不给日期、以及与「终于」「根本上」的分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long corridor, and a lamp at the far end that lights up only after many shut doors.","cn":"核心意象：一条长走廊，尽头的灯在走过许多关着的门之后才亮起来。"},"chain":["A LONG WAIT","TIME PASSES","DELAYS ACCUMULATE","THE OUTCOME COMES","THE END ARRIVES","CERTAIN BUT UNDATED"],"branches":[{"senses":"01","en":"THE END AFTER TIME: the outcome exists, and only the elapsed years explain it.","cn":"时间之后的终点：结果出现了，解释它的只有流逝的岁月。"},{"senses":"02 · 03","en":"DELAYS AND GRADUAL PROCESSES: repeated postponement, or a slow change finishing at last.","cn":"拖延与渐进：要么一再推迟，要么一场缓慢的变化终于走完。"},{"senses":"04 · 08","en":"THE FUTURE WITHOUT A DATE: arrival is promised, the calendar is left blank.","cn":"没有日期的将来：到达被承诺，日历却留白。"},{"senses":"05 · 06","en":"THE TWO POSITIONS: the head of a narrative, the end of a spoken line.","cn":"两个位置：叙述的开头，口语的句末。"},{"senses":"07 · 09","en":"THE QUESTION AND THE BOUNDARY: was it reached, and how it differs from finally and ultimately.","cn":"追问与分界：究竟到了没有，以及它与「终于」「根本上」的区别。"}]},"affixes":{"intro":{"en":"Eventually is a Latin verb of coming, wearing an adjective ending and an adverb ending; its family covers events, outcomes and contingencies.","cn":"这个词是一个披着形容词词尾与副词词尾的拉丁「来」动词，其词族覆盖事件、结局与可能情况。"},"latinIntro":{"en":"Latin supplies venire and evenire, and the noun eventus; Old French carried event into English.","cn":"拉丁语提供了 venire 与 evenire，以及名词 eventus；古法语把 event 带入英语。"},"items":[{"word":"venire","structure":"Latin verb","meaning":"to come","meaningCN":"来","example":"The verb is the coming half of the compound.","exampleCN":"这个动词是复合词里「来」的那一半。"},{"word":"ex-","structure":"Latin prefix","meaning":"out, out of","meaningCN":"向外；出","example":"It turns coming into coming out.","exampleCN":"它把「来」变成「出来」。"},{"word":"evenire","structure":"Latin verb","meaning":"to come out, turn out, happen","meaningCN":"出来；结果成为；发生","example":"The verb names what an outcome does.","exampleCN":"这个动词说出的就是结果的动作。"},{"word":"eventus","structure":"Latin noun","meaning":"outcome, event","meaningCN":"结果；事件","example":"The noun names the thing that has come out.","exampleCN":"这个名词指已经出来的那个东西。"},{"word":"event","structure":"English noun through French","meaning":"an occurrence, an outcome","meaningCN":"事件；结果","example":"English uses it for anything that happens.","exampleCN":"英语用它指任何发生之事。"},{"word":"eventual","structure":"English adjective","meaning":"final, happening in the end","meaningCN":"最终的","example":"The adjective marks the far end of a process.","exampleCN":"这个形容词标记过程的远端。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or relating to","meaningCN":"属于……的","example":"It forms the adjective from the noun.","exampleCN":"它由名词构成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It forms the adverb of arrival.","exampleCN":"它构成表示「最终到来」的副词。"},{"word":"-ity","structure":"Latin noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms eventuality, a possible outcome.","exampleCN":"它构成 eventuality，即可能的结局。"}],"latinEntries":[{"word":"venire","structure":"Latin verb","meaning":"to come","meaningCN":"来"},{"word":"evenire","structure":"Latin verb","meaning":"to come out, turn out","meaningCN":"出来；结果成为"},{"word":"eventus","structure":"Latin noun","meaning":"outcome, event","meaningCN":"结果；事件"},{"word":"ex-","structure":"Latin prefix","meaning":"out, out of","meaningCN":"向外；出"}],"derivatives":[{"word":"eventual","pos":"adj.","zh":"由拉丁词干加形容词词尾构成，义为「最终的」"},{"word":"eventuality","pos":"n.","zh":"由「最终的」形容词加表示状态的名词尾构成，义为「可能发生的结局」"},{"word":"eventuate","pos":"v.","zh":"由拉丁词干加动词词尾构成，义为「最终发生」"},{"word":"event","pos":"n.","zh":"由同一拉丁词根经法语构成名词，义为「事件」"},{"word":"eventful","pos":"adj.","zh":"由事件名词加表示「充满……的」形容词词尾构成，义为「多事的」"}]}},{"word":"evidently","ipa_uk":"/ɪˈvɪdəntli/","ipa_us":"/ɪˈvɪdəntli/","definition_zh":"显然；看来；从迹象看；据证据推断","definition_en":"used to say that something appears to be true from the evidence or signs available, rather than from direct certainty","core_image":"地上一串湿脚印通向屋内，伞架还在滴水，人没有露面，痕迹先说了话","scene":"门口的地板上有一串湿脚印通向屋内，伞架上还滴着水，屋主显然刚刚回来过。The floor was wet and the umbrella stand was dripping; evidently, someone had just come in from the rain.","sceneCN":"这里指从屋内的水迹与滴水的伞推断有人刚回来（第 1 个义项：据可见迹象推断）；句意为地板是湿的，伞架还在滴水，显然有人刚冒雨进来。场景要点：湿脚印、滴水的伞、被推断出的归来。","pos":[{"tag":"adv.","zh":"显然；看来；据证据推断"}],"collocations":[{"phrase":"evidently true","zh":"显然是真的"},{"phrase":"evidently not","zh":"显然不是"},{"phrase":"evidently the case","zh":"显然就是这种情况"},{"phrase":"quite evidently","zh":"十分明显地"},{"phrase":"evidently pleased","zh":"显然很高兴"},{"phrase":"evidently from","zh":"从……可以明显看出"}],"forms":[{"label":"无词形变化（副词）","form":"evidently"}],"derivatives":[{"word":"evident","pos":"adj.","zh":"由拉丁语「看得出来」的分词加形容词词尾构成，义为「明显的」"},{"word":"evidence","pos":"n.","zh":"由同一拉丁词干加表示状态的名词尾构成，义为「证据」"},{"word":"evidential","pos":"adj.","zh":"由证据名词加表示「属于……的」形容词词尾构成，义为「证据的」"},{"word":"evidentiary","pos":"adj.","zh":"由证据名词加表示「用于……的」形容词词尾构成，义为「证据性的」"},{"word":"self-evident","pos":"adj.","zh":"由自身代词与「明显的」形容词复合而成，义为「不言而喻的」"}],"senses":[{"no":"01","title":"Signs that point to a fact","titleCN":"据可见迹象推断","definition":"marks a conclusion drawn from visible traces rather than from direct observation","definitionCN":"标出一个从可见痕迹推出、而非亲眼看到的结论","example":"The floor was wet and the umbrella stand was dripping; evidently, someone had just come in from the rain.","exampleCN":"地板是湿的，伞架还在滴水；显然有人刚冒雨进来。","why":"The Latin participle means able to be seen out in the open, so the word leans on what the eye can find.","whyCN":"拉丁分词意为「能当众看见」，因此这个词倚靠的是眼睛能找到的东西。"},{"no":"02","title":"Data and results","titleCN":"据数据与结果推断","definition":"used in research and analysis when the figures point to a conclusion that has not been directly proved","definitionCN":"在研究与分析中，当数字指向一个尚未被直接证明的结论时使用","example":"Evidently, the second sample had been exposed to light.","exampleCN":"显然，第二份样本曾暴露在光下。","why":"Instruments extend the eye, and what the data show is treated as a kind of seeing.","whyCN":"仪器是眼睛的延长，数据所显示的东西被当作一种「看见」。"},{"no":"03","title":"Sentence-initial report signpost","titleCN":"句首正式提示","definition":"in reports and papers, placed first to announce an inference before the evidence is spelled out","definitionCN":"在报告与论文中置于句首，先宣告推断，再逐条摆出依据","example":"Evidently, the two groups responded to the treatment differently.","exampleCN":"显然，两组对治疗的反应并不相同。","why":"Formal prose signposts the conclusion first because the reader wants the finding before the proof.","whyCN":"正式文章先标出结论，因为读者想先看到发现，再看证明。"},{"no":"04","title":"Mid-sentence parenthesis","titleCN":"句中插入","definition":"set between commas, the inference rides inside the clause instead of governing the sentence","definitionCN":"用逗号夹在句中，推断附着在从句内部，而不支配整句","example":"The manuscript evidently passed through at least three hands.","exampleCN":"这份手稿显然至少经过三个人的手。","why":"An adverb inside the clause attaches the inference to the verb, which makes it lighter than a sentence opener.","whyCN":"放在从句内部的副词把推断挂在动词上，比句首的说法轻。"},{"no":"05","title":"A concession one cannot refuse","titleCN":"不得不承认的让步","definition":"used to grant a point that the evidence has already made plain, often before arguing against it","definitionCN":"用来承认一个证据已经摆明的事实，往往是在反驳它之前","example":"Evidently, the plan has its merits, though the cost remains a problem.","exampleCN":"显然这项计划有其长处，尽管成本仍是个问题。","why":"Granting what is visible costs little and buys room for the argument that follows.","whyCN":"承认摆在眼前的事代价很小，却为随后的论证换来空间。"},{"no":"06","title":"Spoken irony or regret","titleCN":"口语里的无奈与讥讽","definition":"in speech, often with a falling tone, marks a fact that is obvious and mildly embarrassing or annoying","definitionCN":"在口语中常带降调，标记一个显而易见、又令人有点难堪或烦躁的事实","example":"Evidently, nobody thought to check the address.","exampleCN":"显然没人想到要核对一下地址。","why":"In speech the same word carries tone, and an obvious fact turns into a mild complaint.","whyCN":"在口语里同一个词带着语气，一个明显的事实就变成了轻轻的抱怨。"},{"no":"07","title":"The elliptical reply","titleCN":"简答：显然如此或显然不是","definition":"in the short replies evidently so and evidently not, the word answers a question with the evidence alone","definitionCN":"在「显然如此」「显然不是」这类简短回答里，这个词只用证据作答","example":"Was he surprised? Evidently not.","exampleCN":"他吃惊了吗？显然没有。","why":"Conversation drops the clause and leaves the adverb to carry the verdict.","whyCN":"对话省掉了整个小句，只留副词来承担判断。"},{"no":"08","title":"Not the same as obviously","titleCN":"与「一眼可见」的分界","definition":"the boundary sense: evidently works from signs and inference, while obviously works from what anyone can see at once","definitionCN":"分界义：这个词从迹象与推断出发，而「一眼可见」那个词从任何人都能立刻看到的东西出发","example":"Evidently points to evidence; obviously points to what is plain at a glance.","exampleCN":"这个词指向证据；「一眼可见」指向一眼就明白的东西。","why":"One word reasons from traces, the other reports immediate visibility.","whyCN":"一个词从痕迹推理，另一个词报告当下的可见。"},{"no":"09","title":"Not the same as apparently","titleCN":"与「据说、看来」的分界","definition":"the boundary sense: evidently rests on evidence, while apparently reports how things seem or what is said, often with doubt","definitionCN":"分界义：这个词以证据为据，而「看来」那个词转述事情表面如何或据说什么，常带怀疑","example":"Apparently he is resigning; evidently the letter has already been sent.","exampleCN":"据说他要辞职；而从他已寄出信件这一点看，事情显然已经定了。","why":"Hearsay and sight are different sources, and English keeps a separate word for each.","whyCN":"传闻与目睹是不同的来源，英语为二者各留了一个词。"}],"etymology":{"intro":{"en":"Evidently is evident plus -ly. Evident comes through Old French from Latin evidens, built on ex- out and videre to see; the word means able to be seen out in the open, and hence clear.","cn":"evidently 是 evident 加 -ly。evident 经古法语来自拉丁语 evidens，由 ex-「向外」与 videre「看见」构成；词义是「能当众被看见」，因此引申为清楚。"},"items":[{"era":"LATIN VIDERE","en":"Videre meant to see, and it stands behind vision, video and evident.","cn":"这个词意为「看见」，vision、video 与 evident 都由它而来。"},{"era":"LATIN EVIDENS","en":"The participle described something that can be seen out and so is plain to everyone.","cn":"这个分词描述能被看见、因而对人人清楚的东西。"},{"era":"LATIN EVIDENTIA","en":"The noun named clearness itself, the quality that makes a fact visible.","cn":"这个名词指「清楚」本身，即使事实可见的那种性质。"},{"era":"OLD FRENCH EVIDENT","en":"French passed the adjective to English, keeping the sense of plain and manifest.","cn":"法语把这个形容词传给英语，保留了「明白、显而易见」的意思。"},{"era":"ENGLISH EVIDENT","en":"English built the noun evidence and the adjective evident on the same stem.","cn":"英语在同一词干上造出名词 evidence 与形容词 evident。"},{"era":"EVIDENTLY","en":"The adverb was formed with -ly to mark an inference from signs; the exact date of its first use is uncertain.","cn":"副词由 -ly 构成，用来标记从迹象得出的推断；其首次使用的确切年代不确定。"}]},"similar":{"note":{"en":"The first group shares the seeing stem; the second holds the visibility words it is most often confused with.","cn":"第一组共享「看见」的词干；第二组是常与它混淆的几种「可见」说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"evident","ipa":"/ɪˈvɪdənt/","tag":"same root","definition":"Plain to see or to understand; manifest.","definitionCN":"指看得见或想得明白的、明显的。"},{"word":"evidence","ipa":"/ˈevɪdəns/","tag":"same root","definition":"Material or testimony that shows something to be true.","definitionCN":"指证明某事为真的材料或证词。"},{"word":"evidential","ipa":"/ˌevɪˈdenʃl/","tag":"same root","definition":"Relating to evidence, or serving as evidence.","definitionCN":"指与证据有关的，或可作证据的。"},{"word":"evidentiary","ipa":"/ˌevɪˈdenʃəri/","tag":"same root","definition":"Used in legal contexts for what may serve as evidence.","definitionCN":"法律语境中用于指可作为证据的。"},{"word":"eminently","ipa":"/ˈemɪnəntli/","tag":"different root","definition":"From Latin eminere, to stand out; it means very or outstandingly, and its root is eminere rather than videre.","definitionCN":"来自拉丁语中意为「突出」的词，意为非常、卓越地；其词根与「看见」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"obviously","ipa":"/ˈɒbviəsli/","tag":"near meaning","definition":"Marks what anyone can see at once, with no inference needed.","definitionCN":"标记任何人都能立刻看见、无需推断的事。"},{"word":"apparently","ipa":"/əˈpærəntli/","tag":"near meaning","definition":"Reports how things seem or what is said, often with a hint of doubt.","definitionCN":"转述事情表面如何或据说什么，常带一丝怀疑。"},{"word":"clearly","ipa":"/ˈklɪəli/","tag":"near meaning","definition":"Marks what is easy to understand, whether seen or reasoned.","definitionCN":"标记容易理解的事，无论来自看见还是推理。"},{"word":"plainly","ipa":"/ˈpleɪnli/","tag":"near meaning","definition":"Marks what is openly visible or simply stated, without adornment.","definitionCN":"标记公开可见或说得直白、不加修饰的事。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin verb of seeing, the evidence family, and the real report phrases.","cn":"正常联想使用拉丁语「看见」这个动词、证据词族，以及报告里的真实说法。"},"normal":[{"en":"Videre is to see; evidens is able to be seen out, and evidently is the claim that the signs are enough.","cn":"「看见」是看，「看得出来」是看得出来；这个词断言的就是迹象已经够了。"},{"en":"Evidence, evident, evidential and evidently are one family, one root, four jobs.","cn":"证据、明显的、证据性的与显然：一个词族，一个词根，四份差事。"},{"en":"A wet floor is the camera this word trusts more than any witness.","cn":"湿地板就是这个词最信的那台相机，比任何证人都可靠。"},{"en":"At the head of a report it sounds careful, not certain.","cn":"放在报告开头，它听起来是谨慎，而不是断定。"},{"en":"Evidently not is the shortest verdict in English conversation.","cn":"「显然不是」是英语对话里最短的一句判决。"}],"abstract":[{"en":"What is seen is not yet proved, but it is already more than guessed.","cn":"看见的还不算证明，但已经不止是猜测。"},{"en":"Evidence is a small light; the word is the claim that the light is enough.","cn":"证据是一点小光；这个词就是「这点光够了」的主张。"},{"en":"The word keeps faith with the eye, but leaves the last step to argument.","cn":"这个词忠于眼睛，却把最后一步留给论证。"}]},"examples":[{"en":"Evidently, the water in the tank had not been changed for weeks.","cn":"显然，水箱里的水已经好几周没换了。"},{"en":"The window was broken from the inside, evidently by someone in a hurry.","cn":"窗子是从里面打破的，显然是一个匆忙的人所为。"},{"en":"She was evidently relieved to hear the result.","cn":"听到结果，她显然松了一口气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「依维登特利」——湿脚印就摆在那里，不认也不行：显然、看来","word":"evidently"},"root":"拉丁语 videre「看见」→ ex- + videre 构成 evidens「看得出来、明显」→ 名词 evidentia「清楚」→ 古法语 → 英语 evident，再加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses differ by where the evidence comes from and where the word sits: visible traces, data, the sentence-initial report, the parenthesis, the concession, the spoken irony, the elliptical reply, and the two boundaries against obviously and apparently.","cn":"九个义项按证据来源与位置分开：可见痕迹、数据、报告句首、句中插入、让步、口语讥讽、简短回答，以及与「一眼可见」「据说看来」的两处分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: wet footprints crossing the floor while the person himself stays out of sight.","cn":"核心意象：湿脚印穿过地板，而人本身始终没有露面。"},"chain":["A SIGN","OBSERVED","AN INFERENCE","STATED","CONCEDED","THE SOURCE NAMED"],"branches":[{"senses":"01","en":"THE TRACE: the fact is read off what the eye can find.","cn":"痕迹：事实是从眼睛能找到的东西上读出来的。"},{"senses":"02","en":"THE DATA: instruments do the seeing, and the figures carry the inference.","cn":"数据：仪器代为观看，数字承载推断。"},{"senses":"03 · 04","en":"THE TWO POSITIONS IN WRITING: at the head of a report, or inside the clause.","cn":"书面里的两个位置：报告句首，或从句内部。"},{"senses":"05 · 07","en":"THE GRANT AND THE SHORT ANSWER: a point conceded, a verdict left standing alone.","cn":"让步与简答：承认一点，或让一句判决独自站着。"},{"senses":"06 · 08 · 09","en":"THE TONE AND THE TWO BOUNDARIES: irony in speech, and the lines against obvious sight and hearsay.","cn":"语气与两处分界：口语中的讥讽，以及和「一眼可见」「据说看来」的界线。"}]},"affixes":{"intro":{"en":"Evidently is a Latin seeing verb, filtered through French, wearing an adjective ending and an adverb ending.","cn":"这个词是一个经法语过滤的拉丁「看见」动词，套着形容词词尾与副词词尾。"},"latinIntro":{"en":"Latin supplies videre and evidens, and the noun evidentia passed through Old French into English.","cn":"拉丁语提供了 videre 与 evidens；名词 evidentia 经古法语进入英语。"},"items":[{"word":"videre","structure":"Latin verb","meaning":"to see","meaningCN":"看见","example":"The verb is the seeing half of the word.","exampleCN":"这个动词是词里「看见」的那一半。"},{"word":"ex-","structure":"Latin prefix","meaning":"out, out of","meaningCN":"向外；出","example":"It turns seeing into being seen out in the open.","exampleCN":"它把「看见」变成「当众被看见」。"},{"word":"evidens","structure":"Latin participle","meaning":"able to be seen, clear","meaningCN":"看得出来的；明显的","example":"The participle names what the eye can settle.","exampleCN":"这个分词指眼睛能够确认的东西。"},{"word":"evidentia","structure":"Latin noun","meaning":"clearness, distinctness","meaningCN":"清楚；分明","example":"The noun names the quality, not the thing.","exampleCN":"这个名词指的是性质，而不是事物。"},{"word":"evident","structure":"English adjective","meaning":"plain to see or understand","meaningCN":"明显的","example":"English keeps the adjective close to the Latin sense.","exampleCN":"英语让这个形容词紧贴拉丁义。"},{"word":"evidence","structure":"English noun","meaning":"material that shows something to be true","meaningCN":"证据","example":"The noun shifts from clearness to the thing that makes a fact clear.","exampleCN":"这个名词从「清楚」转向「使事实清楚的东西」。"},{"word":"-ial","structure":"Latin adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It forms evidential, the adjective of evidence.","exampleCN":"它构成 evidential，即证据的形容词。"},{"word":"-ary","structure":"Latin adjective ending","meaning":"serving for","meaningCN":"用于……的","example":"It forms evidentiary in legal usage.","exampleCN":"它在法律用语中构成 evidentiary。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It forms the adverb of inference.","exampleCN":"它构成表示推断的副词。"}],"latinEntries":[{"word":"videre","structure":"Latin verb","meaning":"to see","meaningCN":"看见"},{"word":"evidens","structure":"Latin participle","meaning":"able to be seen, clear","meaningCN":"看得出来的；明显的"},{"word":"evidentia","structure":"Latin noun","meaning":"clearness, distinctness","meaningCN":"清楚；分明"},{"word":"ex-","structure":"Latin prefix","meaning":"out, out of","meaningCN":"向外；出"},{"word":"evidenter","structure":"Latin adverb","meaning":"clearly, plainly","meaningCN":"清楚地；明显地"}],"derivatives":[{"word":"evident","pos":"adj.","zh":"由拉丁分词加形容词词尾构成，义为「明显的」"},{"word":"evidence","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「证据」"},{"word":"evidential","pos":"adj.","zh":"由证据名词加「与……有关」的形容词词尾构成，义为「证据的」"},{"word":"evidentiary","pos":"adj.","zh":"由证据名词加「用于……」的形容词词尾构成，义为「证据性的」"},{"word":"self-evident","pos":"adj.","zh":"由自身代词与「明显的」形容词复合而成，义为「不言而喻的」"}]}},{"word":"hence","ipa_uk":"/hens/","ipa_us":"/hens/","definition_zh":"因此；所以；由此；从此；从这儿","definition_en":"used in formal writing to introduce a conclusion that follows closely from what has just been said, often before a noun phrase or a short clause","core_image":"一条推理链的最后一节被扣上，前后两段严丝合缝地咬住，中间没有空隙","scene":"图纸上的两个尺寸都算完之后，工程师在结论栏里只写了一个词，就把前后两步扣在一起。The alloy expands less than steel and hence cracks less often in cold weather.","sceneCN":"这里指由前述事实直接推出结果（第 1 个义项：正式推论，接完整小句）；句意为这种合金比钢膨胀得少，因此天冷时更不容易开裂。场景要点：算完的两个尺寸、只写一个词的结论栏、被扣在一起的两步。","pos":[{"tag":"adv.","zh":"因此；所以；由此；从此"}],"collocations":[{"phrase":"hence the name","zh":"因此得名"},{"phrase":"hence the need for","zh":"因此需要"},{"phrase":"hence the delay","zh":"因此有了延误"},{"phrase":"hence it follows that","zh":"由此可知"},{"phrase":"two years hence","zh":"两年之后"},{"phrase":"hence the importance of","zh":"因此……的重要性"}],"forms":[{"label":"无词形变化（副词）","form":"hence"}],"derivatives":[{"word":"henceforth","pos":"adv.","zh":"由这个词与中古英语中表示「向前」的副词复合而成，义为「从今以后」"},{"word":"henceforward","pos":"adv.","zh":"由这个词与表示「向前」的副词成分复合而成，义为「从今以后」"},{"word":"whence","pos":"adv.","zh":"与这个词同属古英语方位副词系统，由疑问词干加同一副词尾构成，义为「从何处」"},{"word":"thence","pos":"adv.","zh":"与这个词同属古英语方位副词系统，由远指词干加同一副词尾构成，义为「从那里」"}],"senses":[{"no":"01","title":"Therefore, before a full clause","titleCN":"因此，接完整小句","definition":"in formal prose, introduces a clause that states the consequence of what has just been said","definitionCN":"在正式文章里引出一个小句，说明刚才那句话带来的结果","example":"The road was closed, and hence the delivery arrived late.","exampleCN":"道路封闭，因此送货晚了。","why":"Hence began as a pointer meaning from here; a conclusion follows from its premises the way a road follows from a point.","whyCN":"这个词原是一个指向「从此处」的词；结论从前提里跟出来，正如道路从某一点延伸出去。"},{"no":"02","title":"Hence before a noun phrase","titleCN":"因此有了，直接接名词短语","definition":"placed directly before a noun or noun phrase, it names the thing that results, with no verb at all","definitionCN":"直接放在名词或名词短语之前，点出由此产生的东西，完全不用动词","example":"The material is lighter and cheaper, hence its popularity in aircraft.","exampleCN":"这种材料更轻也更便宜，因此它在飞机制造中很受欢迎。","why":"Compression is the point: the conclusion is packed into a phrase instead of a clause.","whyCN":"要点在压缩：结论被塞进一个短语，而不是一个小句。"},{"no":"03","title":"From this time on","titleCN":"此后；今后","definition":"in dating and formal prose, means from this time onward, often after a stated interval","definitionCN":"在计时与正式文章中表示从此时往后，常用于说明一段间隔之后","example":"The agreement expires two years hence.","exampleCN":"这份协议两年之后到期。","why":"The old adverb pointed from here in space, and the same gesture was later extended to time.","whyCN":"这个古老的副词本指空间上的「从此处」，后来同一个手势被延伸到了时间上。"},{"no":"04","title":"From this place","titleCN":"从此处；离开这里","definition":"the old locative sense, now literary or archaic: away from this place","definitionCN":"古老的方位义，今多见于文学作品或古旧语体：离开这个地方","example":"He was told to go hence and never return.","exampleCN":"他被勒令离开此地，再也不许回来。","why":"The word began as a pointer to a place, and this sense survives in older literature.","whyCN":"这个词最初是一个指向地点的词，这一义项留在较早的文学作品里。"},{"no":"05","title":"In a mathematical proof","titleCN":"数学证明中的因此","definition":"in proofs and derivations, marks a step that follows necessarily from the line just written","definitionCN":"在证明与推导中，标出由上一行必然推出的一步","example":"Both angles are right angles, and hence the two lines are parallel.","exampleCN":"两个角都是直角，因此这两条线平行。","why":"A proof is a chain of necessary steps, and the word is the sound of a link closing.","whyCN":"证明是一串必然的步骤，这个词就是链环扣合时的那一声。"},{"no":"06","title":"Sentence-initial signpost","titleCN":"句首正式路标","definition":"at the head of a sentence in formal argument, announces the conclusion before its clause","definitionCN":"在正式论证中置于句首，先宣告结论，再让后面的小句把话说完","example":"Hence we may conclude that the hypothesis was correct.","exampleCN":"因此我们可以断定，那个假设是正确的。","why":"Formal argument puts the signpost first so that the reader knows a conclusion is coming.","whyCN":"正式论证把路标放在最前，好让读者知道结论就要来了。"},{"no":"07","title":"The formulaic hence it follows that","titleCN":"由此可知，固定句式","definition":"in the fixed formula hence it follows that, introduces a formal deduction","definitionCN":"在「由此可知」这一固定句式中，引出一段正式的演绎","example":"Hence it follows that no two such numbers can be equal.","exampleCN":"由此可知，这样的两个数不可能相等。","why":"The formula is a set piece of argument, inherited from logic and mathematics.","whyCN":"这个句式是论证里的现成部件，承自逻辑学与数学。"},{"no":"08","title":"Not the same as therefore","titleCN":"与「因此」的分界","definition":"the boundary sense: hence is tighter and more formal, and can stand before a noun phrase, while therefore is the ordinary full signpost before a clause","definitionCN":"分界义：这个词更紧、更正式，还能直接接名词短语；而「因此」那个词是普通而完整的路标，后面接小句","example":"One writes hence the name, never therefore the name.","exampleCN":"人们会写「因此得名」，却不会用另一个词去接「得名」。","why":"The two words share the inference but not the reach.","whyCN":"两个词共享「推论」这件事，但能管的范围并不一样。"},{"no":"09","title":"Not the same as thus","titleCN":"与「如此、以这种方式」的分界","definition":"the boundary sense: thus can also mean in this way, while hence always points from a reason to its consequence","definitionCN":"分界义：「如此」那个词还能表示「以这种方式」，而这个词始终是从理由指向结果","example":"Thus the parts were joined; hence the joint held.","exampleCN":"零件就是这样接合的；因此接头才吃得住力。","why":"The manner sense belongs to the other word, and this one never had it.","whyCN":"「方式」那一义属于另一个词，这个词从来没有那一层。"}],"etymology":{"intro":{"en":"Hence is a native English adverb, from Old English heonan, meaning from here. Its deeper Germanic and Indo-European roots are reconstructed forms rather than recorded words, so the ultimate origin is uncertain; the first date of the modern inferential use is approximate.","cn":"hence 是英语本族副词，来自古英语 heonan「从此处」。它更早的日耳曼语与原始印欧语词根都是重构形式，并非有记录的词，因此最终来源不确定；现代推论用法首见年代为约数。"},"items":[{"era":"OLD ENGLISH HEONAN","en":"The adverb meant from here, and it belonged to a set of place words that pointed away from the speaker.","cn":"这个副词意为「从此处」，属于一组从说话人所在之处向外指的地点词。"},{"era":"PROTO-GERMANIC HIN-","en":"The stem behind the word is reconstructed as a demonstrative element meaning this; it is not attested as a free word.","cn":"这个词背后的词干被重构为表示「此」的指示成分；它并没有作为独立词被记录下来。"},{"era":"PROTO-INDO-EUROPEAN KI-","en":"The deeper deictic stem is also a reconstruction, so the family's earliest history remains uncertain.","cn":"更深一层的指示词根同样是重构形式，因此这个词族最早的历史仍不确定。"},{"era":"MIDDLE ENGLISH HENCE","en":"The final consonant took the shape seen in thence and whence, a parallel set of place adverbs; the dating of that change is uncertain.","cn":"词尾辅音变得与 thence、whence 一致，形成一组平行的地点副词；这一变化的确切年代不确定。"},{"era":"EARLY MODERN ENGLISH","en":"The word extended from place to time, giving from now on, and from time to consequence, giving therefore.","cn":"这个词从地点延伸到时间，产生「从今以后」，再由时间延伸到结果，产生「因此」。"},{"era":"MODERN FORMAL PROSE","en":"In present-day writing it is a tight, formal link, often followed by a bare noun phrase.","cn":"在当代书面语里，它是一个紧凑而正式的衔接，后面常直接跟一个名词短语。"}]},"similar":{"note":{"en":"The first group shares the old place-adverb system, with one unrelated look-alike; the second holds the inferential connectors it is measured against.","cn":"第一组共享古老的方位副词系统，另有一个无关的形近词；第二组是拿来与它比较的推论连接词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"henceforth","ipa":"/ˈhensfɔːθ/","tag":"same root","definition":"From this time on, in formal or legal writing.","definitionCN":"指从今以后，多用于正式或法律文本。"},{"word":"henceforward","ipa":"/ˈhensˈfɔːwəd/","tag":"same root","definition":"From this time forward; a rarer variant of henceforth.","definitionCN":"指从今往后，是前一个词的较罕见变体。"},{"word":"whence","ipa":"/wens/","tag":"parallel formation","definition":"From where; the interrogative member of the same old set.","definitionCN":"指从何处，是同一古老词族中的疑问成员。"},{"word":"thence","ipa":"/ðens/","tag":"parallel formation","definition":"From there; the far demonstrative member of the set.","definitionCN":"指从那里，是同一组词中的远指成员。"},{"word":"fence","ipa":"/fens/","tag":"different root","definition":"A barrier or to enclose land; it comes from defence, from Latin defensus, and shares nothing with hence beyond sound.","definitionCN":"指栅栏或圈起土地，来自拉丁语中意为「防卫」的词，除了读音相近以外毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"therefore","ipa":"/ˈðeəfɔː/","tag":"near meaning","definition":"The ordinary formal signpost before a full clause, looser and more general than hence.","definitionCN":"普通而正式的路标，后接完整小句，比这个词更宽泛。"},{"word":"thus","ipa":"/ðʌs/","tag":"near meaning","definition":"Marks a conclusion, and can also mean in this way.","definitionCN":"标记结论，同时还能表示「以这种方式」。"},{"word":"accordingly","ipa":"/əˈkɔːdɪŋli/","tag":"near meaning","definition":"Marks a conclusion drawn and then acted upon.","definitionCN":"标记由前述情况得出的结论，并含据此办理之意。"},{"word":"consequently","ipa":"/ˈkɒnsɪkwəntli/","tag":"near meaning","definition":"Reports a consequence as an observed fact, usually before a full clause.","definitionCN":"把后果作为观察到的事实来报告，通常后接完整小句。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Old English place pointer, the three -nce adverbs, and the real formula hence the name.","cn":"正常联想使用古英语的地点指向、三个同尾副词，以及「因此得名」这一真实说法。"},"normal":[{"en":"Old English heonan meant from here; hence is a finger pointing away from this point.","cn":"古英语里它意为「从此处」；这个词就是一根从这一点向外指的手指。"},{"en":"Hence, whence and thence are three pointers: from here, from where, from there.","cn":"「从此处」「从何处」「从那里」是三个指向：这里、哪里、那里。"},{"en":"Hence the name is the word at its most compressed: a reason and its result in three words.","cn":"「因此得名」是这个词最紧的形态：理由与结果，三个词说完。"},{"en":"In a proof it is the click of a step closing.","cn":"在证明里，它就是一步扣合时的那一声轻响。"},{"en":"Two years hence turns a pointer in space into a mark on a clock.","cn":"「两年之后」把一个空间里的指向，变成了钟面上的一个刻度。"}],"abstract":[{"en":"A reason and its consequence are two ends of one line, and the word is the line.","cn":"理由与结果是同一条线的两端，这个词就是那条线。"},{"en":"The shorter the signpost, the tighter the argument it claims.","cn":"路标越短，它所主张的论证就越紧。"},{"en":"Space becomes time in this word, and both are measured from here.","cn":"在这个词里空间变成了时间，而两者都从「此处」量起。"}]},"examples":[{"en":"The soil is thin and hence poor at holding water.","cn":"这里的土层薄，因此保水能力差。"},{"en":"Hence the need for a second inspection before the sale.","cn":"因此，出售之前需要再做一次检查。"},{"en":"The custom died out, and hence the word survives only in old books.","cn":"这一习俗消失了，因此这个词只保存在旧书里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「很斯」——理由很斯文地一扣，结论就跟着出来了：因此","word":"hence"},"root":"古英语 heonan「从此处」→ 中古英语 hence（词尾与 thence、whence 趋同）→ 近代英语由空间义引申出时间义与推论义。属英语本族词；更早日耳曼语与原始印欧语词根均为重构形式，最终来源不确定。","sensesIntro":{"en":"Nine senses differ by what follows the word and which axis it points along: a clause, a noun phrase, a point in time, a place, a proof step, the sentence-initial signpost, the fixed formula, and the boundaries against therefore and thus.","cn":"九个义项按「后面接什么」与「指向哪条轴」分开：接小句、接名词短语、指向时间、指向地点、证明步骤、句首路标、固定句式，以及与「因此」「如此」的分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: the last link of a reasoning chain snapping shut, with no gap left between the two halves.","cn":"核心意象：推理链的最后一环扣上，两端之间不留一点缝。"},"chain":["HERE","FROM THIS POINT","A REASON GIVEN","THE LINK TIGHTENS","THE CONSEQUENCE","A CONCLUSION"],"branches":[{"senses":"01 · 06","en":"THE CLAUSE AND THE SIGNPOST: the same inference, inside a sentence or at its head.","cn":"小句与路标：同一种推论，或放在句中，或放在句首。"},{"senses":"02 · 07","en":"THE COMPRESSED FORMS: a bare noun phrase, and the fixed formula of formal deduction.","cn":"压缩形态：直接跟名词短语，以及正式演绎的固定句式。"},{"senses":"03 · 04","en":"THE OLD POINTER: from this time on, and from this place.","cn":"古老的指向：此后，以及从此处。"},{"senses":"05","en":"THE PROOF STEP: a link that must close because the line above demands it.","cn":"证明的一步：因为上一行要求，这个链环必须扣上。"},{"senses":"08 · 09","en":"THE TWO BOUNDARIES: the line against therefore, and the line against thus.","cn":"两处分界：与「因此」的界线，与「如此」的界线。"}]},"affixes":{"intro":{"en":"Hence is a native English word, not a Latin borrowing; its endings belong to the old Germanic system of place adverbs.","cn":"这个词是英语本族词，不是拉丁语借词；它的词尾属于古老的日耳曼语方位副词系统。"},"latinIntro":{"en":"There is no Latin source here: hence is a native English word from Old English heonan, and its earlier Germanic and Indo-European roots are reconstructed forms rather than recorded words.","cn":"这个词没有拉丁来源：它是英语本族词，来自古英语 heonan，更早的日耳曼语与原始印欧语词根都是重构形式，并非有记录的词。"},"items":[{"word":"heonan","structure":"Old English adverb","meaning":"from here","meaningCN":"从此处","example":"The word begins as a pointer to the speaker's place.","exampleCN":"这个词最初是从说话人所在之处向外指。"},{"word":"-nce","structure":"Old English adverbial ending","meaning":"from a place","meaningCN":"从某处","example":"The same ending appears in whence and thence.","exampleCN":"同一个词尾也出现在 whence 与 thence 里。"},{"word":"hence","structure":"English adverb","meaning":"from here; therefore","meaningCN":"从此处；因此","example":"Space, time and inference meet in one short word.","exampleCN":"空间、时间与推论在一个短词里相遇。"},{"word":"henceforth","structure":"English adverb","meaning":"from this time on","meaningCN":"从今以后","example":"Forth adds the forward direction in time.","exampleCN":"forth 补上了时间上向前的方向。"},{"word":"henceforward","structure":"English adverb","meaning":"from this time forward","meaningCN":"从今往后","example":"Forward gives a fuller, rarer variant.","exampleCN":"forward 造出一个更完整也更罕见的变体。"},{"word":"whence","structure":"English adverb","meaning":"from where","meaningCN":"从何处","example":"The interrogative member of the same set.","exampleCN":"同一组词里的疑问成员。"},{"word":"thence","structure":"English adverb","meaning":"from there","meaningCN":"从那里","example":"The far demonstrative member of the same set.","exampleCN":"同一组词里的远指成员。"},{"word":"hin-","structure":"reconstructed Proto-Germanic stem","meaning":"this","meaningCN":"此","example":"The stem is reconstructed, not attested as a free word.","exampleCN":"这个词干是重构的，并未作为独立词被记录。"},{"word":"*ki-","structure":"reconstructed Proto-Indo-European stem","meaning":"this, here","meaningCN":"此；此处","example":"The deepest root is also a reconstruction, so the origin stays uncertain.","exampleCN":"最深的词根同样是重构形式，因此来源仍不确定。"}],"latinEntries":[],"derivatives":[{"word":"henceforth","pos":"adv.","zh":"由 hence 与 forth 复合而成，义为「从今以后」"},{"word":"henceforward","pos":"adv.","zh":"由 hence 与 forward 复合而成，义为「从今以后」"},{"word":"whence","pos":"adv.","zh":"与 hence 同属古英语方位副词系统，由疑问词干加同一副词尾构成，义为「从何处」"},{"word":"thence","pos":"adv.","zh":"与 hence 同属古英语方位副词系统，由远指词干加同一副词尾构成，义为「从那里」"}]}},{"word":"hypothetically","ipa_uk":"/ˌhaɪpəˈθetɪkli/","ipa_us":"/ˌhaɪpəˈθetɪkli/","definition_zh":"假设地；假定地；从假设上说；在假定情形下","definition_en":"used to say that something is being considered as an assumed possibility or imagined case, not as an established fact","core_image":"白板上画着一个标着「情形甲」的方框，里面的数字都是临时填进去的","scene":"会议开始前，主持人在白板上画出一个方框，说明框里的条件只是临时填进去的。Hypothetically, a city of that size could survive on stored water for a month.","sceneCN":"这里指把某个情形当作假定前提来推想（第 1 个义项：假定情形）；句意为假定有那样规模的一座城市，靠储备水也许能撑一个月。场景要点：白板上的方框、临时填入的条件、被推想的结果。","pos":[{"tag":"adv.","zh":"假设地；假定地；从假设上说"}],"collocations":[{"phrase":"hypothetically speaking","zh":"假设地说"},{"phrase":"purely hypothetically","zh":"纯粹假设地"},{"phrase":"hypothetically possible","zh":"假设上可能"},{"phrase":"hypothetically, if","zh":"假设如果"},{"phrase":"hypothetically assume","zh":"假定"},{"phrase":"consider hypothetically","zh":"作假设性考虑"}],"forms":[{"label":"无词形变化（副词）","form":"hypothetically"}],"derivatives":[{"word":"hypothesis","pos":"n.","zh":"由希腊语「下置、前提」直接借入，义为「假设、假说」"},{"word":"hypothetical","pos":"adj.","zh":"由假设名词加表示「属于……的」形容词词尾构成，义为「假设的」"},{"word":"hypothesize","pos":"v.","zh":"由假设名词加动词词尾构成，义为「提出假设」"},{"word":"hypothetico-deductive","pos":"adj.","zh":"由假设形容词与演绎形容词复合而成，义为「假说—演绎的」"}],"senses":[{"no":"01","title":"An assumed premise","titleCN":"假定前提","definition":"sets up a condition that is accepted for the sake of the discussion, whether or not it is true","definitionCN":"设立一个为了讨论而接受的条件，无论它是否为真","example":"Hypothetically, a city of that size could survive on stored water for a month.","exampleCN":"假定有那样规模的一座城市，靠储备水也许能撑一个月。","why":"The Greek noun is a placing under, a floor laid beneath an argument; the adverb offers that floor.","whyCN":"希腊语名词意为「放在下面」，即铺在论证底下的一层地板；这个副词提供的就是那层地板。"},{"no":"02","title":"The conversational what if","titleCN":"口语里的「假如」","definition":"in speech, invites the listener to imagine a case that may never arise","definitionCN":"在口语中请听者想象一个也许永远不会出现的情形","example":"Hypothetically, what would you do if the offer came tomorrow?","exampleCN":"假设明天这个录用通知来了，你会怎么做？","why":"Speech uses the word as a door into an imagined room, and either side may walk back out.","whyCN":"口语把这个词当作进入想象房间的一扇门，双方都可以随时退出来。"},{"no":"03","title":"A case constructed for argument","titleCN":"为论证构造的假定案情","definition":"in law, logic and debate, introduces a constructed case used to test a rule","definitionCN":"在法律、逻辑与辩论中，引出一个用来检验规则而构造出来的案情","example":"Hypothetically, a tenant who pays no rent for a year may still keep the lease.","exampleCN":"假设一个房客一年不交租金，他仍可能保住租约。","why":"A rule is tested by inventing a case that presses on its edges.","whyCN":"规则的边界是靠虚构一个压在上面的案情来检验的。"},{"no":"04","title":"Merely supposed, not actual","titleCN":"只是假定，并非事实","definition":"marks that what follows is not being claimed to exist or to have happened","definitionCN":"标明所说之事并未被声称为存在或已经发生","example":"The company is hypothetically liable, though no claim has been filed.","exampleCN":"这家公司在假设上负有责任，尽管还没有人提出索赔。","why":"The adjective carries a shadow sense: the thing is only on paper.","whyCN":"这个形容词带着一层阴影义：那件事只在纸面上。"},{"no":"05","title":"Sentence-initial framing","titleCN":"句首设定","definition":"placed first to announce that the sentence is a thought experiment rather than a report","definitionCN":"置于句首，宣告这句话是一场思想试验，而不是一则报告","example":"Hypothetically, the two effects could cancel each other out.","exampleCN":"假设如此，两种效应可能会相互抵消。","why":"A first word tells the reader which kind of sentence this is before the content arrives.","whyCN":"开头的一个词在内容到达之前，先告诉读者这是哪一种句子。"},{"no":"06","title":"The fixed phrase hypothetically speaking","titleCN":"固定插入语「假设地说」","definition":"in the phrase hypothetically speaking, softens a statement that might otherwise sound like a prediction","definitionCN":"在「假设地说」这一固定插入语里，弱化一句本来会被听成预测的话","example":"Hypothetically speaking, the plan could fail within a year.","exampleCN":"假设地说，这项计划可能在一年之内失败。","why":"The phrase marks the frame explicitly, so that the statement inside is not taken as a forecast.","whyCN":"这个短语把框架明明白白标出来，里面的说法就不会被当成预报。"},{"no":"07","title":"A scenario in a model or experiment","titleCN":"模型与实验中的假设情形","definition":"used in science and engineering when a model is run under assumed conditions","definitionCN":"在科学与工程中，当一个模型在假定条件下运行时使用","example":"The model was run hypothetically, with rainfall held constant for a decade.","exampleCN":"这个模型是在假设条件下运行的，把降雨量固定了十年。","why":"A model needs conditions that are set rather than observed, and the word names that setting.","whyCN":"模型需要的是被设定的条件，而不是被观察到的条件，这个词命名的正是这种设定。"},{"no":"08","title":"Not the same as theoretically","titleCN":"与「理论上」的分界","definition":"the boundary sense: hypothetically sets an assumed case, which need not rest on any theory, while theoretically appeals to principles or to what a theory predicts","definitionCN":"分界义：这个词只设定一个假定情形，未必依据任何理论；而「理论上」要诉诸原理或理论所预测的结果","example":"Hypothetically, we may assume free entry; theoretically, free entry should drive prices down.","exampleCN":"假设上我们可以假定自由进入；理论上，自由进入应当压低价格。","why":"An assumption needs no theory; a theory makes predictions.","whyCN":"假设不需要理论，而理论会作出预测。"},{"no":"09","title":"The elliptical hypothetically, yes","titleCN":"简答：假定上可以","definition":"in short replies, grants that something would be true under the assumed case, without endorsing it as fact","definitionCN":"在简短回答里承认某事在假定情形下成立，并不把它当作事实来认可","example":"Could the scheme work? Hypothetically, yes.","exampleCN":"这个方案能行吗？假设上可以。","why":"The reply keeps the frame alive by repeating the word instead of dropping it.","whyCN":"这种回答把框架保留下来，靠重复这个词而不是把它丢掉。"}],"etymology":{"intro":{"en":"Hypothetically is hypothetical plus -ly. The family goes back to Greek hypothesis, a placing under, from hypo- under and thesis a placing, from tithenai to place. Latin took the adjective hypotheticus, and English built the rest on that stem.","cn":"hypothetically 是 hypothetical 加 -ly。这个词族可追到希腊语 hypothesis「放在下面」，由 hypo-「在下」与 thesis「放置」构成，动词为 tithenai「放置」。拉丁语接收了形容词 hypotheticus，英语再在这个词干上造出其余形式。"},"items":[{"era":"GREEK TITHENAI","en":"The verb meant to place or set down, and it stands behind thesis and hypothesis alike.","cn":"这个动词意为放置、放下，thesis 与 hypothesis 都由它而来。"},{"era":"GREEK THESIS","en":"The noun named a placing, and later a proposition that is put forward.","cn":"这个名词指放置，后来指被提出来的命题。"},{"era":"GREEK HYPOTHESIS","en":"Hypo- under plus thesis placing made a foundation laid beneath an argument.","cn":"hypo-「在下」加 thesis「放置」，构成铺在论证底下的基础。"},{"era":"LATIN HYPOTHETICUS","en":"Latin borrowed the adjective and kept the Greek sense of what is assumed.","cn":"拉丁语借入这个形容词，保留了希腊语「被假定」的含义。"},{"era":"ENGLISH HYPOTHETICAL","en":"English formed the adjective on the Latin stem; the date of its first use is only approximate.","cn":"英语在拉丁词干上构成这个形容词；其首次使用年代仅为约数。"},{"era":"HYPOTHETICALLY","en":"The adverb added -ly to mark a statement made inside an assumed case; the exact date is uncertain.","cn":"副词再加 -ly，用来标记在假定情形之内说出的话；确切年代不确定。"}]},"similar":{"note":{"en":"The first group shares the placing-under stem; the second holds the theoretical and tentative words it is compared with.","cn":"第一组共享「放在下面」的词干；第二组是拿来与它比较的理论性与试探性说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hypothesis","ipa":"/haɪˈpɒθəsɪs/","tag":"same root","definition":"A proposed explanation that is still to be tested.","definitionCN":"指尚待检验的解释或假说。"},{"word":"hypothetical","ipa":"/haɪˈpɒθətɪkl/","tag":"same root","definition":"Based on an assumption rather than on fact.","definitionCN":"指基于假定而非事实的。"},{"word":"hypothesize","ipa":"/haɪˈpɒθəsaɪz/","tag":"same root","definition":"To put forward a hypothesis as a possible explanation.","definitionCN":"指提出一个假说作为可能的解释。"},{"word":"hypothetico-deductive","ipa":"/haɪˌpɒθətɪkəʊ dɪˈdʌktɪv/","tag":"same root","definition":"A method that derives testable predictions from a hypothesis.","definitionCN":"指从假说推出可检验预测的方法。"},{"word":"hypocritically","ipa":"/ˌhɪpəˈkrɪtɪkli/","tag":"different root","definition":"From Greek hypo- plus krinein, to sift; it means insincerely, and its root is krinein rather than tithenai.","definitionCN":"来自希腊语中表示「在下」与「筛分」的两个成分，意为虚伪地；其词根与「放置」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theoretically","ipa":"/θiəˈretɪkli/","tag":"near meaning","definition":"According to theory or to what a model predicts, whether or not it happens in practice.","definitionCN":"指依理论或模型所预测的而言，无论实践中是否如此。"},{"word":"in theory","ipa":"/ɪn ˈθɪəri/","tag":"near meaning","definition":"As an ideal principle, as opposed to actual practice.","definitionCN":"指作为理想原则而言，与实际做法相对。"},{"word":"supposedly","ipa":"/səˈpəʊzɪdli/","tag":"near meaning","definition":"According to what is said or believed, often with doubt implied.","definitionCN":"指据所说或据所信，常暗示怀疑。"},{"word":"conceivably","ipa":"/kənˈsiːvəbli/","tag":"near meaning","definition":"As can be imagined as possible, with no assumption set up for a discussion.","definitionCN":"指可以想象为可能，并未为讨论设立任何假定。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek floor laid under an argument, the hypothesis family, and the whiteboard frame.","cn":"正常联想使用希腊语里铺在论证底下的那层地板、假设词族，以及白板上的方框。"},"normal":[{"en":"Hypo is under and thesis is placing: a hypothesis is a floor laid under an argument.","cn":"「在下」是在下，「放置」是放置：一个假设就是铺在论证底下的一层地板。"},{"en":"Hypothesis, hypothetical, hypothesize and hypothetically are one family, one root, four jobs.","cn":"假设、假设的、提出假设与假设地：一个词族，一个词根，四份差事。"},{"en":"A whiteboard box is the word's natural habitat: conditions inside, reality outside.","cn":"白板上的方框是这个词的天然栖息地：条件在框里，现实在框外。"},{"en":"Hypothetically speaking is the polite way to ask what if without promising anything.","cn":"「假设地说」是礼貌地问「假如」、却什么也不承诺的方式。"},{"en":"The word never claims the case exists; it only asks what would follow.","cn":"这个词从不声称情形真的存在，它只问「那会引出什么」。"}],"abstract":[{"en":"An assumption is a borrowed floor on which an argument may stand.","cn":"假定是一层借来的地板，论证可以站在上面。"},{"en":"The word builds a room and leaves the door open to reality.","cn":"这个词搭起一个房间，却把门留给现实。"},{"en":"What is only supposed can be powerful and still be false.","cn":"只是被假定的东西，可以很有力，也仍然是假的。"}]},"examples":[{"en":"Hypothetically, a smaller dose might produce the same effect.","cn":"假设如此，较小的剂量也许能产生同样的效果。"},{"en":"Hypothetically speaking, the two policies could be combined.","cn":"假设地说，这两项政策是可以合并的。"},{"en":"The engineers tested the design hypothetically before building a prototype.","cn":"工程师在造出样机之前，先在假设条件下检验了这个设计。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「海波塞提克理」——先在海面上放一个假设的盒子，再看里面会怎样：假设地","word":"hypothetically"},"root":"希腊语 tithenai「放置」→ thesis「放置、命题」→ hypo-（在下）+ thesis 构成 hypothesis「放在下面的前提」→ 拉丁语 hypotheticus → 英语 hypothetical，再加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses differ by the frame being set up: an assumed premise, a spoken what if, a case built for argument, a merely supposed state, the sentence-initial frame, the fixed phrase, a model scenario, the boundary against theoretically, and the short reply.","cn":"九个义项按所设的框架分开：假定前提、口语的「假如」、为论证构造的案情、只是纸面上的假定、句首设定、固定插入语、模型情形、与「理论上」的分界，以及简短回答。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whiteboard box labelled CASE A, its figures filled in only for the discussion.","cn":"核心意象：白板上一个标着「情形甲」的方框，框里的数字只为这次讨论临时填上。"},"chain":["A PREMISE","LAID UNDER","A CASE BUILT","CONSEQUENCES TRACED","REALITY SUSPENDED","MERELY SUPPOSED"],"branches":[{"senses":"01 · 05","en":"THE ASSUMED PREMISE: a condition accepted, whether it stands at the head of the sentence or inside it.","cn":"假定前提：一个被接受的条件，无论它放在句首还是句中。"},{"senses":"02 · 09","en":"THE SPOKEN FRAME: an imagined case in conversation, and the short reply that keeps it alive.","cn":"口语框架：对话里想象的情形，以及让这个框架继续成立的简短回答。"},{"senses":"03 · 07","en":"THE CONSTRUCTED CASE: one built to test a rule, one run inside a model.","cn":"构造的案情：一个用来检验规则，一个在模型里运行。"},{"senses":"04 · 06","en":"THE MARKED SUPPOSITION: only on paper, and openly labelled by the fixed phrase.","cn":"标明了的假定：只在纸面上，并由固定插入语公开标出。"},{"senses":"08","en":"THE BOUNDARY: an assumption needs no theory, while a theory makes predictions.","cn":"分界：假设不需要理论，而理论会作出预测。"}]},"affixes":{"intro":{"en":"Hypothetically is a Greek noun of placing, filtered through Latin, wearing an English adjective ending and an adverb ending.","cn":"这个词是一个经拉丁语过滤的希腊「放置」名词，套着英语的形容词词尾与副词词尾。"},"latinIntro":{"en":"Greek supplies hypo-, thesis and tithenai; hypothesis entered Latin, and the adjective hypotheticus became the English stem.","cn":"希腊语提供了 hypo-、thesis 与 tithenai；hypothesis 进入拉丁语，形容词 hypotheticus 则成为英语的词干。"},"items":[{"word":"hypo-","structure":"Greek prefix","meaning":"under, beneath","meaningCN":"在下；在下面","example":"It places the premise beneath the argument.","exampleCN":"它把前提放在论证的下面。"},{"word":"thesis","structure":"Greek noun","meaning":"a placing, a proposition","meaningCN":"放置；命题","example":"The noun names what is set down.","exampleCN":"这个名词指被放下的东西。"},{"word":"tithenai","structure":"Greek verb","meaning":"to place, set down","meaningCN":"放置；放下","example":"The verb is the action behind the noun.","exampleCN":"这个动词是名词背后的动作。"},{"word":"hypothesis","structure":"Greek noun borrowed into Latin","meaning":"a premise laid under an argument","meaningCN":"放在论证下面的前提","example":"The word enters learned English through Latin.","exampleCN":"这个词经拉丁语进入学术英语。"},{"word":"hypotheticus","structure":"Latin adjective","meaning":"assumed, not proved","meaningCN":"假定的；未证明的","example":"Latin gives English the adjective stem.","exampleCN":"拉丁语给英语提供了形容词词干。"},{"word":"hypothetical","structure":"English adjective","meaning":"based on an assumption","meaningCN":"假设的","example":"English adds its own adjective ending to the stem.","exampleCN":"英语在词干上加了自身的形容词词尾。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or relating to","meaningCN":"属于……的","example":"It forms the adjective from the Greek noun.","exampleCN":"它由希腊名词构成形容词。"},{"word":"-ize","structure":"Greek verb ending through Latin","meaning":"to make or act","meaningCN":"使……；做……","example":"It forms hypothesize, to put forward a hypothesis.","exampleCN":"它构成 hypothesize，即提出假设。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It forms the adverb of assumed cases.","exampleCN":"它构成表示假定情形的副词。"}],"latinEntries":[{"word":"hypo-","structure":"Greek prefix","meaning":"under, beneath","meaningCN":"在下"},{"word":"thesis","structure":"Greek noun","meaning":"a placing, a proposition","meaningCN":"放置；命题"},{"word":"tithenai","structure":"Greek verb","meaning":"to place, set down","meaningCN":"放置"},{"word":"hypothesis","structure":"Greek noun borrowed into Latin","meaning":"a premise laid under an argument","meaningCN":"放在论证下面的前提"},{"word":"hypotheticus","structure":"Latin adjective","meaning":"assumed, not proved","meaningCN":"假定的"}],"derivatives":[{"word":"hypothesis","pos":"n.","zh":"由希腊语「下置、前提」经拉丁语借入，义为「假设」"},{"word":"hypothetical","pos":"adj.","zh":"由假设名词加「属于……的」形容词词尾构成，义为「假设的」"},{"word":"hypothesize","pos":"v.","zh":"由假设名词加动词词尾构成，义为「提出假设」"},{"word":"hypothetico-deductive","pos":"adj.","zh":"由假设形容词与演绎形容词复合而成，义为「假说—演绎的」"}]}},{"word":"ideally","ipa_uk":"/aɪˈdiːəli/","ipa_us":"/aɪˈdiːəli/","definition_zh":"理想上；最好；理想情况下；以最理想的方式","definition_en":"used to describe the best possible situation or outcome, or the standard one would wish to reach","core_image":"一张草图上先画出最完美的布局，再用铅笔在旁边标注现实能建的部分","scene":"设计师先在纸上画出最完美的布局，然后才考虑现实中的限制。Ideally, the new library would sit at the centre of the campus.","sceneCN":"这里指设想最理想的状态（第 1 个义项：最佳状态）；句意为最理想的情况是，新图书馆坐落在校园的中心。场景要点：纸上的完美布局、后来才考虑的限制、校园中心的位置。","pos":[{"tag":"adv.","zh":"理想上；最好；理想情况下"}],"collocations":[{"phrase":"ideally suited","zh":"非常适合"},{"phrase":"ideally placed","zh":"位置最理想"},{"phrase":"ideally positioned","zh":"处于最理想的位置"},{"phrase":"ideally, we would","zh":"最理想的是我们会"},{"phrase":"ideally speaking","zh":"理想地说"},{"phrase":"ideally, the process","zh":"最理想的是这一过程"}],"forms":[{"label":"无词形变化（副词）","form":"ideally"}],"derivatives":[{"word":"idea","pos":"n.","zh":"由希腊语「形象、所见」经拉丁与法语借入，义为「想法、观念」"},{"word":"ideal","pos":"adj.","zh":"由观念名词加形容词词尾构成，义为「理想的」"},{"word":"idealism","pos":"n.","zh":"由理想形容词加表示学说体系的名词尾构成，义为「理想主义」"},{"word":"idealist","pos":"n.","zh":"由理想形容词加表示人的名词尾构成，义为「理想主义者」"},{"word":"idealize","pos":"v.","zh":"由理想形容词加动词词尾构成，义为「把……理想化」"}],"senses":[{"no":"01","title":"The best possible state","titleCN":"最佳状态","definition":"describes conditions as they would be if nothing stood in the way","definitionCN":"描述在没有阻碍时会呈现的那种状况","example":"Ideally, the new library would sit at the centre of the campus.","exampleCN":"最理想的情况是，新图书馆坐落在校园的中心。","why":"Idea is an image in the mind, and the ideal is that image at its best.","whyCN":"「观念」是心里的一幅形象，而「理想的」就是那幅形象最好的样子。"},{"no":"02","title":"The goal one aims at","titleCN":"追求的理想目标","definition":"names the standard that a plan or effort is trying to reach, even if it falls short","definitionCN":"指出一项计划或努力试图达到的标准，即使最终达不到","example":"Ideally, every student would read the whole corpus before graduating.","exampleCN":"理想的目标是每位学生在毕业前读完整个语料库。","why":"A goal is an ideal seen from the side of effort rather than from the side of fact.","whyCN":"目标是从努力那一侧、而不是从事实那一侧看到的理想。"},{"no":"03","title":"Perfectly suited or placed","titleCN":"完美地、恰当地","definition":"modifies an adjective or participle to mean perfectly suited to a purpose","definitionCN":"修饰形容词或分词，表示完全适合某个用途","example":"The site is ideally placed for a station.","exampleCN":"这块地作为车站的位置再理想不过。","why":"This is the manner sense: in an ideal way, not merely as a wish.","whyCN":"这是方式义：以一种理想的方式，而不只是作为愿望。"},{"no":"04","title":"Sentence-initial planning frame","titleCN":"句首计划设想","definition":"placed first in a plan or proposal to set out the wished-for arrangement before the constraints","definitionCN":"在计划或提案中置于句首，先摆出所期望的安排，再谈限制","example":"Ideally, the work would be finished before the rainy season.","exampleCN":"最理想的是，这项工程能在雨季之前完工。","why":"A plan states its ideal first so that later compromises can be measured against it.","whyCN":"计划先把理想说出来，日后的让步才好拿它来量。"},{"no":"05","title":"The softened expectation with would","titleCN":"与虚拟式连用的委婉期望","definition":"with would or could, softens a request or expectation so that it sounds like a wish rather than a demand","definitionCN":"与虚拟式连用，把请求或期望放软，听起来像愿望而不是要求","example":"We would ideally like an answer by Friday.","exampleCN":"最理想的是，我们希望在周五之前得到答复。","why":"The conditional leaves the other side room to refuse without a quarrel.","whyCN":"条件式给对方留了拒绝的余地，不必吵起来。"},{"no":"06","title":"The opening position in a negotiation","titleCN":"谈判中的理想开价","definition":"in bargaining, marks the figure or terms one asks for first, knowing that the final result will be lower","definitionCN":"在议价中标记最先提出的数字或条件，明知最终结果会更低","example":"Ideally, we would pay nothing for the first year.","exampleCN":"理想的开价是，第一年我们一分钱也不付。","why":"An opening figure is an ideal, not a forecast, and both sides know it.","whyCN":"开价是理想，不是预报，这一点双方都明白。"},{"no":"07","title":"The elliptical ideally, yes","titleCN":"简答：理想上可以","definition":"in short replies, agrees that something is the best outcome while implying that it may not happen","definitionCN":"在简短回答里承认某事是最好的结果，同时暗示它未必会发生","example":"Could both sides sign this week? Ideally, yes.","exampleCN":"双方这周能签字吗？理想上可以。","why":"The short answer grants the wish without pretending that the wish is a fact.","whyCN":"简短回答认可了这个愿望，却不假装愿望已成事实。"},{"no":"08","title":"Not the same as preferably","titleCN":"与「最好、优先」的分界","definition":"the boundary sense: ideally names the best possible state, while preferably ranks one option above another","definitionCN":"分界义：这个词指出可能达到的最佳状态，而「优先」那个词只是把某个选项排在另一个之上","example":"Ideally the room is quiet; preferably it also has daylight.","exampleCN":"最理想的是房间安静；其次最好还有自然光。","why":"The best state is not the same as a preference among choices.","whyCN":"最佳状态与在若干选项里挑一个，并不是一回事。"},{"no":"09","title":"Not the same as in theory","titleCN":"与「理论上」的分界","definition":"the boundary sense: ideally describes a state worth reaching in practice, while in theory describes what principle says, whether or not it can be reached","definitionCN":"分界义：这个词描述一个在实践中值得达到的状态，而「理论上」描述原理怎么说，无论能否达到","example":"In theory the system works; ideally it would also be cheap.","exampleCN":"理论上这套系统行得通；最理想的是它还便宜。","why":"One is a goal, the other is a principle, and the difference is where each one lives.","whyCN":"一个是目标，一个是原理，差别在于它们各自住在哪里。"}],"etymology":{"intro":{"en":"Ideally is ideal plus -ly. Ideal comes through French idéal from Latin idealis, from Greek idea, a form or appearance, from idein, to see. The adverb marks the way things would be at their best.","cn":"ideally 是 ideal 加 -ly。ideal 经法语 idéal 来自拉丁语 idealis，再上溯希腊语 idea「形相、外观」，动词为 idein「看见」。这个副词标记事物处于最好状态时的样子。"},"items":[{"era":"GREEK IDEIN","en":"The verb meant to see, and it stands behind idea and the whole family of ideal words.","cn":"这个动词意为「看见」，idea 与整个「理想」词族都由它而来。"},{"era":"GREEK IDEA","en":"The noun named a form or appearance, and later an image in the mind.","cn":"这个名词指形相或外观，后来指心里的形象。"},{"era":"LATIN IDEA","en":"Latin borrowed the noun and used it for a mental pattern or conception.","cn":"拉丁语借入这个名词，用它指心中的模式或概念。"},{"era":"FRENCH IDEAL","en":"French formed the adjective for what exists only as a pattern to be reached.","cn":"法语构成这个形容词，指只作为待达到的模式而存在的东西。"},{"era":"ENGLISH IDEAL","en":"English took the adjective and later the noun; the first dates are only approximate.","cn":"英语接收了这个形容词，后来又接收其名词用法；首次年代仅为约数。"},{"era":"IDEALLY","en":"The adverb was formed with -ly to set out the best case; the exact date of its first use is uncertain.","cn":"副词由 -ly 构成，用来摆出最好的情形；其首次使用的确切年代不确定。"}]},"similar":{"note":{"en":"The first group shares the seeing-and-image stem; the second holds the preference and principle words it is compared with.","cn":"第一组共享「看见与形象」的词干；第二组是拿来与它比较的偏好与原理说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"idea","ipa":"/aɪˈdɪə/","tag":"same root","definition":"A thought, plan or conception in the mind.","definitionCN":"指心里的想法、计划或概念。"},{"word":"ideal","ipa":"/aɪˈdiːl/","tag":"same root","definition":"The best possible model of something, or existing only as such a model.","definitionCN":"指某事最好的典范，或只作为这种典范而存在的。"},{"word":"idealism","ipa":"/aɪˈdiːəlɪzəm/","tag":"same root","definition":"The belief that ideals can guide reality, or a philosophical position about mind.","definitionCN":"指相信理想能引导现实的立场，或关于心灵的哲学主张。"},{"word":"idealist","ipa":"/aɪˈdiːəlɪst/","tag":"same root","definition":"A person who holds to ideals, sometimes with the implication of impracticality.","definitionCN":"指坚持理想的人，有时暗含不切实际之意。"},{"word":"idly","ipa":"/ˈaɪdli/","tag":"different root","definition":"From Old English idle, empty or unused; it means without purpose, and has nothing to do with idea.","definitionCN":"来自古英语中意为「空的、未用的」的词，意为无所事事地，与「观念」毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"preferably","ipa":"/prɪˈfərəbli/","tag":"near meaning","definition":"Marks which option is preferred among several, not the best possible state.","definitionCN":"标记若干选项中被偏爱的一个，而不是可能的最佳状态。"},{"word":"in theory","ipa":"/ɪn ˈθɪəri/","tag":"near meaning","definition":"According to principle, whether or not it can be achieved in practice.","definitionCN":"指依原理而言，无论实践中能否做到。"},{"word":"in an ideal world","ipa":"/ɪn ən aɪˈdiːl wɜːld/","tag":"near meaning","definition":"Sets out a perfect situation while openly admitting that it is not this world.","definitionCN":"摆出一种完美情形，同时公开承认那不是现实世界。"},{"word":"if possible","ipa":"/ɪf ˈpɒsəbl/","tag":"near meaning","definition":"A practical request that asks for something within existing limits.","definitionCN":"一种务实的请求，要求在现有条件下尽量做到。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek verb of seeing, the idea family, and the draftsman's first drawing.","cn":"正常联想使用希腊语「看见」的动词、观念词族，以及绘图者画下的第一稿。"},"normal":[{"en":"Idein is to see, idea is what is seen, and ideally is how things look at their best.","cn":"「看见」是看，「观念」是被看见的东西，「理想地」就是事物最好时的样子。"},{"en":"Idea, ideal, idealism, idealist and ideally are one family, one root, five jobs.","cn":"观念、理想的、理想主义、理想主义者与理想地：一个词族，一个词根，五份差事。"},{"en":"The draftsman's first drawing is the word's home: perfect lines before the site survey.","cn":"绘图者的第一稿是这个词的家乡：先有完美的线，才有场地的勘测。"},{"en":"Put it before would and a demand turns into a wish.","cn":"把它放在虚拟式前面，要求就变成愿望。"},{"en":"Ideally, yes is an agreement with a door left open.","cn":"「理想上可以」是一句留了门的同意。"}],"abstract":[{"en":"An ideal is a map drawn before anyone has walked the ground.","cn":"理想是一张在无人走过之前就画好的地图。"},{"en":"The word describes the best case and quietly admits it is not the case.","cn":"这个词描述最好的情形，又悄悄承认它不是眼前的情形。"},{"en":"To name the best is not to promise it, and the word knows the difference.","cn":"说出最好，并不等于承诺最好；这个词懂这个区别。"}]},"examples":[{"en":"Ideally, the two departments would share a single archive.","cn":"最理想的是，两个部门共用一个档案库。"},{"en":"The hall is ideally suited for small concerts.","cn":"这个厅非常适合举办小型音乐会。"},{"en":"Ideally, we would finish the survey before the end of the month.","cn":"最理想的是，我们能在月底之前完成勘测。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「爱迪阿里」——先在纸上画一个最完美的版本，再谈现实：理想上、最好","word":"ideally"},"root":"希腊语 idein「看见」→ idea「形相、观念」→ 拉丁语 idea → 法语 idéal → 英语 ideal，再加副词词尾构成。直接来源清楚；副词首见年代为约数。","sensesIntro":{"en":"Nine senses differ by what the ideal is doing: describing the best state, naming a goal, modifying a fit, opening a plan, softening a request, setting an opening price, granting in a short reply, and the two boundaries against preferably and in theory.","cn":"九个义项按「理想在做什么」分开：描述最佳状态、指出目标、修饰契合程度、开启计划、软化请求、设定开价、简短认可，以及与「优先」「理论上」的两处分界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a perfect layout drawn first on tracing paper, with the buildable part pencilled in beside it.","cn":"核心意象：先在描图纸上画出完美的布局，再在旁边用铅笔标出现实可建的部分。"},"chain":["AN IMAGE","A STANDARD","THE BEST CASE","AIMED AT","SOFTENED WISH","NOT YET REAL"],"branches":[{"senses":"01 · 03","en":"THE BEST STATE AND THE PERFECT FIT: conditions without obstacles, and a placement that suits a purpose exactly.","cn":"最佳状态与完美契合：没有阻碍的条件，以及恰好适合用途的位置。"},{"senses":"02 · 04","en":"THE GOAL AND THE PLAN'S OPENING: a standard to reach, set out before the constraints.","cn":"目标与计划的开头：一个待达到的标准，在限制之前先说出来。"},{"senses":"05 · 06","en":"THE SOFTENED REQUEST AND THE OPENING PRICE: a wish with a conditional, a figure named first.","cn":"软化的请求与开价：带条件式的愿望，以及最先报出的数字。"},{"senses":"07","en":"THE SHORT GRANT: yes, with the door left open.","cn":"简短认可：说是，同时把门留着。"},{"senses":"08 · 09","en":"THE TWO BOUNDARIES: the best state is not a preference, and a goal is not a principle.","cn":"两处分界：最佳状态不是偏好，目标也不是原理。"}]},"affixes":{"intro":{"en":"Ideally is a Greek noun of seeing, filtered through Latin and French, wearing an English adjective ending and an adverb ending.","cn":"这个词是一个经拉丁语与法语过滤的希腊「看见」名词，套着英语的形容词词尾与副词词尾。"},"latinIntro":{"en":"Greek supplies idein, idea and eidos; Latin borrowed idea and formed idealis, and French turned that into idéal before English took it.","cn":"希腊语提供了 idein、idea 与 eidos；拉丁语借入 idea 并构成 idealis，法语把它变成 idéal，英语随后接收。"},"items":[{"word":"idein","structure":"Greek verb","meaning":"to see","meaningCN":"看见","example":"The verb is the eye behind the whole family.","exampleCN":"这个动词是整个词族背后的那只眼睛。"},{"word":"idea","structure":"Greek noun","meaning":"form, appearance, mental image","meaningCN":"形相；外观；心中形象","example":"The noun shifts from what is seen to what is conceived.","exampleCN":"这个名词从「被看见的」转向「被想到的」。"},{"word":"eidos","structure":"Greek noun","meaning":"form, shape","meaningCN":"形相；形状","example":"A related noun names the visible shape itself.","exampleCN":"一个相关的名词指可见的形状本身。"},{"word":"idealis","structure":"Medieval Latin adjective","meaning":"existing in idea","meaningCN":"观念上的","example":"Latin forms the adjective for what exists as a pattern.","exampleCN":"拉丁语构成形容词，指作为模式而存在的东西。"},{"word":"ideal","structure":"English adjective","meaning":"the best possible, or existing only as a model","meaningCN":"理想的；只作为典范存在的","example":"English takes the adjective from French.","exampleCN":"英语从法语接收这个形容词。"},{"word":"-al","structure":"Latin adjective ending","meaning":"of or relating to","meaningCN":"属于……的","example":"It forms the adjective from the noun.","exampleCN":"它由名词构成形容词。"},{"word":"-ism","structure":"Greek noun ending through Latin","meaning":"a system or practice","meaningCN":"学说；体系","example":"It forms idealism, a system of thought.","exampleCN":"它构成 idealism，即一套思想体系。"},{"word":"-ist","structure":"Greek noun ending through Latin","meaning":"a person who practises","meaningCN":"从事……的人","example":"It forms idealist, a person who holds to ideals.","exampleCN":"它构成 idealist，即坚持理想的人。"},{"word":"-ize","structure":"Greek verb ending through Latin","meaning":"to make or treat as","meaningCN":"使……；按……对待","example":"It forms idealize, to treat something as perfect.","exampleCN":"它构成 idealize，即把某物看得完美。"},{"word":"-ly","structure":"English adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It forms the adverb that sets out the best case.","exampleCN":"它构成摆出最佳情形的副词。"}],"latinEntries":[{"word":"idein","structure":"Greek verb","meaning":"to see","meaningCN":"看见"},{"word":"idea","structure":"Greek noun borrowed into Latin","meaning":"form, appearance, mental image","meaningCN":"形相；观念"},{"word":"eidos","structure":"Greek noun","meaning":"form, shape","meaningCN":"形相；形状"},{"word":"idealis","structure":"Medieval Latin adjective","meaning":"existing in idea","meaningCN":"观念上的"}],"derivatives":[{"word":"idea","pos":"n.","zh":"由希腊语「形相、所见」经拉丁与法语借入，义为「观念」"},{"word":"ideal","pos":"adj.","zh":"由观念名词加形容词词尾构成，义为「理想的」"},{"word":"idealism","pos":"n.","zh":"由理想形容词加表示学说体系的名词尾构成，义为「理想主义」"},{"word":"idealist","pos":"n.","zh":"由理想形容词加表示人的名词尾构成，义为「理想主义者」"},{"word":"idealize","pos":"v.","zh":"由理想形容词加动词词尾构成，义为「把……理想化」"}]}}]);
